window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0236", [{"word":"be consistent with","ipa_uk":"/biː kənˈsɪstənt wɪð/","ipa_us":"/bi kənˈsɪstənt wɪð/","definition_zh":"与……一致；与……相符；符合；与……相合；与……相称","definition_en":"to agree with or match something such as evidence, a rule, a style or a forecast, so that no contradiction arises","core_image":"两张坐标纸叠在一起，一条曲线来自仪器记录，另一条来自推算，笔尖停在两线完全重合的位置","scene":"实验室的灯一直亮着，值班的人把温度记录纸与模拟输出并排铺在桌上，发现两条曲线的起伏几乎一模一样。Every reading in the log must be consistent with the simulation before the report is signed.","sceneCN":"这里指观测数据与模拟结果相合（第 1 个义项：与实测证据相符）；句意为在报告签字之前，日志里的每一次读数都必须与模拟结果相符。图中可辨识物件：温度记录纸、模拟曲线、签字笔、封存袋。","pos":[{"tag":"v. phr.","zh":"与……一致；符合（系表结构，时态由系动词承担，后接名词、代词或名词性从句）"},{"tag":"v. phr.","zh":"与……相称（后接风格、身份、惯例等抽象名词）"}],"collocations":[{"phrase":"be consistent with the evidence","zh":"与证据相符"},{"phrase":"be consistent with the rules","zh":"与规则一致"},{"phrase":"be consistent with earlier findings","zh":"与先前结论一致"},{"phrase":"be consistent with the theory","zh":"与理论相容"},{"phrase":"be consistent with expectations","zh":"与预期相符"},{"phrase":"be consistent with the standard","zh":"符合标准"},{"phrase":"be consistent with the record","zh":"与记录相符"}],"forms":[{"label":"单数主语现在时","form":"is consistent with"},{"label":"复数主语现在时","form":"are consistent with"},{"label":"单数主语过去时","form":"was consistent with"},{"label":"复数主语过去时","form":"were consistent with"},{"label":"进行体","form":"being consistent with"},{"label":"完成体","form":"been consistent with"}],"derivatives":[{"word":"consistency","pos":"n.","zh":"由形容词加表示性质的名词尾构成，义为「一致性；前后一贯」"},{"word":"consistent","pos":"adj.","zh":"去掉系动词后的形容词原形，义为「一致的；相符的」"},{"word":"consistently","pos":"adv.","zh":"由形容词加副词尾构成，义为「一贯地；始终如一地」"},{"word":"inconsistent","pos":"adj.","zh":"由否定前缀加形容词构成，义为「不一致的；自相矛盾的」"},{"word":"inconsistency","pos":"n.","zh":"由否定前缀加名词尾构成，义为「不一致之处」"}],"senses":[{"no":"01","title":"Matching the evidence","titleCN":"与证据相符","definition":"to agree with the observed data or the recorded facts","definitionCN":"与观测到的数据或已记录的事实相合","example":"Any explanation of the anomaly must be consistent with every measurement taken that night.","exampleCN":"对这一异常的任何解释，都必须与当晚取到的每一次测量相符。","why":"The core verb meant to stand together; a claim that stands together with the data is a claim the data will not knock down.","whyCN":"核心动词本义是「站在一起」；一个能与数据站在一起的说法，就是数据推不倒的说法。"},{"no":"02","title":"Following the same rule","titleCN":"与规则相符","definition":"to comply with an established rule, code or standard","definitionCN":"遵守既定的规则、规范或标准","example":"All new buildings should be consistent with the city's safety code.","exampleCN":"所有新建房屋都应与该市的安全规范相符。","why":"Rules are written to hold across many cases, so a single case that fits them can stand beside every other case.","whyCN":"规则要能覆盖许多情形，因此与规则相合的单个情形，可以和其余情形并排站住。"},{"no":"03","title":"Not contradicting itself","titleCN":"前后不自相矛盾","definition":"to be internally coherent, with no part denying another","definitionCN":"内部自洽，没有任何一部分否定另一部分","example":"A sound argument must be consistent with its own premises from the first line to the last.","exampleCN":"一个可靠的论证必须从第一行到最后一行都与自身的前提保持一致。","why":"Standing together also means standing together with oneself: the parts of a statement must not pull apart.","whyCN":"「站在一起」也包括与自己站在一起：一个说法的各部分不能各自扯开。"},{"no":"04","title":"Compatible with another theory","titleCN":"与另一理论相容","definition":"to be able to coexist with another account without contradiction","definitionCN":"能与另一种解释共存而不产生矛盾","example":"The two models can be consistent with each other only if the second assumption is dropped.","exampleCN":"只有放弃第二个假设，这两个模型才可能与彼此相容。","why":"Two accounts are compatible when both can stand on the same ground; where they cannot, one must give way.","whyCN":"两种解释能站在同一块地面上才叫相容；站不住的时候，必须有一方让位。"},{"no":"05","title":"In keeping with a style or character","titleCN":"与风格、身份相称","definition":"to match the tone, manner or character of something","definitionCN":"与某物的格调、做法或气质相配","example":"The plain wooden benches should be consistent with the meeting house's austere style.","exampleCN":"那些素木长凳应当与聚会所的简朴风格相称。","why":"Style is a kind of standing together too: each detail must stand beside the others without looking borrowed.","whyCN":"风格也是一种站在一起：每个细节都要与其余细节并排而不显得是借来的。"},{"no":"06","title":"In line with past practice","titleCN":"与惯例、旧例一致","definition":"to follow the custom or precedent set by earlier decisions","definitionCN":"沿用早先决定所立下的惯例或先例","example":"The committee's ruling will be consistent with its decisions over the past decade.","exampleCN":"委员会的裁决将与其过去十年的决定保持一致。","why":"Custom is continuity over time: a new decision stands together with the old ones, or the record looks broken.","whyCN":"惯例是时间上的连续：新决定要与旧决定站在一起，否则记录就显得断裂。"},{"no":"07","title":"Within the allowed tolerance","titleCN":"落在允许误差之内","definition":"to fall inside the permitted range of variation for a measurement","definitionCN":"测量值处在允许的变动范围之内","example":"A shaft that is slightly oval may still be consistent with the tolerance band.","exampleCN":"略微呈椭圆的轴，仍可能落在允许的误差带之内。","why":"In manufacture, agreement is numeric: the part stands within a band rather than exactly on a line.","whyCN":"在制造中，一致是数值上的：零件只要站进误差带，而不必正好压线。"},{"no":"08","title":"Matching a legal precedent","titleCN":"与法律先例一致","definition":"to be compatible with a constitution, statute or earlier court ruling","definitionCN":"与宪法、成文法或早先判决相兼容","example":"The new statute must be consistent with the constitution as interpreted by earlier courts.","exampleCN":"新法规必须与早先法院所解释的宪法条文相符。","why":"Law settles disputes by asking whether a new rule can stand beside the old ones without rewriting them.","whyCN":"法律判断争议的方式，是看新规则能否与旧规则并排站住而不必改写旧规则。"},{"no":"09","title":"Matching what was predicted","titleCN":"与预测相符","definition":"to agree with a forecast or a calculated expectation","definitionCN":"与预报或推算出的预期相合","example":"The cooling curve should be consistent with the model's prediction if the insulation is intact.","exampleCN":"如果保温层完好，冷却曲线就应与模型的预测相符。","why":"A prediction is a claim about a curve not yet drawn; agreement means the drawn curve stands where the claim said it would.","whyCN":"预测是对尚未画出的曲线所作的断言；相符意味着画出的曲线站到了断言所说的位置。"}],"etymology":{"intro":{"en":"The phrase is a grammatical frame around the Latin adjective consistent, which descended from the verb meaning to stand together. The frame itself is an English construction, and its first recorded use in academic prose is dated only approximately.","cn":"这个短语是围绕一个拉丁形容词搭起的语法框架，那个形容词出自表示「一起站立」的动词。框架本身是英语的构造，它在学术文章里最早出现的年代只能给约数。"},"items":[{"era":"LATIN SISTERE","en":"Sistere meant to stand, to place or to hold one's ground, and it supplied the standing image behind the whole family.","cn":"这个词意为「站立、安放、站住脚」，整个词族的「站」的意象都由它提供。"},{"era":"LATIN CONSISTERE","en":"Com- 'together' plus sistere produced consistere, to stand together, to hold firm, to remain in one place.","cn":"表示「一起」的前缀加「站立」，构成「站在一起、立稳、留在原处」的动词。"},{"era":"LATIN CONSISTENTIA","en":"The noun named the state of standing firm, and the participle described something that holds its ground.","cn":"相应的名词指「立稳的状态」，分词则形容「站得住的东西」。"},{"era":"ENGLISH CONSISTENT","en":"English took the adjective by way of French in the sixteenth century, first for things that hold together, then for statements that do not contradict each other.","cn":"英语在十六世纪经法语引入这个形容词，先指「结实地连在一起的东西」，后指「不自相矛盾的说法」。"},{"era":"PHRASE FIXED IN ACADEMIC PROSE","en":"The frame be plus the adjective plus with became the standard way to say that a finding, a rule or a style agrees with something else. The exact first citation of the frame is uncertain.","cn":"由系动词、形容词与介词构成的这个框架，成为表示「结论、规则或风格与某物相合」的标准说法。该框架最早的书证年代不确定。"}]},"similar":{"note":{"en":"The first group shares the same Latin standing root but splits into two unlike meanings; the second group holds ordinary ways of saying that two things agree.","cn":"第一组共享同一个拉丁「站立」词根，却分成两个完全不同的意思；第二组是表示「两物相合」的普通说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"consist of","ipa":"/kənˈsɪst əv/","tag":"same root, different meaning","definition":"Built on the same verb, it means to be made up of parts, not to agree with something. A report can consist of five chapters and still not be consistent with the evidence.","definitionCN":"由同一个动词构成，意思却是「由部分组成」，并非「与某物一致」。一份报告可以由五章构成，却仍与证据不符。"},{"word":"consistent","ipa":"/kənˈsɪstənt/","tag":"the adjective alone","definition":"The bare adjective describes a thing or a set of results that holds together; the phrase adds the second party that it agrees with.","definitionCN":"单独的形容词形容某物或某组结果自身站得住；短语则补出它所相合的那一方。"},{"word":"consistency","ipa":"/kənˈsɪstənsi/","tag":"the noun","definition":"The noun names the quality of agreement, as in the consistency of the results; it cannot take the whole phrase's object directly.","definitionCN":"名词指「一致」这一性质，如结果的一致性；它不能像短语那样直接带出所相合的对象。"},{"word":"inconsistent","ipa":"/ˌɪnkənˈsɪstənt/","tag":"negated form","definition":"The negative adjective says that two things cannot stand together, which is exactly what the phrase denies.","definitionCN":"否定形容词表示两物无法并立，正是这个短语所肯定的反面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"accord with","ipa":"/əˈkɔːd wɪð/","tag":"formal agreement","definition":"A formal verb phrase for agreeing with facts or principles; it is close in meaning but far less common in quantitative writing.","definitionCN":"正式地表示与事实或原则相合，意思接近，但在定量写作中远不如本短语常用。"},{"word":"align with","ipa":"/əˈlaɪn wɪð/","tag":"agreement of direction","definition":"Literally to bring into one line; used for plans and interests that point the same way, with less stress on factual proof.","definitionCN":"字面是「排成一条线」，多用于方向、利益一致，对事实证据的强调较弱。"},{"word":"conform to","ipa":"/kənˈfɔːm tə/","tag":"compliance","definition":"To follow a rule or pattern exactly; it stresses obedience to a standard rather than agreement among findings.","definitionCN":"指严格遵照规则或范式，强调对标准的服从，而不是结论之间的一致。"},{"word":"match","ipa":"/mætʃ/","tag":"plain everyday verb","definition":"The everyday verb for two things fitting each other; it is neutral in tone and lacks the phrase's academic register.","definitionCN":"日常表示两物相配的动词，语气中性，没有这个短语的学术语域。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two overlapping curves, the code book, the committee record and the tolerance band.","cn":"正常联想使用两条重合的曲线、规范手册、委员会记录与误差带四个场景。"},"normal":[{"en":"Two curves laid on one sheet: where they overlap, the reading agrees with the model.","cn":"两张曲线铺在同一张纸上：重叠之处，读数就与模型相符。"},{"en":"A new building checked against the code book, clause by clause.","cn":"新楼对着规范手册，一条一条核对。"},{"en":"A statement read twice: the second half must not deny the first.","cn":"一句话读两遍：后半句不能否定前半句。"},{"en":"A committee ruling placed beside ten years of earlier rulings.","cn":"把委员会的新裁决，摆到过去十年的旧裁决旁边。"},{"en":"A shaft measured against the tolerance band, not against a perfect line.","cn":"量轴时对着误差带，而不是对着一条完美的线。"}],"abstract":[{"en":"Agreement is not sameness: two things can differ in shape and still stand together.","cn":"一致不是相同：两样东西形状不同，仍可以站在一起。"},{"en":"Every field draws a line and then asks which results may stand on it.","cn":"每个领域都先画一条线，再问哪些结果可以站到线上。"},{"en":"A claim that agrees with everything agrees with nothing in particular.","cn":"与一切都相符的说法，其实不与任何具体事物相符。"}]},"examples":[{"en":"The isotope ratio must be consistent with the age assigned to the layer.","cn":"同位素比值必须与该层位所定的年代相符。"},{"en":"Her account of the meeting should be consistent with the minutes kept by the secretary.","cn":"她对那次会议的叙述，应与秘书所作的记录一致。"},{"en":"A policy can be consistent with the law and still be unpopular.","cn":"一项政策可以合乎法律，却依然不得人心。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「比 肯西斯滕特 威兹」：把「站在一起」记成两条线站到同一条线上——站得齐，才叫一致","word":"be consistent with"},"root":"核心动词出自拉丁语「一起站立」，由表示「共同」的前缀加表示「站立」的词根构成，本义是「立稳、站得住」，引申为「前后相合」。该短语是英语学术写作的固定框架，由系动词、形容词与介词三层组成，时态由系动词承担。","sensesIntro":{"en":"Nine senses move from proof to propriety: agreement with data, with a rule, with itself, with another theory, with a style, with past practice, with a tolerance band, with precedent, and with a forecast.","cn":"九个义项从证据走到得体：与数据相符、与规则相符、与自身自洽、与另一理论相容、与风格相称、与旧例一致、落在误差带内、合于判例、与预测相符。"},"semanticMap":{"core":{"en":"CORE IMAGE: two curves drawn on one sheet, one from an instrument and one from a calculation, meeting along the same line.","cn":"核心意象：两条曲线画在同一张纸上，一条来自仪器，一条来自推算，沿着同一条线重合。"},"chain":["STAND TOGETHER","MATCH THE DATA","FOLLOW THE RULE","HOLD WITHIN ITSELF","FIT THE SETTING","FIT THE FORECAST"],"branches":[{"senses":"01 · 09","en":"THE DRAWN LINE: a reading or a forecast must land where the claim said it would.","cn":"画出的线：读数或预测必须落在断言所说的位置。"},{"senses":"02 · 06","en":"THE STANDING RULE: a case fits the written code, or fits the unwritten custom of earlier cases.","cn":"站得住的规则：或合于成文规范，或合于旧例的不成文惯例。"},{"senses":"03 · 04","en":"THE SELF AND THE OTHER: a statement must not deny its own parts, and two accounts must not deny each other.","cn":"自身与对方：一个说法不能否定自己的各部分，两种解释也不能互相否定。"},{"senses":"05","en":"THE SETTING: style and character are agreement of tone rather than of fact.","cn":"场合：风格与身份的一致，是语气上的一致，而非事实上的相符。"},{"senses":"07 · 08","en":"THE BAND AND THE BENCH: a part sits inside a tolerance band, a statute sits beside earlier rulings.","cn":"误差带与判席：零件站进误差带，法规站到旧判决旁边。"}]},"affixes":{"intro":{"en":"This phrase is a Latin standing word inside an English frame; its family covers the verb, the adjective, the noun and their negatives.","cn":"这个短语把拉丁语的「站立」之词装进英语框架；词族覆盖动词、形容词、名词及各自的否定形式。"},"latinIntro":{"en":"Latin consistere and its noun consistentia supplied the adjective, and English added its own endings around them.","cn":"拉丁语的「一起站立」动词及其名词提供了形容词的底子，英语又在其外围加上自己的词尾。"},"items":[{"word":"con-","structure":"prefix","meaning":"together, with","meaningCN":"一起；共同","example":"It binds the parts into one standing whole.","exampleCN":"它把各部分绑成一个站立的整体。"},{"word":"sistere","structure":"Latin verb","meaning":"to stand, to hold one's ground","meaningCN":"站立；站住脚","example":"The standing image at the centre of the family.","exampleCN":"这是整个词族中心的「站立」意象。"},{"word":"consistere","structure":"Latin verb","meaning":"to stand together, hold firm","meaningCN":"站在一起；立稳","example":"The source of the English verb and adjective.","exampleCN":"英语动词与形容词的共同来源。"},{"word":"consistent-","structure":"Latin stem","meaning":"holding together","meaningCN":"连在一起而站得住的","example":"The stem that English took as an adjective.","exampleCN":"英语取作形容词的那个词干。"},{"word":"-ent","structure":"adjective ending","meaning":"having the quality of","meaningCN":"具有……性质的","example":"It turns the stem into a describing word.","exampleCN":"它把词干变成描述性的词。"},{"word":"-ence","structure":"noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It names the state of standing firm.","exampleCN":"它给「立稳的状态」命名。"},{"word":"-ency","structure":"noun ending","meaning":"state or quality, variant","meaningCN":"状态；性质（另一种词尾形式）","example":"It produces the modern noun of agreement.","exampleCN":"它构成现代表示「一致」的名词。"},{"word":"in-","structure":"negative prefix","meaning":"not","meaningCN":"不；非","example":"It reverses the adjective into its opposite.","exampleCN":"它把形容词翻成反义。"},{"word":"-ly","structure":"adverb ending","meaning":"in that manner","meaningCN":"以那种方式","example":"It produces the adverb of manner.","exampleCN":"它构成方式副词。"}],"latinEntries":[{"word":"consistere","structure":"Latin verb","meaning":"to stand together, hold firm","meaningCN":"站在一起；立稳"},{"word":"consistentia","structure":"Latin noun","meaning":"a standing firm, consistency","meaningCN":"立稳；一致性"},{"word":"consistens","structure":"Latin participle","meaning":"standing firm, agreeing","meaningCN":"站得住的；相合的"}],"derivatives":[{"word":"consistency","pos":"n.","zh":"由形容词加名词尾构成，义为「一致性」"},{"word":"consistent","pos":"adj.","zh":"形容词原形，义为「一致的」"},{"word":"consistently","pos":"adv.","zh":"由形容词加副词尾构成，义为「一贯地」"},{"word":"inconsistent","pos":"adj.","zh":"由否定前缀加形容词构成，义为「不一致的」"},{"word":"inconsistency","pos":"n.","zh":"由否定前缀加名词尾构成，义为「不一致之处」"}]}},{"word":"be derived from","ipa_uk":"/bi dɪˈraɪvd frəm/","ipa_us":"/bi dɪˈraɪvd frəm/","definition_zh":"源自；由……派生；从……提取；由……推导而来；取自；由……演变而来","definition_en":"to have something as one's source, whether a word, a substance, a conclusion, a species or a set of data","core_image":"一条河从远处的山脚出发，分成许多支流，最后每一股细流都能沿着水痕倒着追回同一个源头","scene":"词源课上，老师把一张写满古代写本的幻灯片推到学生面前，说明黑板上那个词并非本地自造。The term can be derived from an older trade word recorded in port ledgers of the fifteenth century.","sceneCN":"这里指词语在语言上可追溯到更早的来源（第 1 个义项：词或形式由某个更早的词语演变而来）；句意为这个词可以追溯到十五世纪港口账簿里记载的一个更早的行业用语。图中可辨识物件：写本幻灯片、粉笔写的词形、港口账簿、放大镜。","pos":[{"tag":"v. phr.","zh":"源自；由……派生（系表结构，后接来源名词，时态由系动词承担）"},{"tag":"v. phr.","zh":"由……推导、提取或演变而来（用于学术与工艺语境）"}],"collocations":[{"phrase":"be derived from a root","zh":"源自某个词根"},{"phrase":"be derived from plants","zh":"从植物中提取"},{"phrase":"be derived from the data","zh":"取自数据"},{"phrase":"be derived from an earlier model","zh":"承袭自更早的模型"},{"phrase":"be derived from a common ancestor","zh":"源自共同祖先"},{"phrase":"be derived from experience","zh":"来自经验"},{"phrase":"be derived from first principles","zh":"由基本原理推导"}],"forms":[{"label":"单数主语现在时","form":"is derived from"},{"label":"复数主语现在时","form":"are derived from"},{"label":"过去时","form":"was derived from"},{"label":"进行体","form":"being derived from"},{"label":"完成体","form":"been derived from"},{"label":"情态后原形","form":"be derived from"}],"derivatives":[{"word":"derive","pos":"v.","zh":"去掉系动词与介词后的核心动词，义为「取得；推导；起源」"},{"word":"derivation","pos":"n.","zh":"由动词加表示过程的名词尾构成，义为「推导；派生；词源」"},{"word":"derivative","pos":"n./adj.","zh":"由动词加表示「物」或「性质」的词尾构成，义为「派生词；衍生物；派生的」"},{"word":"derivable","pos":"adj.","zh":"由动词加表示「可……的」的形容词尾构成，义为「可推导的；可提取的」"},{"word":"derivational","pos":"adj.","zh":"由名词加形容词尾构成，义为「派生过程的」"}],"senses":[{"no":"01","title":"Traced back in language","titleCN":"语言上源自","definition":"to have an earlier word or form as one's linguistic source","definitionCN":"以某个更早的词或词形作为语言上的来源","example":"The technical term algebra can be derived from an Arabic word for reunion.","exampleCN":"术语「代数」可以追溯到阿拉伯语中表示「重新结合」的词。","why":"The core verb meant to draw off water from a channel, and a word drawn from an older word follows the same course.","whyCN":"核心动词本义是「从水道引水」，一个词从更早的词引出来，走的是同一条路。"},{"no":"02","title":"Extracted chemically","titleCN":"从原料中提取","definition":"to be obtained from a substance by a physical or chemical process","definitionCN":"通过物理或化学过程从某种物质中取得","example":"The yellow dye can be derived from the roots of a common roadside plant.","exampleCN":"这种黄色染料可以从一种常见路边植物的根中提取。","why":"The stream image is literal here: a substance is drawn out of a larger body, as water is led off from a channel.","whyCN":"这里用的是字面的引水意象：物质从更大的主体中被引出，如水从水道被引开。"},{"no":"03","title":"Inferred from premises","titleCN":"由前提推导而出","definition":"to be reached by logical steps from stated assumptions","definitionCN":"由已陈述的假设经逻辑步骤得出","example":"The final theorem must be derived from the three axioms stated at the beginning.","exampleCN":"最终的定理必须由开头陈述的三条公理推导出来。","why":"A conclusion is drawn out of premises the way water is drawn from a channel: the result was already implicit in the source.","whyCN":"结论从前提中被引出，正如水从水道被引开：结果本已隐含在来源之中。"},{"no":"04","title":"Evolved from an ancestor","titleCN":"由祖先进化而来","definition":"to have descended from an earlier species or population","definitionCN":"由更早的物种或种群演化而来","example":"Modern maize is believed to be derived from a wild grass of Central America.","exampleCN":"现代玉米被认为源自中美洲的一种野生禾草。","why":"A species is a later branch of an older line, so the modern form can be traced back along the same channel.","whyCN":"物种是旧谱系较晚的分支，现代形态因此能沿同一条水道回溯。"},{"no":"05","title":"Produced from raw material","titleCN":"由原料制成","definition":"to be manufactured from a particular starting material","definitionCN":"由某种起始材料加工制成","example":"Most of the paper in the archive can be derived from cotton rags rather than wood pulp.","exampleCN":"档案里的大部分纸张原料取自棉布碎料，而非木浆。","why":"Paper is drawn out of rags the way a product is drawn out of its raw material.","whyCN":"纸从碎布中被造出，正如产品从原料中被造出。"},{"no":"06","title":"Taken from a data source","titleCN":"数据取自","definition":"to come from a stated survey, sample or record","definitionCN":"来自明确交代的调查、样本或记录","example":"The figures in the table should be derived from the same survey sample.","exampleCN":"表中的数字应取自同一份调查样本。","why":"Numbers are drawn from one survey, and the survey is the channel they all flow from.","whyCN":"数字从同一份调查中取出，那份调查就是它们共同的渠道。"},{"no":"07","title":"Inherited from an earlier system","titleCN":"承袭自更早的制度","definition":"to be inherited from rules or arrangements established earlier","definitionCN":"承袭自更早确立的规则或安排","example":"The court's procedure may be derived from rules laid down in the previous century.","exampleCN":"该法院的程序可能承袭自上个世纪定下的规则。","why":"A rule inherited from an older code follows the same stream backwards to its source.","whyCN":"从旧法典承袭的规则，沿同一条水流回溯到它的源头。"},{"no":"08","title":"Adapted from an earlier work","titleCN":"改编自更早的作品","definition":"to be taken and reworked from an existing text, tune or design","definitionCN":"取自既有文本、曲调或设计并加以改写","example":"The opening theme can be derived from a folk song collected in the highlands.","exampleCN":"开场的主题可以追溯到高地采集来的一首民歌。","why":"A theme taken from a folk song is a branch diverted from an older channel.","whyCN":"取自民歌的主题，是从更早水道分流出来的一支。"},{"no":"09","title":"Caused by a deeper feeling","titleCN":"由更深层的原因而来","definition":"to arise as an effect of an underlying condition or feeling","definitionCN":"由某种潜在状况或情感所引出","example":"Much of the resentment may be derived from a sense that the promises were never kept.","exampleCN":"许多怨气可能来自一种「承诺从未兑现」的感受。","why":"A feeling can have a source as concrete as a stream, even when that source is an old wound.","whyCN":"情感也可以有像溪流一样具体的来源，哪怕那个来源是一道旧伤。"}],"etymology":{"intro":{"en":"The phrase rests on the verb derive, which Latin built from de- 'off, away' and rivus 'a stream'. The image is water drawn off from a channel, and every later sense keeps the direction of tracing back to a source.","cn":"这个短语的核心是表示「取得、引水」的动词，拉丁语用表示「离开」的前缀加表示「溪流」的名词构成。意象是从水道中把水引出，后来每个义项都保留「回溯到源头」的方向。"},"items":[{"era":"LATIN RIVUS","en":"Rivus meant a brook or a channel, and it also gave English river and rival.","cn":"这个词意为小溪或水道，英语的「河流」与「对手」也由它而来。"},{"era":"LATIN DERIVARE","en":"De- 'away from' plus rivus produced derivare, to lead water away from its channel, hence to divert or to trace an origin.","cn":"表示「离开」的前缀加「溪流」，构成「把水从水道引开」的动词，进而指「转移」与「追溯来源」。"},{"era":"LATIN DERIVATIO","en":"The noun first named the act of diverting a stream, then the act of showing where a word or thing came from.","cn":"相应的名词先指「引开水流」的动作，后指「说明词或物的来源」这一动作。"},{"era":"ENGLISH DERIVE, 14TH CENTURY","en":"English took the verb through French, using it for both water and words; the academic sense of logical derivation came later.","cn":"英语经法语引入这个动词，既用于水也用于词语；表示逻辑推导的学术义后来才出现。"},{"era":"PHRASE IN THE PASSIVE","en":"The passive frame became the standard way to state a source without naming who did the tracing. The exact first citation of the frame is uncertain.","cn":"由系动词、过去分词加介词构成的被动框架，成为不点明追溯者、只陈述来源的标准说法。该框架最早的书证年代不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin stream root or looks close to it; the second group holds other ways of naming a source.","cn":"第一组共享拉丁「溪流」词根或形近；第二组是其他交代来源的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"derive","ipa":"/dɪˈraɪv/","tag":"the bare verb","definition":"The active verb needs a subject: a researcher derives a formula, while the phrase describes the formula, not the researcher.","definitionCN":"主动动词需要主语：研究者推导公式，而本短语描述的是公式，不是研究者。"},{"word":"derivation","ipa":"/ˌderɪˈveɪʃn/","tag":"the noun","definition":"The noun names the act or the recorded lineage; it does not itself take the source as its object.","definitionCN":"名词指「推导」这一动作或记录下来的谱系，本身不直接带出来源对象。"},{"word":"derivative","ipa":"/dɪˈrɪvətɪv/","tag":"the product","definition":"A derivative is the thing produced, as a derived word or compound; the phrase names the relation, not the product.","definitionCN":"派生词或衍生物是被产生出来的东西；短语说的是关系，而不是产物。"},{"word":"river","ipa":"/ˈrɪvə/","tag":"same Latin root, no shared meaning","definition":"River comes from the same stream word but has nothing to do with derivation; the resemblance is etymological only.","definitionCN":"「河流」出自同一个「溪流」词，但与「派生」无关，相似只在词源层面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"originate from","ipa":"/əˈrɪdʒɪneɪt frəm/","tag":"beginning in a place","definition":"It points to the first appearance or birthplace of a thing, not to the steps by which it was obtained.","definitionCN":"强调某物最初出现的地点或起点，而非取得它的步骤。"},{"word":"stem from","ipa":"/stem frəm/","tag":"growing out of","definition":"A vivid phrase for a result that grows out of a cause, often used for problems and feelings.","definitionCN":"形象地表示结果由某原因长出，常用于问题与情绪。"},{"word":"come from","ipa":"/kʌm frəm/","tag":"plain everyday phrase","definition":"The ordinary phrase for a source; it carries no implication of method or logical steps.","definitionCN":"最普通的来源说法，不含方法或逻辑步骤之意。"},{"word":"be based on","ipa":"/bi beɪst ɒn/","tag":"resting upon","definition":"It says what something rests on, such as data or a model, rather than where it came from.","definitionCN":"说的是某物建立在什么之上，如数据或模型，而不是它从何而来。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the branching stream, the dye bath, the axiom list and the port ledger.","cn":"正常联想使用分叉的溪流、染缸、公理清单与港口账簿四个场景。"},"normal":[{"en":"A stream splits into channels: follow any channel backwards and you reach one spring.","cn":"一条溪分成多股水道：顺着任一股往回走，都能到同一个泉眼。"},{"en":"Dye boiled out of roots leaves the roots pale and the cloth yellow.","cn":"从根里煮出染料，根变白了，布变黄了。"},{"en":"Three axioms at the top of the page, one theorem at the bottom.","cn":"页面顶端三条公理，底端一条定理。"},{"en":"A word in a modern dictionary traced to a line in a fifteenth-century ledger.","cn":"现代词典里的一个词，追到十五世纪账簿上的一行字。"},{"en":"A table whose every number can be traced back to one survey sheet.","cn":"表中每个数字都能追回同一张调查表。"}],"abstract":[{"en":"To name a source is to shorten a history into one arrow.","cn":"指出一个来源，就是把一段历史压缩成一支箭头。"},{"en":"Nothing is derived from nothing: every lineage has at least one earlier line.","cn":"无中不能生有：每条谱系至少还有上一条线。"},{"en":"A word and a river share a root because both are things that flow away from a beginning.","cn":"词与河共享一个词根，因为两者都是从某个起点流走的东西。"}]},"examples":[{"en":"Many modern drugs can be derived from compounds first found in soil bacteria.","cn":"许多现代药物可以追溯到最初在土壤细菌中发现的化合物。"},{"en":"The estimate should be derived from the same sample used in the earlier study.","cn":"这一估计应取自早先研究使用的同一份样本。"},{"en":"A conclusion that can be derived from faulty premises may still be false.","cn":"由错误前提推导出的结论，仍可能是错的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「比 迪莱夫德 弗若姆」：把「引水离渠」记成一条河从源头分出去，凡是支流都能倒着追回泉眼——这就叫源自","word":"be derived from"},"root":"核心动词出自拉丁语，由表示「离开」的前缀加表示「溪流」的名词构成，本义是「把水从水道引开」，引申为「追溯来源、推导」。该短语为被动固定框架，由系动词、过去分词与介词构成，来源一方置于介词之后。","sensesIntro":{"en":"Nine senses follow one direction, backwards to a source: a word, a substance, a proof, a species, a material, a data set, an institution, a work of art, and a feeling.","cn":"九个义项都朝同一个方向回溯到源头：词语、物质、证明、物种、材料、数据、制度、作品与情感。"},"semanticMap":{"core":{"en":"CORE IMAGE: water led off from a channel, with every diverted stream still able to be traced back to the same headwater.","cn":"核心意象：水从水道被引开，每一股分流仍能倒着追回同一个源头。"},"chain":["DRAW OFF","TRACE BACK","NAME THE SOURCE","SHOW THE STEPS","CARRY THE LINEAGE","REACH THE ORIGIN"],"branches":[{"senses":"01 · 08","en":"THE TRACED LINE: a word or a tune is followed back to an older text.","cn":"回溯的线：词语或曲调被追回到更早的文本。"},{"senses":"02 · 05","en":"THE MATERIAL CHAIN: a substance or a product is drawn out of a starting material.","cn":"材料链：物质或产品从起始材料中被引出。"},{"senses":"03","en":"THE PROOF LADDER: a conclusion is reached step by step from stated premises.","cn":"证明的梯子：结论由已陈述的前提一步步达到。"},{"senses":"04","en":"THE FAMILY TREE: a living form descends from an earlier population.","cn":"家系树：现存的生物形态由更早的种群传下。"},{"senses":"06 · 07 · 09","en":"THE RECORD AND THE FEELING: numbers come from one survey, rules from an older code, resentment from an old wound.","cn":"记录与感受：数字来自同一份调查，规则来自旧法典，怨气来自旧伤口。"}]},"affixes":{"intro":{"en":"The family is built on a Latin stream word; the prefix points away from the channel and the endings build the acts and the products of tracing.","cn":"这个词族建立在拉丁语「溪流」一词上；前缀指「离开水道」，词尾则构成追溯的动作与产物。"},"latinIntro":{"en":"Latin rivus and derivare passed through French into English, where the noun and adjective endings were added.","cn":"拉丁语的「溪流」与「引出」经法语进入英语，英语又加上名词与形容词词尾。"},"items":[{"word":"de-","structure":"prefix","meaning":"away from, down from","meaningCN":"离开；从……而下","example":"It marks the water as led away from its channel.","exampleCN":"它标出水流被从水道引开。"},{"word":"rivus","structure":"Latin noun","meaning":"brook, channel","meaningCN":"小溪；水道","example":"The source image of flowing water.","exampleCN":"这是「流动之水」的源意象。"},{"word":"derivare","structure":"Latin verb","meaning":"to lead water off, to divert","meaningCN":"引水离开；转移","example":"The verb behind the whole English family.","exampleCN":"整个英语词族背后的动词。"},{"word":"derivation-","structure":"Latin stem","meaning":"a drawing off, a tracing","meaningCN":"引出；追溯","example":"The stem of the noun of process.","exampleCN":"表示过程的名词所用词干。"},{"word":"-ation","structure":"noun ending","meaning":"action or process","meaningCN":"动作；过程","example":"It forms the noun of the act of deriving.","exampleCN":"它构成表示「推导动作」的名词。"},{"word":"-ive","structure":"adjective and noun ending","meaning":"tending to; a thing that","meaningCN":"有……倾向的；……之物","example":"It forms the word for the produced item.","exampleCN":"它构成表示「被产出之物」的词。"},{"word":"-able","structure":"adjective ending","meaning":"able to be","meaningCN":"可被……的","example":"It forms the adjective for what can be derived.","exampleCN":"它构成「可被推导」的形容词。"},{"word":"-al","structure":"adjective ending","meaning":"relating to","meaningCN":"与……有关的","example":"It forms the adjective of the process.","exampleCN":"它构成与过程相关的形容词。"}],"latinEntries":[{"word":"rivus","structure":"Latin noun","meaning":"brook, channel","meaningCN":"小溪；水道"},{"word":"derivare","structure":"Latin verb","meaning":"to lead water off, divert","meaningCN":"引水离开；转移"},{"word":"derivatio","structure":"Latin noun","meaning":"a drawing off, a derivation","meaningCN":"引出；推导"}],"derivatives":[{"word":"derive","pos":"v.","zh":"核心动词，义为「取得；推导；起源」"},{"word":"derivation","pos":"n.","zh":"由动词加过程名词尾构成，义为「推导；词源」"},{"word":"derivative","pos":"n./adj.","zh":"由动词加表示产物的词尾构成，义为「派生词；衍生物」"},{"word":"derivable","pos":"adj.","zh":"由动词加「可……的」词尾构成，义为「可推导的」"}]}},{"word":"be exposed to","ipa_uk":"/bi ɪkˈspəʊzd tə/","ipa_us":"/bi ɪkˈspoʊzd tə/","definition_zh":"暴露于；接触到；受到……作用；面临……风险；置身于……之下","definition_en":"to be placed in contact with something that can act on a person, a material or an organisation, whether harmfully or instructively","core_image":"一扇仓门被拉开，外面的风、尘与光一齐涌进来，站在门口的人无处遮挡，只能让这些东西落在身上","scene":"老厂房的切割车间里，除尘罩一直没有装好，工人站在飞溅的碎屑中间作业。Workers in the older plant may be exposed to fine silica dust during the cutting process.","sceneCN":"这里指工人置身于有害粉尘之中（第 1 个义项：人体接触可能造成伤害的物质）；句意为在老厂区，工人在切割过程中可能接触到细小的硅尘。图中可辨识物件：切割机、悬浮粉尘、未装的除尘罩、口罩。","pos":[{"tag":"v. phr.","zh":"暴露于；接触到（系表结构，后接名词或动名词，时态由系动词承担）"},{"tag":"v. phr.","zh":"受到……作用；面临……风险（用于材料、组织与抽象事物）"}],"collocations":[{"phrase":"be exposed to radiation","zh":"受到辐射"},{"phrase":"be exposed to risk","zh":"面临风险"},{"phrase":"be exposed to the weather","zh":"受风吹日晒"},{"phrase":"be exposed to new ideas","zh":"接触新观念"},{"phrase":"be exposed to criticism","zh":"受到批评"},{"phrase":"be exposed to sunlight","zh":"暴露在阳光下"},{"phrase":"be exposed to infection","zh":"接触传染源"}],"forms":[{"label":"单数主语现在时","form":"is exposed to"},{"label":"复数主语现在时","form":"are exposed to"},{"label":"过去时","form":"was exposed to"},{"label":"进行体","form":"being exposed to"},{"label":"完成体","form":"been exposed to"},{"label":"情态后原形","form":"be exposed to"}],"derivatives":[{"word":"expose","pos":"v.","zh":"去掉系动词与介词后的核心动词，义为「使暴露；揭露」"},{"word":"exposure","pos":"n.","zh":"由动词加表示状态的名词尾构成，义为「暴露；曝光；接触量」"},{"word":"exposed","pos":"adj.","zh":"由动词的过去分词转作形容词，义为「暴露的；无遮蔽的」"},{"word":"exposable","pos":"adj.","zh":"由动词加「可……的」词尾构成，义为「可暴露的；可揭开的」"},{"word":"expositive","pos":"adj.","zh":"由动词加形容词尾构成，义为「说明性的」"}],"senses":[{"no":"01","title":"In contact with a hazard","titleCN":"置身于有害物之中","definition":"to be in contact with a substance or condition that may damage health","definitionCN":"接触可能损害健康的物质或环境","example":"Workers who may be exposed to asbestos must wear sealed suits.","exampleCN":"可能接触石棉的工人必须穿密闭防护服。","why":"The core verb meant to put something outside, and being outside is exactly how a hazard reaches the body.","whyCN":"核心动词本义是「把某物放到外面」，而「在外面」正是危险物触及身体的途径。"},{"no":"02","title":"Learning a language by contact","titleCN":"在语言环境中接触","definition":"to hear and use a language in daily surroundings rather than through formal study","definitionCN":"在日常环境中听到并使用某种语言，而非只靠正式学习","example":"Children can be exposed to two languages from the first year without confusion.","exampleCN":"儿童从第一年起就可以接触两种语言，而不会混淆。","why":"A child put outside the home's single language meets a second one, and contact is the whole method.","whyCN":"孩子被放到家庭单一语言之外，遇上第二种语言，接触本身就是全部方法。"},{"no":"03","title":"Meeting a new practice","titleCN":"接触到新做法","definition":"to come into contact with unfamiliar methods, tools or ideas","definitionCN":"接触到不熟悉的方法、工具或观念","example":"Villagers may be exposed to new farming methods through the extension officer.","exampleCN":"村民可能通过推广员接触到新的耕作方法。","why":"A villager brought outside the usual routine meets a method that was not available indoors.","whyCN":"村民被带到惯常做法之外，遇上一种在屋里得不到的方法。"},{"no":"04","title":"Acted on by heat, light or radiation","titleCN":"受到热、光、辐射作用","definition":"to be subjected to energy that changes the material","definitionCN":"受到会改变材料性质的能量的作用","example":"Film of this kind should not be exposed to direct sunlight for more than an hour.","exampleCN":"这类胶片受阳光直射不应超过一小时。","why":"Photography gave this sense its sharp edge: a sensitive surface left outside is changed by light itself.","whyCN":"摄影给了这一义项锋利的边界：感光面留在外面，就会被光本身改变。"},{"no":"05","title":"Carrying financial risk","titleCN":"承受金融风险","definition":"to hold assets or obligations whose value can move against one","definitionCN":"持有价值可能朝不利方向变动的资产或负债","example":"Firms that may be exposed to currency swings usually hedge their contracts.","exampleCN":"可能受到汇率波动冲击的公司，通常会为合同作对冲。","why":"Assets held in the open move with a market one does not control, exactly as a surface left outside moves with the weather.","whyCN":"暴露在外的资产随自己无法控制的市场起落，正如留在外面的表面随天气变化。"},{"no":"06","title":"Laid open to public view","titleCN":"暴露在公众视野中","definition":"to be made visible or known to people who had no right to see it","definitionCN":"被本无权看到的人看见或知道","example":"The private letters should never be exposed to public view without the family's consent.","exampleCN":"未经家属同意，这些私人信件绝不应暴露在公众眼前。","why":"Letters carried out of a private drawer are seen by eyes that were never meant to read them.","whyCN":"信件被从私人抽屉里拿出来，被本不该读它们的人看见。"},{"no":"07","title":"Given small amounts to build immunity","titleCN":"少量接触以建立免疫","definition":"to be brought into controlled contact with an antigen so the body learns to resist it","definitionCN":"与抗原发生受控接触，使身体学会抵抗","example":"Infants can be exposed to harmless proteins that train the immune system.","exampleCN":"婴儿可以接触无害的蛋白，以训练免疫系统。","why":"A small dose put into the body teaches it to meet the full dose later.","whyCN":"少量被放进身体，教它日后应对足量的侵袭。"},{"no":"08","title":"Opened to criticism or testing","titleCN":"受到检验与批评","definition":"to be placed where others may examine and challenge one's claims","definitionCN":"被置于他人可以审查和质疑其主张的位置","example":"Every claim in the paper must be exposed to independent scrutiny.","exampleCN":"论文中的每一项主张都必须接受独立审查。","why":"A claim brought into the open can be challenged by anyone who can reach it.","whyCN":"主张被带到明处，任何够得着它的人都能质疑。"},{"no":"09","title":"Damaged by an external condition","titleCN":"因外界条件而受损","definition":"to suffer slow damage from the surrounding air, water or salt","definitionCN":"因周围空气、水或盐分而缓慢受损","example":"The bronze plaques may be exposed to salt air and lose their polish.","exampleCN":"那些铜牌可能受含盐海风侵蚀而失去光泽。","why":"Metal left in salt air is slowly eaten by the very air it stands in.","whyCN":"留在含盐空气中的金属，被它身处其中的空气慢慢吃掉。"}],"etymology":{"intro":{"en":"The phrase is built on the verb meaning to put out, which Latin formed from ex- 'out' and ponere 'to place'. To expose is literally to put something out, and the phrase names what the thing is put out into.","cn":"这个短语的核心是表示「放到外面」的动词，拉丁语用表示「向外」的前缀加表示「放置」的动词构成。所谓使暴露，字面就是「把某物放到外面」，短语则补出「放到什么之中」。"},"items":[{"era":"LATIN PONERE","en":"Ponere meant to put or to place, and it stands behind position, compose, deposit and expose alike.","cn":"这个词意为「放置」，位置、组成、沉积与暴露诸词都出自它。"},{"era":"LATIN EXPONERE","en":"Ex- 'out' plus ponere produced exponere, to put out, to set forth, and also to abandon an infant to the elements.","cn":"表示「向外」的前缀加「放置」，构成「放出、摆出」的动词，也曾指把婴儿弃于户外。"},{"era":"FRENCH EXPOSER","en":"Old French reshaped the verb as exposer, to set out, to display, to leave unprotected.","cn":"古法语把这个动词改写为「摆出、展示、任其无遮」的意思。"},{"era":"ENGLISH EXPOSE, 15TH CENTURY","en":"English took the verb for laying something open to view or to danger; the passive frame followed naturally.","cn":"英语在十五世纪引入这个动词，指让某物敞开于视野或危险之中；被动框架随之自然形成。"},{"era":"SCIENTIFIC AND FINANCIAL SENSES","en":"From the nineteenth century the frame covered radiation dose, chemical contact and market risk. The exact first citation of the passive frame is uncertain.","cn":"从十九世纪起，这个框架覆盖辐射剂量、化学接触与市场风险。该被动框架最早的书证年代不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin placing verb and is constantly confused with it; the second group holds other ways of saying that something is acted on.","cn":"第一组共享拉丁「放置」动词，常被与之混淆；第二组是其他表示「受到作用」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"expose","ipa":"/ɪkˈspəʊz/","tag":"the active verb","definition":"The active verb names an agent who lays something open; the passive phrase removes the agent and keeps only the condition.","definitionCN":"主动动词点出「把某物敞开」的施事者；被动短语去掉施事者，只留下那种处境。"},{"word":"exposure","ipa":"/ɪkˈspəʊʒə/","tag":"the noun","definition":"The noun measures the contact as a quantity, as in a radiation exposure; the phrase describes the state, not the dose.","definitionCN":"名词把接触量化为数值，如辐射暴露量；短语描述状态，而不是剂量。"},{"word":"impose","ipa":"/ɪmˈpəʊz/","tag":"same Latin root, different prefix","definition":"Im- 'on' plus ponere means to place a burden on someone; it shares the root but has nothing to do with being laid open.","definitionCN":"表示「在上」的前缀加「放置」，意为把负担压在某人身上；词根相同，但与「敞开」无关。"},{"word":"compose","ipa":"/kəmˈpəʊz/","tag":"same Latin root, different prefix","definition":"Com- 'together' plus ponere means to put parts together; the shared root is placing, not exposing.","definitionCN":"表示「一起」的前缀加「放置」，意为把各部分放在一起；共享的只是「放置」这一动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"subject to","ipa":"/səbˈdʒekt tə/","tag":"put under a condition","definition":"A formal phrase for being made to undergo a treatment or rule; it often implies an authority doing the subjecting.","definitionCN":"正式地表示「使遭受某种处理或规则」，常暗示有权威在施加。"},{"word":"come into contact with","ipa":"/kʌm ˈɪntə ˈkɒntækt wɪð/","tag":"neutral contact","definition":"Neutral about harm: two things touch, and nothing is said about damage or learning.","definitionCN":"对是否有害保持中立：两物接触，不涉及损害或学习。"},{"word":"encounter","ipa":"/ɪnˈkaʊntə/","tag":"meet by chance","definition":"To meet something unexpectedly, often used of difficulties; it lacks the sense of prolonged contact.","definitionCN":"意外遇到某物，常用于困难；不含长时间接触之意。"},{"word":"face","ipa":"/feɪs/","tag":"have before one","definition":"To have a risk or a problem ahead; it stresses what one must deal with rather than what acts on one.","definitionCN":"面前存在风险或问题；强调必须应对，而不是受到作用。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the open warehouse door, the bilingual household, the film canister and the bronze plaque.","cn":"正常联想使用敞开的仓门、双语家庭、胶片暗盒与铜牌四个场景。"},"normal":[{"en":"A warehouse door pulled open: dust, wind and light all enter at once.","cn":"仓门一拉开，尘、风与光同时涌进来。"},{"en":"A child hears one language at the table and another at the door.","cn":"孩子在饭桌边听一种语言，在门口听另一种语言。"},{"en":"A film canister left on the sill turns milky by noon.","cn":"胶片暗盒放在窗台上，到中午就发白了。"},{"en":"A bronze plaque near the sea grows a green skin.","cn":"靠海的铜牌长出一层绿皮。"},{"en":"A paper read at a seminar before it is published.","cn":"论文先拿到研讨会上读，然后才发表。"}],"abstract":[{"en":"To be exposed is to lose the wall between oneself and the world.","cn":"被暴露，就是失去自己与世界之间的那堵墙。"},{"en":"Not all exposure harms: small doses can teach a body or a mind what to resist.","cn":"并非所有暴露都有害：小剂量能教身体或心智学会抵抗。"},{"en":"A claim kept indoors is safe; a claim exposed is either strengthened or broken.","cn":"主张关在屋里最安全；一旦暴露，不是变强就是被击碎。"}]},"examples":[{"en":"Samples left on the bench may be exposed to dust and should be capped at once.","cn":"留在实验台上的样品可能沾染灰尘，应立即加盖。"},{"en":"Students can be exposed to primary sources only after the archive grants permission.","cn":"学生只有在档案馆许可之后，才能接触原始文献。"},{"en":"A fund that may be exposed to sudden withdrawals needs a cash reserve.","cn":"可能遭遇突然赎回的基金，需要留有一笔现金储备。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「比 伊克斯波兹德 图」：把「放到外面」记成仓门大开，风尘一起落在身上——这就是暴露于","word":"be exposed to"},"root":"核心动词出自拉丁语，由表示「向外」的前缀加表示「放置」的动词构成，本义是「把某物放到外面、摆出来」，引申为「使无遮蔽、使遭受」。该短语为被动框架，由系动词、过去分词与介词构成，后面补出所暴露的对象。","sensesIntro":{"en":"Nine senses run from harm to instruction: a hazard, a language, a new method, radiant energy, market risk, public view, a vaccine dose, criticism, and slow corrosion.","cn":"九个义项从伤害走到教益：有害物、语言、新方法、辐射能量、市场风险、公众视野、疫苗剂量、批评与缓慢侵蚀。"},"semanticMap":{"core":{"en":"CORE IMAGE: a door opened onto a room with no wall, letting whatever is outside act on whoever stands within.","cn":"核心意象：门一开，房间没有墙，外面的东西直接作用在站在里面的人身上。"},"chain":["PUT OUTSIDE","LOSE THE WALL","TAKE WHAT ARRIVES","LEARN OR SUFFER","OPEN TO VIEW","CARRY THE RISK"],"branches":[{"senses":"01 · 09","en":"THE OPENING: a body or a metal face meets dust, salt or weather and pays for it.","cn":"敞口：身体或金属面遇到粉尘、盐分或天气，并为此付出代价。"},{"senses":"02 · 03","en":"THE WIDE WORLD: a learner meets a language or a method that was not in the room before.","cn":"广阔世界：学习者遇到原本不在屋里的语言或方法。"},{"senses":"04","en":"THE SENSITIVE SURFACE: energy itself changes the material left in the open.","cn":"感光面：能量本身改变了留在外面的材料。"},{"senses":"05","en":"THE LEDGER: value held in the open moves with a market one does not control.","cn":"账簿：暴露在外的价值，随自己无法控制的市场起落。"},{"senses":"06 · 07 · 08","en":"THE PUBLIC EYE: words, antigens and claims are all brought out where others may act on them.","cn":"公众之眼：言辞、抗原与主张都被带到别人可以作用的地方。"}]},"affixes":{"intro":{"en":"The family is built on the Latin verb for placing, with a prefix that points outward; the endings cover the act, the state and the thing placed.","cn":"这个词族建立在拉丁语「放置」动词上，前缀指向外；词尾覆盖动作、状态与被放置之物。"},"latinIntro":{"en":"Latin exponere and its participle expositus reached English through French, which supplied the modern spelling.","cn":"拉丁语的「放出」动词及其分词经法语进入英语，现代拼写由法语提供。"},"items":[{"word":"ex-","structure":"prefix","meaning":"out, outward","meaningCN":"向外；往外","example":"It marks the thing as put outside.","exampleCN":"它标出某物被放到外面。"},{"word":"ponere","structure":"Latin verb","meaning":"to put, to place","meaningCN":"放置；安放","example":"The placing verb behind the family.","exampleCN":"这是词族背后的「放置」动词。"},{"word":"exponere","structure":"Latin verb","meaning":"to put out, set forth","meaningCN":"放出；摆出","example":"The direct source of the English verb.","exampleCN":"英语动词的直接来源。"},{"word":"expositus","structure":"Latin participle","meaning":"put out, laid open","meaningCN":"被放出；被敞开","example":"The participle that became the English adjective.","exampleCN":"这个分词后来成为英语的形容词。"},{"word":"-ed","structure":"adjective ending","meaning":"having undergone","meaningCN":"已经受……的","example":"It turns the participle into a describing word.","exampleCN":"它把分词变成描述词。"},{"word":"-ure","structure":"noun ending","meaning":"act or state","meaningCN":"动作；状态","example":"It forms the noun of the state of being laid open.","exampleCN":"它构成表示「敞开状态」的名词。"},{"word":"-able","structure":"adjective ending","meaning":"able to be","meaningCN":"可被……的","example":"It forms the adjective for what can be exposed.","exampleCN":"它构成「可被暴露」的形容词。"},{"word":"-ive","structure":"adjective ending","meaning":"tending to","meaningCN":"有……性质的","example":"It forms the adjective of a setting-forth style.","exampleCN":"它构成表示「说明性」的形容词。"}],"latinEntries":[{"word":"ponere","structure":"Latin verb","meaning":"to put, place","meaningCN":"放置；安放"},{"word":"exponere","structure":"Latin verb","meaning":"to put out, set forth","meaningCN":"放出；摆出"},{"word":"expositus","structure":"Latin participle","meaning":"put out, laid open","meaningCN":"被放出；被敞开"}],"derivatives":[{"word":"expose","pos":"v.","zh":"核心动词，义为「使暴露；揭露」"},{"word":"exposure","pos":"n.","zh":"由动词加状态名词尾构成，义为「暴露；曝光」"},{"word":"exposed","pos":"adj.","zh":"由过去分词转作形容词，义为「无遮蔽的」"},{"word":"exposable","pos":"adj.","zh":"由动词加「可……的」词尾构成，义为「可暴露的」"}]}},{"word":"be responsible for","ipa_uk":"/bi rɪˈspɒnsəbl fə/","ipa_us":"/bi rɪˈspɑːnsəbl fər/","definition_zh":"对……负责；是……的原因；承担……费用；占据……比例；照管……","definition_en":"to hold a duty for something, to be the cause of it, or to answer for it, depending on what follows","core_image":"一张值班表贴在墙上，每一行工作后面都写着一个人的名字，名字旁边还留着出问题时该找谁的箭头","scene":"事故复盘会上，现场经理把每个环节逐条投到屏幕上，问到底该由谁对哪一步负责。The site manager must be responsible for every step of the repair before the plant reopens.","sceneCN":"这里指对一系列工作步骤承担责任（第 1 个义项：负有职责并对结果作出交代）；句意为在工厂重新开工之前，现场经理必须对维修的每一个步骤负责。图中可辨识物件：值班表、事故照片、白板上的箭头、签字笔。","pos":[{"tag":"v. phr.","zh":"对……负责；承担……的职责（系表结构，后接名词、动名词或从句）"},{"tag":"v. phr.","zh":"是……的原因；占……的比例（用于因果与数量说明）"}],"collocations":[{"phrase":"be responsible for the damage","zh":"对损坏负责"},{"phrase":"be responsible for the delay","zh":"是延误的原因"},{"phrase":"be responsible for safety","zh":"负责安全"},{"phrase":"be responsible for the outcome","zh":"对结果负责"},{"phrase":"be responsible for a large share","zh":"占很大比例"},{"phrase":"be responsible for the cost","zh":"承担费用"},{"phrase":"be responsible for a child","zh":"照管一个孩子"}],"forms":[{"label":"单数主语现在时","form":"is responsible for"},{"label":"复数主语现在时","form":"are responsible for"},{"label":"过去时","form":"was responsible for"},{"label":"进行体","form":"being responsible for"},{"label":"完成体","form":"been responsible for"},{"label":"情态后原形","form":"be responsible for"}],"derivatives":[{"word":"responsibility","pos":"n.","zh":"由形容词加表示性质的名词尾构成，义为「责任；职责」"},{"word":"responsive","pos":"adj.","zh":"由同一词干加表示倾向的形容词尾构成，义为「回应的；反应灵敏的」"},{"word":"response","pos":"n.","zh":"由动词加名词尾构成，义为「回答；反应」"},{"word":"responsibly","pos":"adv.","zh":"由形容词加副词尾构成，义为「负责任地」"},{"word":"irresponsible","pos":"adj.","zh":"由否定前缀加形容词构成，义为「不负责任的」"}],"senses":[{"no":"01","title":"Holding a duty or office","titleCN":"承担职责","definition":"to have a stated duty for a task, a place or a group of people","definitionCN":"对某项任务、某个场所或某群人负有明确职责","example":"The deputy director should be responsible for the daily running of the archive.","exampleCN":"副馆长应负责档案馆的日常运转。","why":"The word began as a promise to answer back, and a person who must answer for a duty is the first sense of the phrase.","whyCN":"这个词最初指「作出回应」的承诺，而必须为职责作出交代的人，正是这个短语的第一义。"},{"no":"02","title":"Causing a result","titleCN":"是……的原因","definition":"to be the cause that produced an observed effect","definitionCN":"作为造成某个已观察结果的原因","example":"A single faulty valve may be responsible for the pressure drop recorded at midnight.","exampleCN":"一个故障阀门就可能是午夜记录到的压力下降的原因。","why":"Once a result appears, the mind asks who must answer for it; cause and duty share the same frame.","whyCN":"结果一出现，人就会问该由谁为它作出交代；因果与责任因此共用同一个框架。"},{"no":"03","title":"Answerable for a failure","titleCN":"对过失负责","definition":"to bear the blame and the consequences of something that went wrong","definitionCN":"对出错之事承担过失与后果","example":"The contractor must be responsible for the cracks found in the foundation.","exampleCN":"承包商必须对地基中发现的裂缝负责。","why":"The answering frame turns a crack into a question that someone must answer.","whyCN":"「作答」的框架把一道裂缝变成必须有人回答的问题。"},{"no":"04","title":"Performing an ecological role","titleCN":"在生态过程中担当作用","definition":"to be the agent that carries out a natural function","definitionCN":"作为完成某项自然功能的媒介","example":"Bats can be responsible for pollinating several night-blooming desert plants.","exampleCN":"蝙蝠可能为几种夜间开花的沙漠植物完成授粉。","why":"The frame treats a natural process like an office: some creature holds the post of pollinator.","whyCN":"这个框架把自然过程当作一个岗位：某种生物担任了授粉的角色。"},{"no":"05","title":"Accounting for a share of a total","titleCN":"占……的比例","definition":"to account for a stated portion of a total amount","definitionCN":"在总量中占去所述的那一部分","example":"Road transport may be responsible for nearly a third of urban air pollution.","exampleCN":"道路交通可能占城市空气污染的近三分之一。","why":"A source that accounts for a third of a total is standing behind that share and answering for it.","whyCN":"占去总量三分之一的一个来源，就是站在那份份额背后并为它作答。"},{"no":"06","title":"Covering a cost","titleCN":"承担费用","definition":"to bear the expense of something","definitionCN":"负担某项开支","example":"The publisher should be responsible for the cost of reproducing the maps.","exampleCN":"出版商应承担复制地图的费用。","why":"The one who answers for a bill is the one who pays it.","whyCN":"为一张账单作答的人，就是付账的人。"},{"no":"07","title":"Caring for a dependent","titleCN":"照管受扶养者","definition":"to have the care of a child, an ill person or an elderly relative","definitionCN":"负有照顾孩子、病人或年长亲属的责任","example":"Adults may be responsible for elderly relatives as well as their own children.","exampleCN":"成年人可能要照管年长的亲属，还要照管自己的孩子。","why":"Care is a duty that cannot be handed back unanswered.","whyCN":"照护是一份不能推回去不作答的职责。"},{"no":"08","title":"Owning a task in a team","titleCN":"在团队中分管某一部分","definition":"to be the named person who owns one part of a shared job","definitionCN":"在共同工作中被指定为某一部分的负责人","example":"Each lab member must be responsible for one section of the safety report.","exampleCN":"每位实验室成员必须分管安全报告中的一个部分。","why":"A named section in a report is a post that one person holds and answers for.","whyCN":"报告中被点名的一节，就是一个人担任并为之作答的岗位。"},{"no":"09","title":"Being to blame in a moral sense","titleCN":"在道义上应受责备","definition":"to deserve blame for a wrong, even where no rule was broken","definitionCN":"即使未违反规则，也因过错而应受责备","example":"No one should be responsible for a mistake that the rules made unavoidable.","exampleCN":"不应让任何人对一个由规则本身造成的错误负责。","why":"Even without a written rule, the question of who answers for the harm still stands.","whyCN":"即使没有成文规则，「谁来为伤害作答」这个问题仍然站着。"}],"etymology":{"intro":{"en":"The phrase turns on the adjective of answering, from Latin respondere, to answer back. A responsible person is one who can answer when called, and the phrase names whatever that person must answer for.","cn":"这个短语的核心是表示「可作答的」形容词，出自拉丁语「回应、作答」的动词。负责任的人就是被问到时能作答的人，短语则补出他要为之作答的那件事。"},"items":[{"era":"LATIN SPONDERE","en":"Spondere meant to promise solemnly, and it stands behind sponsor and spouse as well as respond.","cn":"这个词意为「郑重许诺」，担保人、配偶与回应诸词都由它而来。"},{"era":"LATIN RESPONDERE","en":"Re- 'back' plus spondere produced respondere, to promise in return, hence to answer.","cn":"表示「回」的前缀加「许诺」，构成「回以许诺」的动词，进而指「回答」。"},{"era":"LATIN RESPONSUS","en":"The participle named a thing given back in answer, and French built responsable on it.","cn":"分词指「回以作答之物」，法语在其基础上造出「负责任的」一词。"},{"era":"ENGLISH RESPONSIBLE, 16TH CENTURY","en":"English used it first for persons who could be called to account, then for the things they answered for.","cn":"英语最初用它形容「可被要求作出交代的人」，随后也用于他们所交代的事情。"},{"era":"PHRASE OF DUTY AND CAUSE","en":"The frame split into a sense of duty and a sense of cause, since the same question who answers for this serves both. The exact first citation is uncertain.","cn":"这一框架分化出「职责」与「原因」两义，因为「这该由谁交代」这一问题两者都适用。最早书证年代不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin answering verb; the second group holds other ways of assigning duty or cause.","cn":"第一组共享拉丁「作答」动词；第二组是其他分派职责或说明原因的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"responsibility","ipa":"/rɪˌspɒnsəˈbɪləti/","tag":"the noun","definition":"The noun names the duty itself; the phrase puts a person or thing into that duty.","definitionCN":"名词指职责本身；短语则把人或物放进这份职责里。"},{"word":"responsive","ipa":"/rɪˈspɒnsɪv/","tag":"same root, different suffix","definition":"From the same answering root, it describes readiness to react, not a duty to answer.","definitionCN":"同出「作答」词根，却形容「反应灵敏」，而不是「有责任交代」。"},{"word":"response","ipa":"/rɪˈspɒns/","tag":"the noun of answering","definition":"It names the answer given; the phrase is about who owes the answer, not what the answer is.","definitionCN":"它指给出的答复；短语关心的是谁欠一个交代，而不是交代的内容。"},{"word":"sponsor","ipa":"/ˈspɒnsə/","tag":"same Latin promise word","definition":"It shares the promise root and means one who stands surety for another; it has no causal sense.","definitionCN":"共享「许诺」词根，指为他人作担保者；不含因果义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"in charge of","ipa":"/ɪn tʃɑːdʒ ɒv/","tag":"having control","definition":"It stresses control over a place or a team rather than answerability for an outcome.","definitionCN":"强调对场所或团队的控制，而不是对结果的交代。"},{"word":"accountable for","ipa":"/əˈkaʊntəbl fə/","tag":"must explain","definition":"It focuses on having to explain and justify a result, close to the duty sense but more formal.","definitionCN":"强调必须解释并为结果辩护，接近「职责」义，但更正式。"},{"word":"account for","ipa":"/əˈkaʊnt fɔː/","tag":"explain or make up","definition":"It can mean to explain a result or to form a share of a total, covering two of the phrase's senses without the personal duty.","definitionCN":"既可指解释某个结果，也可指占总量的一部分，涵盖短语的两个义项，却不含人身职责。"},{"word":"cause","ipa":"/kɔːz/","tag":"plain causal verb","definition":"The ordinary verb for producing an effect; unlike the phrase, it makes no claim about blame.","definitionCN":"表示「造成结果」的普通动词；与短语不同，它不涉及责备。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the duty rota, the faulty valve, the contractor's cracks and the pollinating bat.","cn":"正常联想使用值班表、故障阀门、承包商的裂缝与授粉的蝙蝠四个场景。"},"normal":[{"en":"A duty rota with a name beside every line, and an arrow for who to call when it fails.","cn":"值班表每行一个名字，旁边再画一个箭头，标出出错时该找谁。"},{"en":"One faulty valve, one pressure drop at midnight.","cn":"一个坏阀门，对应午夜的一次压力下降。"},{"en":"A crack in the foundation traced back to the contractor's pour.","cn":"地基裂缝追到承包商浇筑的那一天。"},{"en":"A bat that holds the night shift for desert flowers.","cn":"蝙蝠替沙漠的花值夜班。"},{"en":"A publisher that pays for the maps it chose to reprint.","cn":"出版商选择重印地图，就由它付这笔钱。"}],"abstract":[{"en":"Responsibility is a debt paid in answers rather than in money.","cn":"责任是一笔用「交代」而不是用钱偿还的债。"},{"en":"Cause and duty meet because both answer the same question: who is behind this?","cn":"因果与职责会合，因为两者都在回答同一个问题：这事背后是谁。"},{"en":"Naming a person responsible turns a diffuse failure into a place where repair can start.","cn":"指出负责人，就是把一团散开的失误收成一个可以开始修补的地点。"}]},"examples":[{"en":"Each regional office must be responsible for the accuracy of its own figures.","cn":"每个地区办事处必须对本机构数字的准确性负责。"},{"en":"A change in ocean temperature may be responsible for the shift in fish stocks.","cn":"海水温度的变化可能是鱼群移动的原因。"},{"en":"Households can be responsible for more than half of the water used in the city.","cn":"家庭可能占全市用水量的一半以上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「比 瑞斯庞瑟波 佛」：把「作答」记成值班表上每个名字都要在被问到时站出来——站出来答，就是负责","word":"be responsible for"},"root":"核心形容词出自拉丁语「回应、作答」的动词，由表示「回」的前缀加表示「郑重许诺」的词根构成，本义是「回以许诺」，引申为「可被要求作出交代」。该短语为系表框架，后接介词引出所负责的对象，职责义与因果义共用同一结构。","sensesIntro":{"en":"Nine senses split between duty and cause: an office, a cause, a fault, an ecological role, a share of a total, a cost, a dependent, a team section, and moral blame.","cn":"九个义项分居职责与因果两侧：职务、原因、过失、生态作用、总量份额、费用、受照管者、团队分工与道义责备。"},"semanticMap":{"core":{"en":"CORE IMAGE: a duty rota on the wall, every line carrying a name, and an arrow showing whom to call when that line goes wrong.","cn":"核心意象：墙上的值班表，每一行都写着一个名字，还有一个箭头指出这行出问题时该找谁。"},"chain":["PROMISE AN ANSWER","TAKE THE DUTY","STAND BEHIND THE RESULT","BEAR THE BLAME","COVER THE COST","ACCOUNT FOR A SHARE"],"branches":[{"senses":"01 · 08","en":"THE NAMED POST: a person or office is written beside the task and must answer for it.","cn":"具名的岗位：人或机构被写在任务旁边，必须为它作出交代。"},{"senses":"02 · 04","en":"THE HIDDEN HAND: a valve, a gene or a bat turns out to be what produced the result.","cn":"看不见的手：阀门、基因或蝙蝠原来是造成结果的那一方。"},{"senses":"03 · 09","en":"THE RECKONING: blame falls on a contractor's work or on a rule that made the error unavoidable.","cn":"清算：责备落在承包商的工程上，或落在一条使错误无可避免的规则上。"},{"senses":"05","en":"THE SHARE: one source of pollution or one sector of spending accounts for a measured portion.","cn":"份额：某一污染源或某一支出部门占去可测的一部分。"},{"senses":"06 · 07","en":"THE PURSE AND THE CRADLE: someone pays the printer, someone cares for the old and the young.","cn":"钱袋与摇篮：有人付印刷费，有人照管老人与孩子。"}]},"affixes":{"intro":{"en":"The family is built on a Latin promise-and-answer verb; the endings produce the duty, the answer, the adjective of reaction and their negatives.","cn":"这个词族建立在拉丁语「许诺与作答」的动词上；词尾造出职责、答复、反应形容词及各自的否定形式。"},"latinIntro":{"en":"Latin respondere and responsus reached French, which shaped responsable, and English added the noun and adverb endings.","cn":"拉丁语的「作答」动词与分词进入法语，法语造出「负责任的」这一形容词，英语再加名词与副词词尾。"},"items":[{"word":"re-","structure":"prefix","meaning":"back, in return","meaningCN":"回；回以","example":"It marks the answer as given back.","exampleCN":"它标出答复是「回过去」的。"},{"word":"spondere","structure":"Latin verb","meaning":"to promise solemnly","meaningCN":"郑重许诺","example":"The promise word behind the family.","exampleCN":"这是词族背后的「许诺」之词。"},{"word":"respondere","structure":"Latin verb","meaning":"to answer, to promise back","meaningCN":"作答；回以许诺","example":"The direct source of the English word.","exampleCN":"英语词的直接来源。"},{"word":"respons-","structure":"Latin stem","meaning":"given in answer","meaningCN":"回以作答的","example":"The stem English took for the adjective.","exampleCN":"英语取作形容词的词干。"},{"word":"-ible","structure":"adjective ending","meaning":"able to be","meaningCN":"可被……的","example":"It makes the word mean able to be called to answer.","exampleCN":"它使这个词表示「可被要求作答的」。"},{"word":"-ity","structure":"noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It forms the noun of duty.","exampleCN":"它构成表示「职责」的名词。"},{"word":"-ive","structure":"adjective ending","meaning":"tending to","meaningCN":"有……倾向的","example":"It forms the adjective of quick reaction.","exampleCN":"它构成表示「反应灵敏」的形容词。"},{"word":"ir-","structure":"negative prefix","meaning":"not","meaningCN":"不；非","example":"It reverses the adjective in the same way as the negative prefix of other Latin words.","exampleCN":"它像其他拉丁词一样，把形容词翻成反义。"}],"latinEntries":[{"word":"spondere","structure":"Latin verb","meaning":"to promise solemnly","meaningCN":"郑重许诺"},{"word":"respondere","structure":"Latin verb","meaning":"to answer, promise back","meaningCN":"作答；回以许诺"},{"word":"responsus","structure":"Latin participle","meaning":"answered, given back","meaningCN":"被回应的；回以的"}],"derivatives":[{"word":"responsibility","pos":"n.","zh":"由形容词加性质名词尾构成，义为「责任」"},{"word":"response","pos":"n.","zh":"由动词加名词尾构成，义为「答复；反应」"},{"word":"responsive","pos":"adj.","zh":"由词干加倾向形容词尾构成，义为「反应灵敏的」"},{"word":"irresponsible","pos":"adj.","zh":"由否定前缀加形容词构成，义为「不负责任的」"}]}},{"word":"bring about","ipa_uk":"/brɪŋ əˈbaʊt/","ipa_us":"/brɪŋ əˈbaʊt/","definition_zh":"促成；带来；引起；使发生；实现","definition_en":"to cause something to happen or to come into a desired state, usually through effort or a chain of effects","core_image":"一个人用撬棍顶住一块卡死的石板，先试力，再换支点，石板终于挪开，原来挡住的通道露了出来","scene":"旧城改造的会议室里，桌上摊开一份方案，主持人不断追问到底哪几项具体措施才能真正带来变化。No single subsidy can bring about the revival of a whole district on its own.","sceneCN":"这里指促成、使某种变化真正发生（第 1 个义项：通过措施使改革或变化实现）；句意为单靠一项补贴，无法独自促成整个城区的复兴。图中可辨识物件：改造方案、桌上的比例模型、标注箭头、会议记录。","pos":[{"tag":"v. phr.","zh":"促成；带来；引起（及物动词短语，宾语多为变化、结果或状态）"},{"tag":"v. phr.","zh":"使发生；实现（可用于中性或负面结果）"}],"collocations":[{"phrase":"bring about change","zh":"带来变化"},{"phrase":"bring about reform","zh":"促成改革"},{"phrase":"bring about a decline","zh":"造成下降"},{"phrase":"bring about peace","zh":"实现和平"},{"phrase":"bring about an improvement","zh":"带来改善"},{"phrase":"bring about a shift","zh":"促成转变"}],"forms":[{"label":"三单","form":"brings about"},{"label":"过去式","form":"brought about"},{"label":"过去分词","form":"brought about"},{"label":"现在分词","form":"bringing about"},{"label":"被动","form":"be brought about"}],"derivatives":[{"word":"bring","pos":"v.","zh":"短语的核心动词，义为「带来；使来到」"},{"word":"bringer","pos":"n.","zh":"由动词加表示施事者的词尾构成，义为「带来者」，较少用"},{"word":"bringing","pos":"n.","zh":"由动词加动名词词尾构成，义为「带来这一动作」"},{"word":"brought","pos":"v.","zh":"核心动词的过去式与过去分词形式"}],"senses":[{"no":"01","title":"Cause a reform","titleCN":"促成改革","definition":"to cause a change in policy, practice or structure to take place","definitionCN":"使政策、做法或结构发生改变","example":"A series of small tax changes can bring about a lasting shift in land use.","exampleCN":"一连串小幅税制调整，可能促成土地使用方式的持久转变。","why":"The verb meant to carry something forward; a reform is brought about when it is carried from intention into fact.","whyCN":"这个动词本义是「把某物带过来」；改革被「带来」，就是从意图被带到事实里。"},{"no":"02","title":"Produce an accident","titleCN":"引起事故","definition":"to cause an unintended and harmful event","definitionCN":"造成非本意且有害的事件","example":"A single loose bolt may bring about the collapse of the whole frame.","exampleCN":"一颗松动的螺栓，就可能造成整副框架的垮塌。","why":"A cause is carried into fact; a loose bolt carries a collapse into fact without anyone intending it.","whyCN":"原因被搬进事实；一颗松动的螺栓把垮塌搬进事实，而无人有意为之。"},{"no":"03","title":"Make a state real","titleCN":"使某种状态实现","definition":"to cause a desired condition such as peace or order to exist","definitionCN":"使和平、秩序等期望的状态真正存在","example":"Patient talks between the two communities may bring about a lasting peace.","exampleCN":"两个社区之间耐心的谈判，可能带来持久的和平。","why":"Peace is brought from intention into fact by talks that carry it forward.","whyCN":"和平被谈判从意图搬到事实。"},{"no":"04","title":"Enable a new market","titleCN":"催生新市场","definition":"to cause a new industry or market to come into being","definitionCN":"使新产业或新市场得以出现","example":"Cheap sensors can bring about a market for home water meters.","exampleCN":"廉价的传感器可以催生家用自来水表的市场。","why":"A cheap sensor carries a market from possibility into fact.","whyCN":"廉价传感器把市场从可能搬到事实。"},{"no":"05","title":"Change behaviour by policy","titleCN":"以政策改变行为","definition":"to cause people to act differently through a rule or an incentive","definitionCN":"通过规则或激励使人改变行为","example":"A modest fee may bring about a sharp fall in plastic bag use.","exampleCN":"一笔不大的收费，可能使塑料袋的使用量急剧下降。","why":"A fee carries a habit from intention into fact by changing what people do.","whyCN":"一笔收费通过改变人们的做法，把习惯从意图搬到事实。"},{"no":"06","title":"Trigger a bodily reaction","titleCN":"引起生理反应","definition":"to cause a physical response in a living body","definitionCN":"在生物体内引起生理上的反应","example":"The drug can bring about a rise in heart rate within minutes.","exampleCN":"这种药可能在几分钟内使心率上升。","why":"A drug carries a change into the body, where it stands as a measurable fact.","whyCN":"药物把一种变化搬进身体，在那里成为可测的事实。"},{"no":"07","title":"Close a settlement","titleCN":"促成和解","definition":"to cause an agreement or a settlement to be reached","definitionCN":"使协议或和解得以达成","example":"Neither side would bring about a settlement without a neutral chair.","exampleCN":"若没有中立的主持人，双方都不会促成和解。","why":"Two sides cannot carry a settlement into fact without a neutral hand.","whyCN":"没有中立之手，双方无法把和解搬到事实。"},{"no":"08","title":"Turn a season","titleCN":"带来季节转换","definition":"to cause a natural change of season or weather to arrive","definitionCN":"使季节或天气的自然转换到来","example":"Cool winds from the north can bring about an early frost in the valley.","exampleCN":"来自北方的凉风，可能给河谷带来早霜。","why":"Cool winds carry an early frost into fact in the valley.","whyCN":"凉风把早霜搬进河谷的事实。"},{"no":"09","title":"Change someone's mind","titleCN":"使某人转变看法","definition":"to cause a person to adopt a different view","definitionCN":"使某人接受另一种看法","example":"One well-documented case may bring about a change of view among the sceptics.","exampleCN":"一个证据充分的案例，可能使持怀疑态度的人改变看法。","why":"A documented case carries a person from one view to another.","whyCN":"一个有据的案例把人从一种看法搬到另一种看法。"}],"etymology":{"intro":{"en":"The phrase joins an Old English verb meaning to carry or fetch with a particle meaning around or to a point. What is brought about is carried around from intention until it stands as a fact.","cn":"这个短语由古英语中表示「携带、取来」的动词加一个表示「转到、达到某点」的虚词构成。被「带来」的东西，就是从意图被搬到事实那一端。"},"items":[{"era":"OLD ENGLISH BRINGAN","en":"Bringan meant to carry, to fetch or to lead something to a place, and it is recorded from the earliest English.","cn":"这个词意为「携带、取来、把某物带到某处」，自英语最早文献即有记录。"},{"era":"OLD ENGLISH ABUTAN","en":"The particle came from a word meaning around or on the outside, built from a- plus butan 'outside'; it supplied the sense of turning something toward a point.","cn":"这个虚词出自表示「环绕、在外」的词，由加强成分加「外面」构成，提供了「把某物转到某一点」的意思。"},{"era":"ENGLISH BRING ABOUT, 17TH CENTURY","en":"The combination with the particle appears in the seventeenth century, first in nautical and then in general use for causing an event.","cn":"这个动词与虚词的组合在十七世纪出现，先用于航海，后泛指「使事件发生」。"},{"era":"SENSE WIDENED","en":"From causing a ship to turn it widened to causing reforms, accidents, markets and moods; the object may be good or bad.","cn":"从「使船转向」扩及促成改革、事故、市场与情绪；宾语可好可坏。"},{"era":"ORIGIN OF THE VERB","en":"Source uncertain: the deeper origin of the Old English verb is not established, and the forms offered for it in older comparative work are reconstructions. The first date of the phrase itself is approximate.","cn":"来源不确定：该古英语动词的更早来源尚无定论，旧比较语言学为其拟出的形式属于重构；短语本身的首见年代亦为约数。"}]},"similar":{"note":{"en":"The first group shares the carrying verb; the second group holds other ways of saying that something was caused.","cn":"第一组共享「携带」动词；第二组是其他表示「造成某事」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bring","ipa":"/brɪŋ/","tag":"the bare verb","definition":"The bare verb needs a concrete object, as bring a chair; the phrase needs an event or a state as its object.","definitionCN":"单独使用时多带具体宾语，如搬一把椅子；短语的宾语则是事件或状态。"},{"word":"bring up","ipa":"/brɪŋ ʌp/","tag":"different particle","definition":"It means to raise a child or to raise a topic; the particle changes the direction from around to upward.","definitionCN":"意为「抚养孩子」或「提出话题」；虚词把方向从「转到」改成「向上」。"},{"word":"bring in","ipa":"/brɪŋ ɪn/","tag":"different particle","definition":"It means to introduce, to earn or to recruit; it shares the carrying verb but not the sense of causing an event.","definitionCN":"意为「引进、赚得、招募」；共享「携带」动词，但不含「使事件发生」。"},{"word":"bring out","ipa":"/brɪŋ aʊt/","tag":"different particle","definition":"It means to reveal a quality or to publish a product; the direction is outward, not around to a result.","definitionCN":"意为「显出某种特质」或「出版产品」；方向是向外，而不是转到某个结果。"}]},{"heading":"NEAR MEANING","entries":[{"word":"give rise to","ipa":"/ɡɪv raɪz tə/","tag":"set off, often unintended","definition":"It stresses a causal spark that sets something going, and it often suits problems that were not planned.","definitionCN":"强调「点燃」式的起因，常适合并非有意造成的问题。"},{"word":"lead to","ipa":"/liːd tə/","tag":"point toward a result","definition":"It follows a chain of steps toward an outcome; it stresses the path rather than the act of producing.","definitionCN":"强调沿着步骤通向结果，重点在路径而不在「制造」这一动作。"},{"word":"cause","ipa":"/kɔːz/","tag":"plain causal verb","definition":"The general verb for producing an effect; it is neutral and needs no particle.","definitionCN":"表示「造成结果」的通用动词，语气中立，不需虚词。"},{"word":"produce","ipa":"/prəˈdjuːs/","tag":"bring forth","definition":"It suggests an effect that follows from a process, as a factory produces goods; it is less idiomatic for reforms.","definitionCN":"暗示结果由过程产出，如工厂产出货物；用于「改革」不如本短语自然。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the crowbar and stone slab, the loose bolt, the peace talks and the cheap sensor.","cn":"正常联想使用撬棍与石板、松动的螺栓、和谈与廉价传感器四个场景。"},"normal":[{"en":"A crowbar against a jammed slab: force, a new pivot, and the passage opens.","cn":"撬棍顶住卡死的石板：换一次支点，通道就开了。"},{"en":"One loose bolt under a steel frame.","cn":"钢架下面一颗松动的螺栓。"},{"en":"Two communities talking until the shooting stops.","cn":"两个社区一直谈到枪声停下。"},{"en":"A ten-dollar sensor that creates a market nobody had before.","cn":"一只十美元的传感器，造出从前没有的市场。"},{"en":"A small fee that empties the plastic bag drawer.","cn":"一笔小收费，把塑料袋抽屉清空。"}],"abstract":[{"en":"To bring about is to move a thing from the possible to the actual.","cn":"促成，就是把一件事从「可能」搬到「实际」。"},{"en":"Causes are carried, not conjured: something must do the carrying.","cn":"原因是被搬来的，不是被念来的：总得有什么在搬。"},{"en":"The same verb serves reforms and accidents, because intention is not part of its meaning.","cn":"同一个动词既管改革也管事故，因为「意图」并不在它的含义里。"}]},"examples":[{"en":"Better drainage can bring about a fall in mosquito-borne illness.","cn":"改善排水可以促成蚊媒疾病的减少。"},{"en":"A single ruling may bring about a change in how the whole industry operates.","cn":"一项裁决可能促成整个行业运作方式的改变。"},{"en":"Years of patient work may bring about what one speech cannot.","cn":"多年耐心的努力，可能带来一次演讲带不来的东西。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「布林 阿包特」：把「带到面前」记成用撬棍把卡死的石板顶开——东西被搬到眼前，事情就成了","word":"bring about"},"root":"核心动词出自古英语，意为「携带、取来、把某物带到某处」，其更早来源未有定论，旧比较语言学所拟形式属重构。短语由该动词加表示「转到、达到」的虚词构成，整体义为「把某事从可能搬到实际」。","sensesIntro":{"en":"Nine senses carry something into fact: a reform, an accident, a peace, a market, a habit, a pulse, a settlement, a season, and a changed mind.","cn":"九个义项把某物搬到事实里：改革、事故、和平、市场、习惯、脉搏、和解、季节与转变的看法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a crowbar against a jammed slab, force applied, a new pivot chosen, and the blocked passage opening.","cn":"核心意象：撬棍顶住卡死的石板，施力、换支点，被堵住的通道终于打开。"},"chain":["CARRY FORWARD","APPLY FORCE","MOVE THE BLOCK","REACH THE POINT","STAND AS FACT","CHANGE THE STATE"],"branches":[{"senses":"01 · 05","en":"THE PUBLIC FRAME: a tax rule or a fee moves many people at once.","cn":"公共框架：一条税规或一笔收费，同时推动许多人。"},{"senses":"02 · 08","en":"THE UNPLANNED EVENT: a bolt gives way, a frost arrives earlier than expected.","cn":"未计划的事件：螺栓失效，霜比预期来得早。"},{"senses":"03 · 07","en":"THE SETTLEMENT: talks and a neutral chair move two sides to one table.","cn":"和解：谈判与中立的主持把两方搬到同一张桌边。"},{"senses":"04 · 06","en":"THE NEW THING: a cheap sensor opens a market, a drug raises a pulse.","cn":"新生之物：廉价传感器打开市场，药物使脉搏加快。"},{"senses":"09","en":"THE MIND MOVED: one documented case shifts what a person believes.","cn":"被搬动的心：一个有据的案例改变了人的信念。"}]},"affixes":{"intro":{"en":"The phrase is a native English verb with a particle; the family is small and mostly verbal, while the particle supplies the direction.","cn":"这个短语是本族英语动词加虚词；词族很小，以动词为主，方向由虚词承担。"},"latinIntro":{"en":"No Latin source is involved in either part, so the Latin list is left empty and the native forms are given instead.","cn":"两部分都不涉及拉丁语来源，因此拉丁词表留空，改列本族形式。"},"items":[{"word":"bring","structure":"Old English verb","meaning":"to carry, to fetch","meaningCN":"携带；取来","example":"The native verb at the centre of the phrase.","exampleCN":"短语中心的本族动词。"},{"word":"about","structure":"Old English particle","meaning":"around, to a point","meaningCN":"环绕；转到某点","example":"It supplies the direction toward a result.","exampleCN":"它提供「转到某个结果」的方向。"},{"word":"-s","structure":"verb ending","meaning":"third person singular","meaningCN":"第三人称单数","example":"It marks a singular subject in the present.","exampleCN":"它标出现在时的单数主语。"},{"word":"-ing","structure":"verb ending","meaning":"ongoing action","meaningCN":"进行中的动作","example":"It forms the participle of the phrase.","exampleCN":"它构成短语的现在分词。"},{"word":"brought","structure":"irregular form","meaning":"past and past participle","meaningCN":"过去式与过去分词","example":"The verb keeps an old strong form.","exampleCN":"这个动词保留了古老的强变化形式。"},{"word":"bringer","structure":"noun suffix","meaning":"one who brings","meaningCN":"带来者","example":"It forms an agent noun, rarely used.","exampleCN":"它构成施事名词，较少使用。"},{"word":"bringing","structure":"gerund form","meaning":"the act of carrying","meaningCN":"携带这一动作","example":"It names the act itself.","exampleCN":"它给这个动作本身命名。"},{"word":"about","structure":"adverb use","meaning":"approximately, around","meaningCN":"大约；四处","example":"The same form has unrelated everyday uses.","exampleCN":"同一形式另有不相干的日常用法。"}],"latinEntries":[],"derivatives":[{"word":"bring","pos":"v.","zh":"短语的核心动词，义为「带来」"},{"word":"bringing","pos":"n.","zh":"由动词加动名词词尾构成，义为「带来这一动作」"},{"word":"bringer","pos":"n.","zh":"由动词加施事词尾构成，义为「带来者」，较少用"},{"word":"brought","pos":"v.","zh":"核心动词的过去式与过去分词"}]}},{"word":"carry out","ipa_uk":"/ˈkæri aʊt/","ipa_us":"/ˈkæri aʊt/","definition_zh":"实施；执行；进行；完成；履行；把……搬出去","definition_en":"to perform or complete a plan, a task, an order or an action, or literally to move something out of a place","core_image":"工头把图纸摊在钢梁上，一名工人照着编号逐段加固，另一名在旁边把已完成的项一格一格打勾","scene":"旧厂房里，工人按图纸逐项施工，监理拿着清单在旁边核对每一项是否真的落实。The crew will carry out the reinforcement exactly as the drawing shows.","sceneCN":"这里指按计划实施加固工程（第 1 个义项：把既定方案真正做出来）；句意为施工队将完全照图纸实施加固。图中可辨识物件：钢梁、图纸、打勾清单、扭矩扳手。","pos":[{"tag":"v. phr.","zh":"实施；执行；进行（及物动词短语，宾语多为计划、研究、命令、任务）"},{"tag":"v. phr.","zh":"把……搬出去（字面义，宾语为可移动的物件）"}],"collocations":[{"phrase":"carry out a plan","zh":"实施计划"},{"phrase":"carry out research","zh":"进行研究"},{"phrase":"carry out a survey","zh":"进行调查"},{"phrase":"carry out orders","zh":"执行命令"},{"phrase":"carry out reforms","zh":"推行改革"},{"phrase":"carry out repairs","zh":"进行维修"},{"phrase":"carry out a threat","zh":"把威胁付诸行动"}],"forms":[{"label":"三单","form":"carries out"},{"label":"过去式","form":"carried out"},{"label":"过去分词","form":"carried out"},{"label":"现在分词","form":"carrying out"},{"label":"被动","form":"be carried out"}],"derivatives":[{"word":"carrier","pos":"n.","zh":"由动词加表示施事者的词尾构成，义为「承运者；载体」"},{"word":"carriage","pos":"n.","zh":"由动词加表示行为或工具的名词尾构成，义为「运输；车厢」"},{"word":"carrying","pos":"n./adj.","zh":"由动词加动名词词尾构成，义为「搬运；承载的」"},{"word":"carriable","pos":"adj.","zh":"由动词加「可……的」词尾构成，义为「便于携带的」"}],"senses":[{"no":"01","title":"Put a plan into effect","titleCN":"实施计划","definition":"to perform a planned piece of work from start to finish","definitionCN":"把一项已规划的工作从头到尾做出来","example":"The city will carry out the drainage project in two stages.","exampleCN":"该市将分两个阶段实施排水工程。","why":"The verb meant to move something along, and a plan is carried until it stands completed rather than only written.","whyCN":"核心动词本义是「把某物搬运向前」，计划被「搬」到完工为止，而不是停在纸面上。"},{"no":"02","title":"Conduct a study","titleCN":"进行研究或调查","definition":"to perform a systematic inquiry or measurement","definitionCN":"开展系统的调查或测量","example":"The team must carry out a survey of every household in the valley.","exampleCN":"该团队必须对河谷中的每一户进行调查。","why":"A survey is carried outward into every household until the plan stands completed.","whyCN":"调查被搬到每一户人家，直到计划完成。"},{"no":"03","title":"Fulfil a promise or an order","titleCN":"履行承诺、执行命令","definition":"to act on a commitment or an instruction that has been given","definitionCN":"把已作出的承诺或已下达的指示做出来","example":"Officers should carry out the order even when they doubt its wisdom.","exampleCN":"即使对命令是否明智存疑，官员也应执行该命令。","why":"An order is only words until it is carried outward into action.","whyCN":"命令在被搬进行动之前只是话。"},{"no":"04","title":"Complete a task to the end","titleCN":"把任务做到完成","definition":"to finish a piece of work rather than leave it partly done","definitionCN":"把一件工作做完，而不是半途停下","example":"Volunteers can carry out the whole restoration in a single summer.","exampleCN":"志愿者可以在一个夏天内完成整个修复工作。","why":"The outward push ends only when the last piece is finished.","whyCN":"向外的推力直到最后一件做完才停止。"},{"no":"05","title":"Mount a military action","titleCN":"实施军事行动","definition":"to perform a raid, an attack or a patrol as a unit","definitionCN":"以部队为单位实施突袭、攻击或巡逻","example":"The patrol may carry out a raid on the depot before dawn.","exampleCN":"巡逻队可能在黎明前对仓库实施突袭。","why":"A unit carries an action outward beyond its own lines.","whyCN":"部队把行动搬到自己防线之外。"},{"no":"06","title":"Remove something physically","titleCN":"把东西搬出去","definition":"literally to take an object out of a room or a building","definitionCN":"字面地把物件从房间或建筑中搬走","example":"Two workers will carry out the broken crates before the floor is washed.","exampleCN":"两名工人会在洗地之前把破木箱搬出去。","why":"This is the oldest layer of the phrase: the object is carried and the direction is outward.","whyCN":"这是短语最古老的一层：物件被搬动，方向朝外。"},{"no":"07","title":"Make a threat real","titleCN":"把威胁付诸行动","definition":"to actually do what one has warned others one would do","definitionCN":"真的做出此前警告过要做的事","example":"He may carry out his threat to publish the letters.","exampleCN":"他可能真的兑现公布那些信件的威胁。","why":"A threat becomes real only when it is carried out into the act it named.","whyCN":"威胁只有在被搬成它所说的那个行动时才变真。"},{"no":"08","title":"Apply a reform at every level","titleCN":"把改革贯彻到基层","definition":"to put a new rule into practice through every level of an organisation","definitionCN":"使新规则在组织的每一层都落到实处","example":"Local offices must carry out the new rules without adding their own conditions.","exampleCN":"地方办事处必须执行新规则，不得自行附加条件。","why":"A rule is carried outward through every office until the last one acts on it.","whyCN":"规则被搬到每一个办事处，直到最后一个也照它行事。"},{"no":"09","title":"Execute a commercial transaction","titleCN":"执行交易","definition":"to complete a sale or an order in a market","definitionCN":"在市场里完成一笔买卖或订单","example":"The broker will carry out the sale at the opening price.","exampleCN":"经纪人将按开盘价执行这笔卖出。","why":"A trade is carried to its close when the order is executed at the stated price.","whyCN":"交易在按约定价格执行时被搬到终点。"}],"etymology":{"intro":{"en":"The phrase pairs a verb that reached English from the language of carters with a native particle of direction. What is carried out is moved from inside to outside, and the figurative senses keep that outward push.","cn":"这个短语把经赶车人之语进入英语的动词，与本族表示方向的虚词配在一起。被「搬出去」的东西由内到外，比喻义也保留这股向外的推力。"},"items":[{"era":"GAULISH CARRUS","en":"A Gaulish word for a wheeled cart was taken into Latin as carrus, and it stands behind carriage, cargo and career.","cn":"高卢语中表示带轮车子的词被拉丁语吸收，马车、货物与「生涯」诸词都由它而来。"},{"era":"LATE LATIN CARRICARE","en":"Carricare meant to load a cart, and it produced the verb that French reshaped as carier, to carry.","cn":"这个词意为「把货装上车」，由此产生的动词被法语改写成「运送」。"},{"era":"OLD NORTH FRENCH CARIER","en":"English took the verb through the northern French form in the fourteenth century.","cn":"英语在十四世纪经北方法语的形式引入这个动词。"},{"era":"NATIVE PARTICLE","en":"The particle is native English and means outward or away from the inside; it gives the phrase its direction.","cn":"虚词是本族英语，意为「向外、离开里面」，为短语提供了方向。"},{"era":"PHRASE FROM THE SIXTEENTH CENTURY","en":"The combination first appears in the sixteenth century with the literal sense, and the sense of performing a plan follows. The exact first citation is uncertain, and the deeper origin of the cart word is not established.","cn":"这个组合在十六世纪先以字面义出现，随后才有「实施计划」的意思。最早书证年代不确定；表示「车」的那个词更早的来源亦无定论。"}]},"similar":{"note":{"en":"The first group shares the carrying verb with a different particle each time; the second group holds verbs of performing a task.","cn":"第一组共享「搬运」动词，但各自的虚词不同；第二组是表示「执行任务」的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"carry","ipa":"/ˈkæri/","tag":"the bare verb","definition":"The bare verb needs a concrete object and no direction, as carry a bag; it says nothing about completing a plan.","definitionCN":"单独使用时带具体宾语，如提一个包，不含方向，也不表示完成计划。"},{"word":"carry on","ipa":"/ˈkæri ɒn/","tag":"different particle","definition":"It means to continue rather than to perform; the particle points forward in time, not outward.","definitionCN":"意为「继续」，而不是「执行」；虚词指时间上的向前，而非向外。"},{"word":"carry through","ipa":"/ˈkæri θruː/","tag":"different particle","definition":"It means to complete something despite difficulty, close to the fourth sense but with an added note of endurance.","definitionCN":"意为「排除困难坚持完成」，接近第四个义项，但多了一层「撑住」的意味。"},{"word":"carry over","ipa":"/ˈkæri ˈəʊvə/","tag":"different particle","definition":"It means to transfer something to another period or account, a movement across, not an execution.","definitionCN":"意为把某物结转到另一期或另一账目，是横向转移，不是执行。"}]},{"heading":"NEAR MEANING","entries":[{"word":"implement","ipa":"/ɪmˈplɪment/","tag":"put into practice","definition":"A formal verb for making a policy or system operate; it stresses the machinery of putting something into effect.","definitionCN":"正式地表示使政策或制度运转，强调「使之生效」的机制。"},{"word":"conduct","ipa":"/kənˈdʌkt/","tag":"run an inquiry","definition":"The usual verb for running a study, a survey or an orchestra; it fits research better than repairs.","definitionCN":"常用于「进行研究、调查或指挥乐队」，用于研究比用于维修更合适。"},{"word":"execute","ipa":"/ɪˈsekjuːt/","tag":"perform formally","definition":"A formal verb for performing a plan or a legal act; it also carries the separate meaning of putting someone to death.","definitionCN":"正式地表示执行计划或法律行为；另有「处死」这一不相干的含义。"},{"word":"perform","ipa":"/pəˈfɔːm/","tag":"do a task","definition":"A general verb for doing a task or a role; it lacks the sense of completing something previously planned.","definitionCN":"泛指完成任务或扮演角色，不含「把既定计划做完」之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the reinforcement drawing, the household survey, the order on the desk and the crates by the door.","cn":"正常联想使用加固图纸、入户调查、桌上的命令与门边的木箱四个场景。"},"normal":[{"en":"A drawing on a steel beam, a torque wrench, and a checklist filling with ticks.","cn":"钢梁上摊着图纸，扭矩扳手转动，清单上的勾一格一格填满。"},{"en":"One survey sheet for every household in the valley.","cn":"河谷里每户一张调查表。"},{"en":"An order signed at the top, carried out before the ink is dry.","cn":"命令签在顶端，墨迹未干就已经执行。"},{"en":"Broken crates carried out before the floor is washed.","cn":"洗地之前，先把破木箱搬出去。"},{"en":"A threat that stops being words and becomes an act.","cn":"威胁不再只是话，而变成了一件事。"}],"abstract":[{"en":"A plan is only a sentence until someone carries it out.","cn":"计划在有人执行之前，只是一句话。"},{"en":"The same phrase moves a box and a reform, because both travel from intention to fact.","cn":"同一个短语既搬箱子也推改革，因为两者都从意图走到事实。"},{"en":"Execution is where authority meets material: nothing survives the trip unchanged.","cn":"执行是权威与材料相遇的地方：经过这趟搬运，没有东西原样不变。"}]},"examples":[{"en":"The laboratory will carry out the tests under a sealed protocol.","cn":"实验室将按封存的规程进行这些测试。"},{"en":"Local councils must carry out the housing survey before winter.","cn":"地方议会必须在入冬前完成住房调查。"},{"en":"A promise is easy to make and harder to carry out.","cn":"承诺容易作出，却难以履行。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「凯瑞 奥特」：把「搬出去」记成工人把箱子从屋里抬到门外——搬到底，事情就算做完","word":"carry out"},"root":"核心动词经古法语来自晚期拉丁语「把货物装上车」，其源头是高卢语中表示「车」的词，更早来源不确定；虚词为本族英语，意为「向外」。短语整体表示「把某事从计划搬到完成」，也保留字面的「搬出去」。","sensesIntro":{"en":"Nine senses move outward: a plan, a study, an order, a task, a raid, a crate, a threat, a reform at every level, and a sale.","cn":"九个义项都朝外推：计划、研究、命令、任务、突袭、木箱、威胁、层层落实的改革与一笔交易。"},"semanticMap":{"core":{"en":"CORE IMAGE: a drawing laid on a steel beam, a wrench turning, and a checklist filling with ticks as the work moves outward to completion.","cn":"核心意象：图纸摊在钢梁上，扳手转动，清单随工程推进被一格格打勾，直到完成。"},"chain":["CARRY","MOVE OUTWARD","FOLLOW THE PLAN","WORK THROUGH","FINISH","BECOME FACT"],"branches":[{"senses":"01 · 08","en":"THE PLAN AND THE LEVELS: a project or a rule must be performed from the top down to the last office.","cn":"计划与层级：工程或规则必须从上到下落到最后一个办事处。"},{"senses":"02 · 05","en":"THE FIELD ACTION: a survey in every household, a raid before dawn.","cn":"现场行动：逐户调查，黎明突袭。"},{"senses":"03 · 07","en":"THE BINDING WORD: an order obeyed, a threat finally acted on.","cn":"有约束的话：命令被服从，威胁终于变成行动。"},{"senses":"04 · 09","en":"THE CLOSED DEAL: the restoration finished, the sale executed at the opening price.","cn":"完成的交易：修复完工，卖出按开盘价执行。"},{"senses":"06","en":"THE LITERAL BOX: crates taken out before the floor is washed.","cn":"字面的箱子：洗地之前把木箱搬出去。"}]},"affixes":{"intro":{"en":"The family joins a borrowed cart word to native English endings; the particle carries direction while the endings carry agent, act and capacity.","cn":"这个词族把借来的「车」之词与本族英语词尾结合；方向由虚词承担，施事、动作与能力由词尾承担。"},"latinIntro":{"en":"Latin carrus came from Gaulish, and its verb carricare passed through French into English.","cn":"拉丁语的「车」来自高卢语，其动词经法语进入英语。"},"items":[{"word":"carrus","structure":"Latin noun","meaning":"a wheeled cart","meaningCN":"带轮的车","example":"The borrowed noun at the base of the family.","exampleCN":"词族底层的借入名词。"},{"word":"carricare","structure":"Late Latin verb","meaning":"to load a cart","meaningCN":"把货装上车","example":"It produced the verb of carrying.","exampleCN":"它产生了「运送」的动词。"},{"word":"carier","structure":"Old French verb","meaning":"to carry, to transport","meaningCN":"运送；搬运","example":"The form English borrowed.","exampleCN":"英语借入的那个形式。"},{"word":"carry","structure":"English verb","meaning":"to move something along","meaningCN":"把某物搬运向前","example":"The English verb at the centre of the phrase.","exampleCN":"短语中心的英语动词。"},{"word":"-er","structure":"noun ending","meaning":"one who does","meaningCN":"做某事的人或物","example":"It forms the word for a carrier.","exampleCN":"它构成表示「承运者」的词。"},{"word":"-age","structure":"noun ending","meaning":"act, result or charge","meaningCN":"动作；结果；费用","example":"It forms the noun for transport and its price.","exampleCN":"它构成表示运输及其费用的名词。"},{"word":"out","structure":"native particle","meaning":"away from the inside","meaningCN":"向外；离开里面","example":"It supplies the outward direction.","exampleCN":"它提供向外的方向。"},{"word":"-ing","structure":"verb ending","meaning":"ongoing action","meaningCN":"进行中的动作","example":"It forms the participle of the phrase.","exampleCN":"它构成短语的现在分词。"}],"latinEntries":[{"word":"carrus","structure":"Latin noun","meaning":"a wheeled cart","meaningCN":"带轮的车"},{"word":"carricare","structure":"Late Latin verb","meaning":"to load a cart","meaningCN":"把货装上车"},{"word":"carruca","structure":"Late Latin noun","meaning":"a heavy carriage","meaningCN":"重型车"}],"derivatives":[{"word":"carrier","pos":"n.","zh":"由动词加施事词尾构成，义为「承运者」"},{"word":"carriage","pos":"n.","zh":"由动词加名词尾构成，义为「运输；车厢」"},{"word":"carrying","pos":"n./adj.","zh":"由动词加动名词词尾构成，义为「搬运；承载的」"},{"word":"carriable","pos":"adj.","zh":"由动词加「可……的」词尾构成，义为「便于携带的」"}]}},{"word":"come into existence","ipa_uk":"/kʌm ˈɪntə ɪɡˈzɪstəns/","ipa_us":"/kʌm ˈɪntu ɪɡˈzɪstəns/","definition_zh":"开始存在；产生；成立；形成；问世","definition_en":"to begin to be, whether of an institution, a species, a rule, an idea or an object","core_image":"一间空屋子的门被推开，桌上先出现一张纸，纸上写着第一个名字，随后又添了第二张、第三张","scene":"档案馆里，一份旧会议记录显示，这个机构最初只是几个人在租来的房间里议事，后来才正式成立。The bureau may come into existence as a temporary office before it wins permanent funding.","sceneCN":"这里指机构开始存在、正式设立（第 1 个义项：组织从无到有地成立）；句意为该局可能先以临时办事处的形式设立，之后才获得长期经费。图中可辨识物件：租来的房间、会议记录、临时门牌、经费批文。","pos":[{"tag":"v. phr.","zh":"开始存在；产生（不及物动词短语，主语为被产生的事物）"},{"tag":"v. phr.","zh":"成立；问世（用于机构、制度、作品）"}],"collocations":[{"phrase":"come into existence as","zh":"以……的形式开始存在"},{"phrase":"come into existence only after","zh":"只有在……之后才产生"},{"phrase":"come into existence gradually","zh":"逐渐形成"},{"phrase":"come into existence overnight","zh":"一夜之间出现"},{"phrase":"come into existence under a new law","zh":"依新法设立"},{"phrase":"come into existence independently","zh":"独立产生"}],"forms":[{"label":"三单","form":"comes into existence"},{"label":"过去式","form":"came into existence"},{"label":"过去分词","form":"come into existence"},{"label":"现在分词","form":"coming into existence"},{"label":"完成体","form":"has come into existence"}],"derivatives":[{"word":"existence","pos":"n.","zh":"短语中的核心名词，义为「存在；生存」"},{"word":"exist","pos":"v.","zh":"由名词回构的动词，义为「存在；生存」"},{"word":"existent","pos":"adj.","zh":"由动词加形容词尾构成，义为「存在的；现存的」"},{"word":"existing","pos":"adj.","zh":"由现在分词转作形容词，义为「现有的」"}],"senses":[{"no":"01","title":"An organisation is founded","titleCN":"机构成立","definition":"to begin to operate as an organised body","definitionCN":"作为有组织的机构开始运转","example":"The first public library in the town may come into existence only after a large gift.","exampleCN":"镇上的第一座公共图书馆，可能只在一笔大额捐赠之后才会成立。","why":"Coming is movement toward a place; existence is the place reached, so founding is the moment the thing arrives.","whyCN":"「来」是朝某处移动，「存在」是抵达之处，因此「成立」就是那件事物到达的时刻。"},{"no":"02","title":"A species appears","titleCN":"物种出现","definition":"to arise as a new kind of living thing","definitionCN":"作为一种新的生物类别出现","example":"New species can come into existence when a river separates two populations for ages.","exampleCN":"当一条河把两个种群隔开很久，新的物种就可能出现。","why":"A new kind arrives at standing on its own when a river keeps two populations apart.","whyCN":"一条河把两个种群隔开，新的一类就来到独立站住的位置。"},{"no":"03","title":"A law takes effect","titleCN":"法律、制度产生","definition":"to begin to have legal force","definitionCN":"开始具有法律效力","example":"The rule should come into existence only after the council publishes it.","exampleCN":"该规则只有在议会公布之后才应产生效力。","why":"A rule stands forth only when it is published and begins to hold.","whyCN":"规则在公布并开始生效时才站出来。"},{"no":"04","title":"An idea takes shape","titleCN":"想法形成","definition":"to emerge as a recognisable concept","definitionCN":"作为一个可辨认的概念出现","example":"The notion of a common market can come into existence long before any treaty is signed.","exampleCN":"共同市场的观念可以在任何条约签署之前很久就已形成。","why":"A concept stands forth in speech long before it stands in a treaty.","whyCN":"观念先在言语中站出来，远早于它在条约中站住。"},{"no":"05","title":"A work appears","titleCN":"作品问世","definition":"to be produced and become available as a text or an object","definitionCN":"作为文本或实物被产出并可供人接触","example":"The manuscript may come into existence as a set of loose notes before it becomes a book.","exampleCN":"这部手稿可能先以一组散页笔记的形式出现，然后才成为一本书。","why":"Loose notes stand forth as a book when they are gathered into one body.","whyCN":"散页在被收拢成一体时，作为一本书站出来。"},{"no":"06","title":"A celestial body forms","titleCN":"天体形成","definition":"to condense or assemble as a physical body in space","definitionCN":"在太空中凝聚或聚合成一个天体","example":"A star can come into existence from a cloud of gas and dust.","exampleCN":"一颗恒星可以由一团气体与尘埃形成。","why":"Gas and dust arrive at standing as a star when gravity gathers them.","whyCN":"气体与尘埃在引力收拢时，来到作为恒星站住的位置。"},{"no":"07","title":"A word enters the language","titleCN":"新词进入语言","definition":"to be coined and begin to be used by speakers","definitionCN":"被造出并开始被使用者采用","example":"Most slang terms come into existence in speech and reach print much later.","exampleCN":"大多数俚语先在口语里产生，很久以后才进入印刷品。","why":"A slang term stands forth in speech and only later stands in print.","whyCN":"俚语先在口语中站出来，之后才站进印刷品。"},{"no":"08","title":"A post is created","titleCN":"职位设立","definition":"to be established as an office or a position","definitionCN":"作为一个职位或岗位被设立","example":"The office of inspector should come into existence when the factory opens.","exampleCN":"监察员这一职位应在工厂开工时设立。","why":"A post stands forth when an office is written into the rules.","whyCN":"当职位被写进规则，它就站出来了。"},{"no":"09","title":"A relationship forms","titleCN":"关系、局面形成","definition":"to develop as a working relationship or a situation","definitionCN":"作为一种可运作的关系或局面发展出来","example":"A working trust can come into existence only after both sides keep small promises.","exampleCN":"只有当双方都守住了小的承诺，可用的信任才会形成。","why":"Trust stands forth only after small promises have stood.","whyCN":"只有小的承诺先站住，信任才站出来。"}],"etymology":{"intro":{"en":"The phrase combines a native verb of arriving with a noun built in Latin from out plus standing. What comes into existence literally arrives at standing outside nothing.","cn":"这个短语把本族表示「到来」的动词，与拉丁语用「向外」加「站立」构成的名词配在一起。所谓进入存在，字面就是「来到外面的站立之处」。"},"items":[{"era":"OLD ENGLISH CUMAN","en":"Cuman meant to come or to arrive, and it is one of the oldest verbs in English.","cn":"这个词意为「来、到达」，是英语中最古老的动词之一。"},{"era":"LATIN SISTERE","en":"Sistere meant to stand or to hold one's ground, the standing image shared by the whole family.","cn":"这个词意为「站立、站住脚」，是整个词族共享的「站立」意象。"},{"era":"LATIN EXSISTERE","en":"Ex- 'out' plus sistere produced exsistere, to stand forth, to appear, to be.","cn":"表示「向外」的前缀加「站立」，构成「站出来、显现、存在」的动词。"},{"era":"LATIN EXSISTENTIA","en":"The noun named the state of standing forth, and French and English took it as existence.","cn":"相应的名词指「站出来的状态」，法语与英语把它用作「存在」。"},{"era":"PHRASE FIXED IN THE SIXTEENTH CENTURY","en":"The frame with come fixed in the sixteenth century for institutions and laws, and later for species and stars. The exact first citation is uncertain.","cn":"与「来」搭配的框架在十六世纪固定下来，先用于机构与法律，后扩及物种与星体。最早书证年代不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin standing noun; the second group holds other ways of saying that something began to be.","cn":"第一组共享拉丁「站立」名词；第二组是其他表示「开始存在」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"existence","ipa":"/ɪɡˈzɪstəns/","tag":"the noun alone","definition":"The noun names the state of being; the phrase names the moment of arriving at that state.","definitionCN":"名词指「存在的状态」；短语指「抵达这一状态的那一刻」。"},{"word":"exist","ipa":"/ɪɡˈzɪst/","tag":"the verb alone","definition":"The verb says that something is; it does not mark the beginning.","definitionCN":"动词只陈述某物存在，并不标出「开始」这一点。"},{"word":"existent","ipa":"/ɪɡˈzɪstənt/","tag":"the adjective","definition":"It describes what already is; the phrase is about the step before it existed.","definitionCN":"它形容已经存在的东西；短语说的则是它尚未存在之前的那一步。"},{"word":"existing","ipa":"/ɪɡˈzɪstɪŋ/","tag":"the participle","definition":"It marks what is present now, often before a change; it has no sense of origin.","definitionCN":"标出现在已有之物，常用在变化之前；不含起源之意。"}]},{"heading":"NEAR MEANING","entries":[{"word":"come into being","ipa":"/kʌm ˈɪntə ˈbiːɪŋ/","tag":"closest twin","definition":"Nearly the same in meaning, but it sounds more literary and is used less for offices and budgets.","definitionCN":"意思几乎相同，但更带文学色彩，较少用于职位与预算。"},{"word":"arise","ipa":"/əˈraɪz/","tag":"spring up","definition":"Often used for problems, questions and situations that appear without a maker.","definitionCN":"常用于没有明确制造者的问题、疑问与局面。"},{"word":"emerge","ipa":"/ɪˈmɜːdʒ/","tag":"come out of hiding","definition":"It stresses becoming visible after being unnoticed, as a pattern emerging from data.","definitionCN":"强调从未被注意的状态中显现，如规律从数据中浮现。"},{"word":"be established","ipa":"/bi ɪˈstæblɪʃt/","tag":"set up on purpose","definition":"It implies a deliberate founder, which the phrase itself does not require.","definitionCN":"暗示有人有意设立，而本短语本身并不要求有创立者。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the empty room, the river splitting a population, the published rule and the first star.","cn":"正常联想使用空房间、把种群隔开的河、公布的规则与第一颗星四个场景。"},"normal":[{"en":"An empty room, then one sheet of paper with the first name on it.","cn":"空房间里先出现一张纸，上面写着第一个名字。"},{"en":"A river wide enough to keep two herds apart for thousands of years.","cn":"一条宽到能把两群动物隔开上千年的河。"},{"en":"A rule that exists on paper but has no force until it is published.","cn":"一条只写在纸上、公布之前毫无效力的规则。"},{"en":"Gas and dust collapsing until a point of light switches on.","cn":"气体与尘埃塌缩，直到一点光亮起来。"},{"en":"A slang word spoken at a market stall decades before it is printed.","cn":"一个俚语在集市摊上被说了几十年，才被印出来。"}],"abstract":[{"en":"Existence begins as an event, not as a substance.","cn":"存在是从一个事件开始的，而不是从一种实体开始的。"},{"en":"Institutions are the slowest kind of new thing: they must be born in rooms before they are born in law.","cn":"机构是最慢的一种新事物：先在房间里出生，才在法律里出生。"},{"en":"Nothing begins alone: a river, a gift or a kept promise is always part of the story.","cn":"没有东西是独自开始的：一条河、一笔捐赠或一个守住的承诺，总在故事里。"}]},"examples":[{"en":"A new department may come into existence only after the budget is approved.","cn":"新部门可能只有在预算获批之后才会设立。"},{"en":"Written records can come into existence long before a formal archive is founded.","cn":"书面记录可以在正式档案馆成立之前很久就已产生。"},{"en":"The custom may come into existence among sailors and spread inland later.","cn":"这一习俗可能先在船员中形成，后来才传到内陆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「康姆 因图 伊克斯伊斯坦斯」：把「来到站立之处」记成一间空屋里先出现一张写着名字的纸——名字落纸，事物就开始了","word":"come into existence"},"root":"前半为本族动词，意为「来、到达」；后半名词出自拉丁语，由表示「向外」的前缀加表示「站立」的词根构成，本义是「站出来、显现」。短语整体表示「某物从无到有地开始站立存在」，不点明是否有创立者。","sensesIntro":{"en":"Nine senses begin something: a body, a species, a law, an idea, a text, a star, a word, a post, and a trust.","cn":"九个义项都让某物开始：机构、物种、法律、观念、文本、恒星、词语、职位与信任。"},"semanticMap":{"core":{"en":"CORE IMAGE: an empty room, and then a single sheet of paper carrying the first name, followed by more sheets.","cn":"核心意象：一间空屋子，然后出现一张写着第一个名字的纸，接着是更多张。"},"chain":["ARRIVE","STAND FORTH","BE NAMED","TAKE FORM","BECOME VISIBLE","BEGIN TO COUNT"],"branches":[{"senses":"01 · 08","en":"THE FOUNDED THING: a bureau or an inspectorship is written into being.","cn":"被设立之物：一个局或一个监察职位被写出来而存在。"},{"senses":"02 · 06","en":"THE NATURAL BIRTH: a species splits off, a star condenses.","cn":"自然诞生：物种分化，恒星凝聚。"},{"senses":"03 · 04","en":"THE RULE AND THE IDEA: force begins on publication, a concept forms before any treaty.","cn":"规则与观念：效力始于公布，观念在条约之前形成。"},{"senses":"05 · 07","en":"THE TEXT AND THE WORD: loose notes become a book, slang reaches print late.","cn":"文本与词语：散页成为书，俚语很晚才入印刷。"},{"senses":"09","en":"THE KEPT PROMISE: trust forms only after small promises hold.","cn":"守住的承诺：信任只在小的承诺兑现后形成。"}]},"affixes":{"intro":{"en":"The phrase joins a native arriving verb to a Latin noun of standing forth; the endings build the verb of being and its descriptions.","cn":"这个短语把本族「到达」动词与拉丁语「站出来」名词结合；词尾造出「存在」动词及其描述形式。"},"latinIntro":{"en":"Latin exsistere and exsistentia reached French and then English, which shortened the noun to its modern form.","cn":"拉丁语的「显现」动词与名词进入法语，再进入英语，英语把名词缩成现代形式。"},"items":[{"word":"ex-","structure":"prefix","meaning":"out, forth","meaningCN":"向外；向前","example":"It marks the thing as standing forth.","exampleCN":"它标出某物「站出来」。"},{"word":"sistere","structure":"Latin verb","meaning":"to stand, to hold ground","meaningCN":"站立；站住","example":"The standing verb behind the noun.","exampleCN":"名词背后的「站立」动词。"},{"word":"exsistere","structure":"Latin verb","meaning":"to stand forth, appear","meaningCN":"站出来；显现","example":"The direct source of the verb of being.","exampleCN":"「存在」动词的直接来源。"},{"word":"exsistentia","structure":"Latin noun","meaning":"a standing forth, being","meaningCN":"站出来；存在","example":"The noun English shortened.","exampleCN":"英语加以缩短的那个名词。"},{"word":"-ence","structure":"noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It carries the noun of state.","exampleCN":"它承担表示状态的名词。"},{"word":"-ent","structure":"adjective ending","meaning":"having the quality","meaningCN":"具有该性质的","example":"It forms the adjective of what is.","exampleCN":"它构成表示「存在者」的形容词。"},{"word":"-ing","structure":"participle ending","meaning":"ongoing","meaningCN":"进行中的","example":"It forms the participle of what currently is.","exampleCN":"它构成表示「现有」的分词。"},{"word":"into","structure":"native preposition","meaning":"to the inside of","meaningCN":"进入……之中","example":"It marks arrival at the new state.","exampleCN":"它标出抵达新状态。"}],"latinEntries":[{"word":"sistere","structure":"Latin verb","meaning":"to stand, hold ground","meaningCN":"站立；站住"},{"word":"exsistere","structure":"Latin verb","meaning":"to stand forth, appear","meaningCN":"站出来；显现"},{"word":"exsistentia","structure":"Latin noun","meaning":"a standing forth, being","meaningCN":"站出来；存在"}],"derivatives":[{"word":"existence","pos":"n.","zh":"短语中的核心名词，义为「存在」"},{"word":"exist","pos":"v.","zh":"由名词回构的动词，义为「存在」"},{"word":"existent","pos":"adj.","zh":"由动词加形容词尾构成，义为「存在的」"},{"word":"existing","pos":"adj.","zh":"由分词转作形容词，义为「现有的」"}]}},{"word":"consist of","ipa_uk":"/kənˈsɪst əv/","ipa_us":"/kənˈsɪst əv/","definition_zh":"由……构成；由……组成；包括；由……构成其全部内容","definition_en":"to be made up of the parts, members or items that are named after the preposition","core_image":"一只木盒被倒过来，零件一件件落在桌面上，排成一列，正好凑成盒子里原来装着的那件东西","scene":"检验员把一台旧仪器拆开，把里面的零件按大小排成一列，逐一登记。The device should consist of a lens, a brass tube and a wooden stand.","sceneCN":"这里指一台装置由若干部件构成（第 1 个义项：整体由列出的部分组成）；句意为一台这样的装置应由一片透镜、一根黄铜管与一个木架构成。图中可辨识物件：拆开的仪器、排成一列的零件、登记簿、木架。","pos":[{"tag":"v. phr.","zh":"由……构成（及物动词短语，后接构成整体的各部分）"},{"tag":"v. phr.","zh":"由……组成（后接成员、成分或步骤）"}],"collocations":[{"phrase":"consist of three parts","zh":"由三个部分组成"},{"phrase":"consist of members","zh":"由成员组成"},{"phrase":"consist of water and salt","zh":"由水与盐构成"},{"phrase":"consist of several stages","zh":"由若干阶段构成"},{"phrase":"consist of a summary and an appendix","zh":"由摘要与附录构成"},{"phrase":"consist mainly of","zh":"主要由……构成"}],"forms":[{"label":"三单","form":"consists of"},{"label":"过去式","form":"consisted of"},{"label":"过去分词","form":"consisted of"},{"label":"现在分词","form":"consisting of"},{"label":"情态后原形","form":"consist of"}],"derivatives":[{"word":"consistency","pos":"n.","zh":"由同根形容词加名词尾构成，义为「一致性」，与「构成」义不同"},{"word":"consistent","pos":"adj.","zh":"由同根词干加形容词尾构成，义为「一致的」，与「构成」义不同"},{"word":"consistently","pos":"adv.","zh":"由同根形容词加副词尾构成，义为「一贯地」"},{"word":"inconsistent","pos":"adj.","zh":"由否定前缀加同根形容词构成，义为「不一致的」"}],"senses":[{"no":"01","title":"Made of physical parts","titleCN":"由实物部分组成","definition":"to be built from a stated set of components","definitionCN":"由一组明确的部件搭成","example":"The bridge must consist of three spans and a central pier.","exampleCN":"这座桥必须由三个跨度与一座中央桥墩构成。","why":"The core verb meant to stand together; parts that stand together make one whole, which is the oldest sense of the phrase.","whyCN":"核心动词本义是「站在一起」；站在一起的各部分合成一个整体，这正是短语最古老的义项。"},{"no":"02","title":"Composed of members","titleCN":"由成员组成","definition":"to have a stated set of people as its members","definitionCN":"以一组明确的人作为其成员","example":"The panel should consist of five reviewers from outside the university.","exampleCN":"评审小组应由五名校外评审人组成。","why":"Parts that stand together can be people; a panel is a whole made of named members.","whyCN":"站在一起的部分也可以是人；小组就是由具名成员构成的整体。"},{"no":"03","title":"Made of ingredients","titleCN":"由成分、原料构成","definition":"to be made from a stated mixture of materials","definitionCN":"由明确的材料混合物制成","example":"The plaster can consist of lime, sand and animal hair.","exampleCN":"这种灰泥可以由石灰、砂与动物毛构成。","why":"The standing-together image applies to a mixture: the materials stand in one body.","whyCN":"「站在一起」的意象也用于混合物：材料站进同一个身体。"},{"no":"04","title":"Divided into steps","titleCN":"由若干步骤构成","definition":"to be carried out as a stated series of stages","definitionCN":"按明确的一系列阶段进行","example":"The procedure must consist of four washes and one final rinse.","exampleCN":"该流程必须由四次洗涤与最后一次漂洗构成。","why":"Stages stand one after another in a procedure and together make the whole.","whyCN":"各阶段在流程中依次站住，共同构成整体。"},{"no":"05","title":"Built from chapters or sections","titleCN":"由章节构成","definition":"to be organised as a stated set of sections","definitionCN":"按明确的一组章节组织起来","example":"The report should consist of a summary, three chapters and an appendix.","exampleCN":"报告应由一篇摘要、三章正文与一个附录构成。","why":"Sections stand together in a fixed order to make one report.","whyCN":"各章节按固定次序站在一起，构成一份报告。"},{"no":"06","title":"Made of elements or compounds","titleCN":"由元素、化合物组成","definition":"to be composed of stated chemical constituents","definitionCN":"由明确的化学组分构成","example":"The mineral may consist of iron oxide with traces of silica.","exampleCN":"这种矿物可能由氧化铁并含微量二氧化硅组成。","why":"Chemical constituents stand together in one mineral.","whyCN":"化学组分在同一块矿物中站在一起。"},{"no":"07","title":"Made of premises","titleCN":"由前提构成","definition":"to be constructed from stated assumptions or statements","definitionCN":"由明确的假设或陈述搭成","example":"A valid proof must consist of premises that are either given or already shown.","exampleCN":"一个有效的证明必须由已给出或已证明的命题构成。","why":"Premises stand together to hold up one conclusion.","whyCN":"各前提站在一起，托住一个结论。"},{"no":"08","title":"Accounted for by budget items","titleCN":"由预算项目构成","definition":"to be made up of stated categories of spending","definitionCN":"由明确的支出类别构成","example":"The annual budget can consist of salaries, maintenance and a small reserve.","exampleCN":"年度预算可由薪金、维护费与一小笔储备构成。","why":"Spending lines stand together to make one annual sum.","whyCN":"各支出项目站在一起，构成一个年度总额。"},{"no":"09","title":"Made up of stated proportions","titleCN":"按比例构成","definition":"to be made up of stated proportions of a population or a set","definitionCN":"按明确的比例由某一群体或集合构成","example":"The sample must consist of equal numbers of men and women.","exampleCN":"样本必须由数目相等的男性与女性构成。","why":"A sample can be a whole whose parts stand in a stated ratio.","whyCN":"样本可以是一个整体，其各部分按明确比例站在一起。"}],"etymology":{"intro":{"en":"The phrase is built on a Latin verb meaning to stand together. Parts that stand together form a whole, and English uses the phrase to name exactly those parts, never the whole itself as one of them.","cn":"这个短语建立在拉丁语「一起站立」的动词上。站在一起的各部分构成整体，英语正是用这个短语点出这些部分，而绝不把整体本身算作其中一个部分。"},"items":[{"era":"LATIN SISTERE","en":"Sistere meant to stand or to place, and it supplied the standing image for the whole family.","cn":"这个词意为「站立、安放」，为整个词族提供了「站立」的意象。"},{"era":"LATIN CONSISTERE","en":"Com- 'together' plus sistere produced consistere, to stand together, to hold firm, to be made up of.","cn":"表示「一起」的前缀加「站立」，构成「站在一起、立稳、由……构成」的动词。"},{"era":"FRENCH CONSISTER","en":"French passed the verb to English in the sixteenth century, where it first meant to have a certain nature or makeup.","cn":"法语在十六世纪把这个动词传给英语，最初指「具有某种本性或构造」。"},{"era":"CONSIST OF AND CONSIST IN","en":"Two prepositions split the old verb: of names the parts, in names the essential point. The pair is a frequent source of error.","cn":"两个介词把这个古老动词一分为二：一个点出部分，另一个点出实质所在。这对搭配是常见的错误来源。"},{"era":"PHRASE FIXED","en":"The frame with this preposition became the standard way to list the parts of a whole. The exact first citation and the date of the split from the other preposition are uncertain.","cn":"与这个介词搭配的框架成为列举整体各部分的标准说法。最早书证年代，以及它与另一介词用法分化的年代，均不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin standing root and is constantly confused with the phrase; the second group holds other ways of naming the parts of a whole.","cn":"第一组共享拉丁「站立」词根，常与本短语混淆；第二组是其他列举整体部分的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"be consistent with","ipa":"/biː kənˈsɪstənt wɪð/","tag":"same root, entirely different meaning","definition":"It means to agree with something, not to be made up of it. A report can be consistent with the evidence while consisting of five chapters.","definitionCN":"它的意思是「与某物一致」，而不是「由某物构成」。一份报告可以合乎证据，同时由五章构成。"},{"word":"consist in","ipa":"/kənˈsɪst ɪn/","tag":"same verb, other preposition","definition":"It names the essential point rather than the parts, as when a method consists in careful measurement.","definitionCN":"它点出实质所在，而非列举部分，例如某方法实质在于仔细测量。"},{"word":"consistency","ipa":"/kənˈsɪstənsi/","tag":"the noun of agreement","definition":"It names agreement or evenness, not the parts of a whole.","definitionCN":"它指「一致性、均匀」，而不是整体的各部分。"},{"word":"consistent","ipa":"/kənˈsɪstənt/","tag":"the adjective of agreement","definition":"The adjective describes agreement, so it cannot replace the phrase when parts are being listed.","definitionCN":"形容词描述「一致」，因此在列举部分时不能替换本短语。"}]},{"heading":"NEAR MEANING","entries":[{"word":"be composed of","ipa":"/bi kəmˈpəʊzd ɒv/","tag":"formal listing","definition":"A formal equivalent that stresses the act of putting parts together; it is common in technical writing.","definitionCN":"正式的对应说法，强调把部分合在一起的动作，常见于技术写作。"},{"word":"comprise","ipa":"/kəmˈpraɪz/","tag":"whole to parts","definition":"It usually takes the whole as subject and the parts as object; usage guides disagree about the reverse pattern.","definitionCN":"通常以整体作主语、部分作宾语；用法指南对反过来用的写法意见不一。"},{"word":"be made up of","ipa":"/bi meɪd ʌp ɒv/","tag":"plain everyday phrase","definition":"The everyday equivalent; it works in speech where the phrase would sound too formal.","definitionCN":"日常对应说法，在口语中比本短语自然。"},{"word":"constitute","ipa":"/kənˈstɪtjuːt/","tag":"parts to whole","definition":"It reverses the direction: the parts constitute the whole, so the whole is not the subject.","definitionCN":"方向相反：部分构成整体，因此整体不能作主语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the tipped box, the five reviewers, the plaster mix and the budget sheet.","cn":"正常联想使用倒出的木盒、五名评审、灰泥配料与预算表四个场景。"},"normal":[{"en":"A box tipped over: the parts fall out and line up into exactly the thing that was inside.","cn":"木盒一倒，零件落出来排成一列，正好凑成原来装在里面的那件东西。"},{"en":"Five reviewers from outside the university, no more and no fewer.","cn":"五名校外评审，不多也不少。"},{"en":"Lime, sand and animal hair mixed into plaster.","cn":"石灰、砂与动物毛拌成灰泥。"},{"en":"Four washes and one rinse, in that order.","cn":"四次洗涤加一次漂洗，顺序不能乱。"},{"en":"A budget with three lines and a small reserve.","cn":"预算只有三行，再加一小笔储备。"}],"abstract":[{"en":"The phrase names the parts and never lets the whole join the list.","cn":"这个短语只点部分，绝不让整体混进清单。"},{"en":"A whole is not one of its own parts, just as a sentence is not one of its words.","cn":"整体不是自己的一个部分，正如句子不是它的某个词。"},{"en":"Two prepositions from one verb: one lists the pieces, the other names the point.","cn":"同一个动词配两个介词：一个列零件，一个点实质。"}]},"examples":[{"en":"The committee should consist of seven members with voting rights.","cn":"该委员会应由七名有表决权的成员组成。"},{"en":"The atmosphere must consist of nitrogen, oxygen and a few trace gases.","cn":"大气必须由氮、氧与少数微量气体构成。"},{"en":"A good lecture can consist of one question and three examples.","cn":"一堂好课可以由一个问题与三个例子构成。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「肯西斯特 欧夫」：把「站在一起」记成倒出来的零件排成一列，正好拼回原物——零件站着，整体就成了","word":"consist of"},"root":"核心动词出自拉丁语，由表示「一起」的前缀加表示「站立」的词根构成，本义是「站在一起、立稳」，引申为「由若干部分合成整体」。该短语后接介词引出各部分，整体本身不能列入其中。","sensesIntro":{"en":"Nine senses name parts of different wholes: components, members, ingredients, steps, chapters, chemical constituents, premises, budget lines, and proportions.","cn":"九个义项为不同的整体点名部分：部件、成员、成分、步骤、章节、化学组分、前提、预算项目与比例。"},"semanticMap":{"core":{"en":"CORE IMAGE: a box tipped over, its parts falling out and lining up into exactly the object that had been inside.","cn":"核心意象：木盒被倒过来，零件落出排成一列，正好拼成原来装在里面的那件东西。"},"chain":["STAND TOGETHER","FALL INTO PARTS","NAME EACH PART","COVER THE WHOLE","LEAVE NOTHING OUT","FORM ONE THING"],"branches":[{"senses":"01 · 03 · 06","en":"THE MATERIAL WHOLE: components, ingredients and chemical constituents are all matter arranged into one object.","cn":"物质整体：部件、成分与化学组分都是被排成一件物体的物质。"},{"senses":"02 · 08","en":"THE COUNTED WHOLE: people on a panel and lines in a budget are both lists that must add up.","cn":"可数的整体：评审名单与预算条目都是必须加得起来的清单。"},{"senses":"04 · 05","en":"THE ORDERED WHOLE: steps in a procedure and sections in a report follow a sequence.","cn":"有序的整体：流程步骤与报告章节都按顺序排列。"},{"senses":"07","en":"THE LOGICAL WHOLE: a proof is built out of premises that already stand.","cn":"逻辑整体：证明由已经站得住的前提搭成。"},{"senses":"09","en":"THE PROPORTIONAL WHOLE: a sample is built to a stated ratio.","cn":"比例整体：样本按明确比例构成。"}]},"affixes":{"intro":{"en":"The family is built on the Latin standing verb; the same stem gives both the phrase of composition and the adjective of agreement.","cn":"这个词族建立在拉丁语「站立」动词上；同一个词干既造出「构成」短语，也造出「一致」形容词。"},"latinIntro":{"en":"Latin consistere passed through French into English, and the preposition of was added in English.","cn":"拉丁语的「一起站立」经法语进入英语，介词部分则是英语后加的。"},"items":[{"word":"con-","structure":"prefix","meaning":"together","meaningCN":"一起","example":"It marks the parts as standing in one place.","exampleCN":"它标出各部分站到同一处。"},{"word":"sistere","structure":"Latin verb","meaning":"to stand, to place","meaningCN":"站立；安放","example":"The standing verb at the base.","exampleCN":"底层的「站立」动词。"},{"word":"consistere","structure":"Latin verb","meaning":"to stand together, hold firm","meaningCN":"站在一起；立稳","example":"The direct source of the English verb.","exampleCN":"英语动词的直接来源。"},{"word":"consist-","structure":"English stem","meaning":"to be made up","meaningCN":"由……构成","example":"The stem used in the modern phrase.","exampleCN":"现代短语所用的词干。"},{"word":"-ent","structure":"adjective ending","meaning":"having the quality","meaningCN":"具有该性质的","example":"It forms the adjective of agreement.","exampleCN":"它构成表示「一致」的形容词。"},{"word":"-ence","structure":"noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It forms the noun of consistency.","exampleCN":"它构成「一致性」名词。"},{"word":"-ency","structure":"noun ending","meaning":"state or quality, variant","meaningCN":"状态；性质（变体词尾）","example":"It gives the modern noun form.","exampleCN":"它给出名词的现代形式。"},{"word":"of","structure":"preposition","meaning":"belonging to, made from","meaningCN":"属于；由……而来","example":"It introduces the parts that make the whole.","exampleCN":"它引出构成整体的各部分。"}],"latinEntries":[{"word":"sistere","structure":"Latin verb","meaning":"to stand, place","meaningCN":"站立；安放"},{"word":"consistere","structure":"Latin verb","meaning":"to stand together, hold firm","meaningCN":"站在一起；立稳"},{"word":"consistentia","structure":"Latin noun","meaning":"a standing firm","meaningCN":"立稳的状态"}],"derivatives":[{"word":"consistency","pos":"n.","zh":"由同根形容词加名词尾构成，义为「一致性」"},{"word":"consistent","pos":"adj.","zh":"由同根词干加形容词尾构成，义为「一致的」"},{"word":"consistently","pos":"adv.","zh":"由形容词加副词尾构成，义为「一贯地」"},{"word":"inconsistent","pos":"adj.","zh":"由否定前缀加形容词构成，义为「不一致的」"}]}},{"word":"contribute to","ipa_uk":"/kənˈtrɪbjuːt tə/","ipa_us":"/kənˈtrɪbjuːt tuː/","definition_zh":"为……出力；捐资；促成；加剧；向……投稿；为……提供材料","definition_en":"to give money, effort, material or a cause toward something, whether to help it or to make it worse","core_image":"一只募捐盘在门口传了一圈，回来时压着硬币、纸条与一张写满数据的卡片，盘子本身却没变重多少","scene":"社区公告栏上贴着一张修缮老桥的筹款表，往来的人在上面写下各自能出的份额。Anyone who uses the bridge may contribute to its upkeep.","sceneCN":"这里指出钱出力帮助某项公共事务（第 1 个义项：为共同目标提供资金或资源）；句意为任何使用这座桥的人都可以为它的维护出钱出力。图中可辨识物件：筹款表、硬币、修缮中的桥、签名笔。","pos":[{"tag":"v. phr.","zh":"为……出力；捐资；促成（不及物动词短语加介词，后接受益对象或结果）"},{"tag":"v. phr.","zh":"向……投稿；为……撰稿（后接刊物、讨论或文集）"}],"collocations":[{"phrase":"contribute to a fund","zh":"向基金捐款"},{"phrase":"contribute to research","zh":"为研究出力"},{"phrase":"contribute to a journal","zh":"向期刊投稿"},{"phrase":"contribute to the discussion","zh":"参与讨论"},{"phrase":"contribute to pollution","zh":"加剧污染"},{"phrase":"contribute to economic growth","zh":"促进经济增长"},{"phrase":"contribute to a better understanding","zh":"增进理解"}],"forms":[{"label":"三单","form":"contributes to"},{"label":"过去式","form":"contributed to"},{"label":"过去分词","form":"contributed to"},{"label":"现在分词","form":"contributing to"},{"label":"情态后原形","form":"contribute to"}],"derivatives":[{"word":"contribution","pos":"n.","zh":"由动词加表示行为的名词尾构成，义为「贡献；捐款；投稿」"},{"word":"contributor","pos":"n.","zh":"由动词加表示施事者的词尾构成，义为「贡献者；投稿人」"},{"word":"contributory","pos":"adj.","zh":"由动词加形容词尾构成，义为「促成的；有责任的」"},{"word":"contributing","pos":"adj.","zh":"由分词转作形容词，义为「有所贡献的」"}],"senses":[{"no":"01","title":"Give money to a shared aim","titleCN":"为共同目标捐资","definition":"to give money toward a fund, a project or a public good","definitionCN":"为基金、项目或公共事业提供资金","example":"Each member may contribute to the repair fund according to income.","exampleCN":"每位成员可以按收入情况向修缮基金捐资。","why":"The verb meant to allot a share alongside others; money given into a common pot is a share assigned to the whole.","whyCN":"核心动词本义是「与他人一起分派份额」；放进公家的钱，就是分给整体的一份。"},{"no":"02","title":"Help cause a result","titleCN":"促成某种结果","definition":"to be one of the causes that help produce an outcome","definitionCN":"作为帮助产生某一结果的成因之一","example":"Better street lighting can contribute to a fall in night accidents.","exampleCN":"更好的路灯照明可以促成夜间事故下降。","why":"A share added to a total can turn the total; a street lamp adds its bit to the night's safety.","whyCN":"加进总量的一份可以改变总量；路灯为夜间安全添上自己那一份。"},{"no":"03","title":"Add effort to a team","titleCN":"为团队出力","definition":"to give work or skill to a joint undertaking","definitionCN":"为共同的事业提供劳动或技能","example":"Every student should contribute to the group's field notes.","exampleCN":"每位学生都应为小组的野外记录出力。","why":"Field notes are a share given to a joint page.","whyCN":"野外记录是交到共同页面上的一份。"},{"no":"04","title":"Submit writing to a publication","titleCN":"向刊物投稿","definition":"to send an article or a piece of writing for publication","definitionCN":"把文章或文字作品投给刊物发表","example":"She may contribute to the journal only after the embargo ends.","exampleCN":"她只有在禁发期结束后才能向该刊投稿。","why":"An article is a share handed in to an editor's common fund of pages.","whyCN":"文章是交到编辑那一份公共版面里的份额。"},{"no":"05","title":"Supply data for research","titleCN":"为研究提供数据","definition":"to provide records or measurements that others will analyse","definitionCN":"提供可供他人分析的记录或测量","example":"Farmers can contribute to the climate record by sending daily readings.","exampleCN":"农民可以通过寄送每日读数，为气候记录提供数据。","why":"Daily readings are shares handed to a collective record.","whyCN":"每日读数是交到集体记录里的一份份份额。"},{"no":"06","title":"Make a problem worse","titleCN":"加剧某个问题","definition":"to be one of the factors that intensifies an unwanted condition","definitionCN":"作为使某种不良状况加剧的因素之一","example":"Idling engines may contribute to the smog that covers the basin.","exampleCN":"空转的发动机可能加剧笼罩盆地的烟雾。","why":"The same frame serves help and harm: a share can be added to a good total or to a bad one.","whyCN":"同一个框架既可用于帮助也可用于损害：份额可以加进好的总量，也可以加进坏的总量。"},{"no":"07","title":"Advance knowledge or culture","titleCN":"对知识与文化有贡献","definition":"to add something of lasting value to a field or an art","definitionCN":"为一个领域或一门艺术增添有持久价值的东西","example":"Translators can contribute to the survival of a minority literature.","exampleCN":"译者可以为少数族裔文学的存续作出贡献。","why":"A translated book is a share added to a literature's common stock.","whyCN":"一部译作是加进文学公共库存的一份。"},{"no":"08","title":"Join a discussion with views","titleCN":"参与讨论、提供意见","definition":"to add one's views or findings to an ongoing debate","definitionCN":"把自己的看法或发现加进正在进行的讨论","example":"Observers may contribute to the debate without voting.","exampleCN":"观察员可以参与讨论而不参加表决。","why":"A view offered in debate is a share put into a common pot of argument.","whyCN":"讨论中提出的看法，是放进公共论证锅里的一份。"},{"no":"09","title":"Pay into a fund over time","titleCN":"定期缴存","definition":"to make regular payments into a pension or insurance fund","definitionCN":"定期向养老金或保险基金缴款","example":"Employees should contribute to the pension plan from their first month.","exampleCN":"雇员应从第一个月起向养老金计划缴存。","why":"A monthly payment into a pension is a share handed over before it is needed.","whyCN":"每月缴进养老金的钱，是在需要之前就交出去的一份。"}],"etymology":{"intro":{"en":"The phrase rests on a Latin verb built from together plus allot. Its root sense is a share assigned alongside others, which is why the same phrase can help a project, feed a debate or worsen a problem.","cn":"这个短语的核心是拉丁语中由「一起」加「分派」构成的动词。其本义是「与他人一起分得的一份份额」，因此同一短语既能帮助项目，也能喂给讨论，或加剧一个问题。"},"items":[{"era":"LATIN TRIBUS","en":"Tribus named a division of the Roman people, and the word is usually explained as a threefold division, a reconstructed form rather than a recorded one.","cn":"这个词指罗马人民的一个分部，通常被解释为「三分之划分」，但那是重构形式，并非有记录的原形。"},{"era":"LATIN TRIBUERE","en":"From the noun came tribuere, to allot, to assign a share, to grant.","cn":"由该名词产生「分派、分配一份、给予」的动词。"},{"era":"LATIN CONTRIBUERE","en":"Com- 'together' plus tribuere produced contribuere, to bring shares together into one common fund.","cn":"表示「一起」的前缀加「分派」，构成「把各份汇到一起」的动词。"},{"era":"FRENCH AND ENGLISH","en":"French contribuer and English contribute both carried the sense of joining one's share to a common sum.","cn":"法语与英语的形式都保留了「把自己的份额加进公共总额」的意思。"},{"era":"PHRASE AND ITS DOUBLE DIRECTION","en":"With to, the phrase points either at the recipient or at the result, which is how helping and worsening share one form. The exact first citation is uncertain, and the deeper origin of the division word is a reconstruction.","cn":"带介词时，这个短语或指接受者，或指结果，帮助与加剧因此共用一种形式。最早书证年代不确定；表示「分部」的那个词更早的来源属重构形式。"}]},"similar":{"note":{"en":"The first group shares the Latin allotting root, including a word that looks similar but distributes rather than gathers; the second group holds other ways of adding to something.","cn":"第一组共享拉丁「分派」词根，其中还包括一个形近却表示「分发」而非「汇集」的词；第二组是其他表示「增添」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"contribution","ipa":"/ˌkəntrɪˈbjuːʃn/","tag":"the noun","definition":"It names the share given; the phrase names the act of giving it toward something.","definitionCN":"名词指「所给出的那份」；短语指「把它给向某物」这一动作。"},{"word":"contributor","ipa":"/kənˈtrɪbjuːtə/","tag":"the person","definition":"It names the giver, including a writer who sends an article; the phrase has no person in it.","definitionCN":"指给予者，也包括投稿的作者；短语本身不含「人」。"},{"word":"distribute","ipa":"/dɪˈstrɪbjuːt/","tag":"same root, opposite direction","definition":"From dis- 'apart' plus the same allotting verb: it sends shares outward instead of gathering them in.","definitionCN":"表示「分开」的前缀加同一个「分派」动词：它把份额分发出去，而不是汇拢进来。"},{"word":"attribute","ipa":"/əˈtrɪbjuːt/","tag":"same root, different prefix","definition":"From ad- 'to' plus the same verb: it assigns a cause or a quality to someone, without any gift.","definitionCN":"表示「朝向」的前缀加同一个动词：把原因或性质归到某人身上，不涉及给予。"}]},{"heading":"NEAR MEANING","entries":[{"word":"add to","ipa":"/æd tə/","tag":"plain addition","definition":"The everyday phrase for making something larger; it can help or worsen but carries no sense of a share.","definitionCN":"日常表示「使增大」的说法，可好可坏，但不含「份额」之意。"},{"word":"lead to","ipa":"/liːd tə/","tag":"causal chain","definition":"It marks a step in a causal chain; it does not imply that other factors are also at work.","definitionCN":"标出因果链中的一步，不暗示还有其他因素在起作用。"},{"word":"donate to","ipa":"/dəʊˈneɪt tə/","tag":"give as a gift","definition":"It is limited to giving money or goods, usually to a charity, and cannot mean to worsen a problem.","definitionCN":"限于捐钱捐物，通常给慈善机构，不能表示「加剧问题」。"},{"word":"submit to","ipa":"/səbˈmɪt tə/","tag":"send for review","definition":"It is the usual verb for sending an article to an editor; it says nothing about the wider effect of the work.","definitionCN":"是把文章送交编辑的常用说法，不涉及作品更广泛的作用。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the collection plate, the street lamp, the embargoed journal and the idling engine.","cn":"正常联想使用募捐盘、路灯、禁发期的期刊与空转的发动机四个场景。"},"normal":[{"en":"A collection plate passed around the room, each person dropping in a share.","cn":"募捐盘在屋里传一圈，每人放进自己的一份。"},{"en":"A new street lamp over a crossing where cars used to meet.","cn":"旧日车祸频发的路口，新装了一盏路灯。"},{"en":"A farmer mailing a sheet of daily readings to a climate office.","cn":"农民把一张每日读数寄给气候机构。"},{"en":"An idling engine outside a school gate, adding to the haze.","cn":"校门外空转的发动机，给雾霾又添一份。"},{"en":"A translator keeping an old literature alive one book at a time.","cn":"译者一本一本地让旧文学活下去。"}],"abstract":[{"en":"A contribution is a share that becomes part of a sum larger than itself.","cn":"贡献是一份份额，它并入一个比自己更大的总额。"},{"en":"The same gesture that helps can harm, because the frame asks only where the share goes.","cn":"帮助与损害可以是同一个动作，因为这个框架只问份额去了哪里。"},{"en":"Giving is not losing: the share leaves the hand and stays in the result.","cn":"给予不是失去：份额离开手，却留在结果里。"}]},"examples":[{"en":"Every household can contribute to the village well fund in small amounts.","cn":"每家每户都可以小额向村井基金捐资。"},{"en":"Poor ventilation may contribute to the spread of the infection indoors.","cn":"通风不良可能加剧感染在室内的传播。"},{"en":"Outside scholars may contribute to the volume after peer review.","cn":"外部学者可以在同行评审之后向该文集投稿。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「肯吹比尤特 图」：把「分一份进去」记成募捐盘传一圈，每人都放一份——份额汇进去，就有了贡献","word":"contribute to"},"root":"核心动词出自拉丁语，由表示「一起」的前缀加表示「分派份额」的动词构成，本义是「把各份汇到一起」，引申为「贡献、促成、投稿、缴存」。表示「份额」的那一名词更早的来源属重构形式，未有定论。该短语后接介词，既可指接受者，也可指结果。","sensesIntro":{"en":"Nine senses give a share toward something: money, a cause, team effort, an article, data, a worse problem, culture, a debate, and a pension fund.","cn":"九个义项把一份东西给向某处：钱、成因、团队劳动、文章、数据、更糟的问题、文化、讨论与养老基金。"},"semanticMap":{"core":{"en":"CORE IMAGE: a collection plate passed around, returning loaded with coins, notes and a data card while the plate itself is barely heavier.","cn":"核心意象：募捐盘传了一圈，回来时压着硬币、纸条与数据卡，盘子本身却几乎没变重。"},"chain":["ALLOT A SHARE","GATHER THE SHARES","ADD TO A COMMON SUM","HELP OR WORSEN","REACH A RESULT","LEAVE A MARK"],"branches":[{"senses":"01 · 09","en":"THE COMMON PURSE: a repair fund and a pension plan both collect regular shares.","cn":"公共钱袋：修缮基金与养老金都收集定期份额。"},{"senses":"02 · 06","en":"THE CAUSAL SHARE: a street lamp lowers accidents, an idling engine raises smog.","cn":"因果份额：路灯减少事故，空转发动机增加雾霾。"},{"senses":"03 · 07","en":"THE WORK GIVEN: field notes and translated books are labour added to a lasting whole.","cn":"给出的劳动：野外记录与译作都是加进持久整体的劳动。"},{"senses":"04 · 08","en":"THE PAGE AND THE PODIUM: an article sent to a journal, a view added to a debate.","cn":"版面与讲台：投给期刊的文章，加进讨论的看法。"},{"senses":"05","en":"THE DATA GIFT: daily readings handed over for others to analyse.","cn":"数据之赠：交出每日读数，供他人分析。"}]},"affixes":{"intro":{"en":"The family is built on a Latin allotting verb; the prefix gathers shares, while other prefixes scatter or assign them.","cn":"这个词族建立在拉丁语「分派」动词上；前缀把份额汇拢，别的前缀则把份额散开或归到某处。"},"latinIntro":{"en":"Latin tribuere and contribuere reached French and then English, which added its own noun and agent endings.","cn":"拉丁语的「分派」与「汇合」动词进入法语，再进入英语，英语又加上自己的名词与施事词尾。"},"items":[{"word":"con-","structure":"prefix","meaning":"together","meaningCN":"一起；共同","example":"It gathers the shares into one fund.","exampleCN":"它把各份汇进同一个基金。"},{"word":"tribus","structure":"Latin noun","meaning":"a division of the people","meaningCN":"人民的一个分部","example":"The noun behind the allotting verb.","exampleCN":"「分派」动词背后的名词。"},{"word":"tribuere","structure":"Latin verb","meaning":"to allot, assign a share","meaningCN":"分派；分配一份","example":"The giving verb of the family.","exampleCN":"词族中的「给予」动词。"},{"word":"contribuere","structure":"Latin verb","meaning":"to bring shares together","meaningCN":"把各份汇到一起","example":"The direct source of the English verb.","exampleCN":"英语动词的直接来源。"},{"word":"-tion","structure":"noun ending","meaning":"action or result","meaningCN":"动作；结果","example":"It forms the noun of the share given.","exampleCN":"它构成表示「所给份额」的名词。"},{"word":"-or","structure":"noun ending","meaning":"one who does","meaningCN":"做某事的人","example":"It forms the word for the giver.","exampleCN":"它构成表示「给予者」的词。"},{"word":"-ory","structure":"adjective ending","meaning":"tending to","meaningCN":"有……作用的","example":"It forms the adjective for what helps cause a result.","exampleCN":"它构成表示「起促成作用」的形容词。"},{"word":"to","structure":"preposition","meaning":"toward","meaningCN":"朝向；对于","example":"It points the share at its recipient or result.","exampleCN":"它把份额指向接受者或结果。"}],"latinEntries":[{"word":"tribus","structure":"Latin noun","meaning":"a division of the people","meaningCN":"人民的一个分部"},{"word":"tribuere","structure":"Latin verb","meaning":"to allot, assign","meaningCN":"分派；分配"},{"word":"contribuere","structure":"Latin verb","meaning":"to bring shares together","meaningCN":"把各份汇到一起"}],"derivatives":[{"word":"contribution","pos":"n.","zh":"由动词加行为名词尾构成，义为「贡献；捐款」"},{"word":"contributor","pos":"n.","zh":"由动词加施事词尾构成，义为「贡献者；投稿人」"},{"word":"contributory","pos":"adj.","zh":"由动词加形容词尾构成，义为「促成的」"},{"word":"contributing","pos":"adj.","zh":"由分词转作形容词，义为「有贡献的」"}]}},{"word":"cope with","ipa_uk":"/kəʊp wɪð/","ipa_us":"/koʊp wɪð/","definition_zh":"应对；应付；处理；承受；勉强维持","definition_en":"to deal with a difficulty, a load or a demand using the resources one has","core_image":"一个人顶着风把伞撑开，伞骨被吹得反折，他没有松手，而是侧过身换了个角度继续往前走","scene":"急诊走廊里，护士推着车穿过人群，墙上的排班表被临时改写了好几处。The night team must cope with twice the usual number of arrivals.","sceneCN":"这里指承受并处理超出平常的工作量（第 2 个义项：应付繁重的任务或需求）；句意为夜班团队必须应对两倍于平常的接诊人数。图中可辨识物件：急诊推车、改写过的排班表、候诊椅、走廊指示牌。","pos":[{"tag":"v. phr.","zh":"应对；应付（不及物动词短语加介词，后接困难、压力或任务）"},{"tag":"v. phr.","zh":"承受；勉强维持（后接负荷、开支或局面）"}],"collocations":[{"phrase":"cope with stress","zh":"应对压力"},{"phrase":"cope with the workload","zh":"应付工作量"},{"phrase":"cope with a crisis","zh":"应对危机"},{"phrase":"cope with change","zh":"适应变化"},{"phrase":"cope with illness","zh":"应对疾病"},{"phrase":"cope with a tight budget","zh":"靠紧张的预算维持"},{"phrase":"cope with the load","zh":"承受负荷"}],"forms":[{"label":"三单","form":"copes with"},{"label":"过去式","form":"coped with"},{"label":"过去分词","form":"coped with"},{"label":"现在分词","form":"coping with"},{"label":"情态后原形","form":"cope with"}],"derivatives":[{"word":"coping","pos":"n./adj.","zh":"由动词加动名词词尾构成，义为「应对方式；应对的」"},{"word":"cope","pos":"v.","zh":"去掉介词后的核心动词，义为「应付；对付」"},{"word":"coped","pos":"v.","zh":"核心动词的过去式与过去分词形式"},{"word":"coper","pos":"n.","zh":"由动词加施事词尾构成，义为「能应付的人」，较少用"}],"senses":[{"no":"01","title":"Handle pressure","titleCN":"应对压力","definition":"to keep functioning under strain without breaking down","definitionCN":"在压力下仍能运转而不垮掉","example":"Students must cope with the strain of three examinations in one week.","exampleCN":"学生必须应对一周三场考试带来的压力。","why":"The verb came from a word for exchanging blows; coping is holding one's ground in a contest, not winning it.","whyCN":"核心动词出自表示「交手、对打」的词；应对就是在较量中站住，而不是取胜。"},{"no":"02","title":"Manage a heavy workload","titleCN":"应付繁重的工作量","definition":"to deal with more work or more demand than is usual","definitionCN":"处理超出平常的工作量或需求","example":"The small office can cope with a sudden rise in applications.","exampleCN":"这个小办事处能够应付申请量的突然上升。","why":"Coping is holding one's ground when the work arrives faster than usual.","whyCN":"当工作来得比平常更快，撑住就是应对。"},{"no":"03","title":"Respond to a crisis","titleCN":"应对危机","definition":"to act effectively when an emergency breaks","definitionCN":"紧急状况发生时能有效行动","example":"The hospital may cope with a flood of casualties only if extra staff arrive.","exampleCN":"只有增援人员到达，医院才可能应对大量伤员涌入。","why":"A crisis is a blow one meets with whatever hands are free.","whyCN":"危机是用手里现有的人手迎上的一击。"},{"no":"04","title":"Adapt to change","titleCN":"适应变化","definition":"to adjust one's methods to a new condition","definitionCN":"调整做法以适应新的条件","example":"Older workers should cope with new software if the training is patient.","exampleCN":"如果培训足够耐心，年长的员工应能适应新软件。","why":"Coping with change is turning sideways rather than letting go of the umbrella.","whyCN":"应对变化，是侧过身，而不是松手丢伞。"},{"no":"05","title":"Live with illness or disability","titleCN":"应对疾病与残障","definition":"to carry on daily life while managing a long-term condition","definitionCN":"在长期病痛或残障下维持日常生活","example":"Families may cope with a long illness by sharing the care.","exampleCN":"家庭可以通过分担照护来应对长期的病痛。","why":"A long illness is a long contest, and sharing the care is how a family keeps standing.","whyCN":"长期病痛是一场长久的交手，分担照护是家庭继续站住的方式。"},{"no":"06","title":"Get by on limited money","titleCN":"靠有限的钱维持","definition":"to manage daily needs with very little income","definitionCN":"以很少的收入维持日常所需","example":"A family can cope with a small budget if housing costs stay low.","exampleCN":"如果住房开支不高，一个家庭可以靠小笔预算维持。","why":"A small budget is a load one carries by leaving things out, not by winning.","whyCN":"小预算是一副靠舍弃来承担的担子，而不是靠取胜。"},{"no":"07","title":"Bear a mechanical load","titleCN":"承受机械负荷","definition":"to carry a physical load without failing","definitionCN":"承受物理负荷而不失效","example":"The old dam must cope with the weight of water after heavy snow.","exampleCN":"大雪之后，这座旧坝必须承受水的重量。","why":"The everyday sense of managing a burden extends naturally to structures that must hold under load.","whyCN":"日常「承担重负」的意思，自然延伸到必须承压的结构上。"},{"no":"08","title":"Balance competing demands","titleCN":"应付多方诉求","definition":"to keep several parties satisfied enough to proceed","definitionCN":"使多方各自得到起码的满足以便推进","example":"A chair must cope with members who want opposite things.","exampleCN":"主持人必须应付想要相反结果的成员。","why":"A chair meets opposite demands by standing between them rather than over them.","whyCN":"主持人站在相反诉求之间，而不是压在其上。"},{"no":"09","title":"Endure an emotional loss","titleCN":"承受情感打击","definition":"to continue living after a loss without being overwhelmed","definitionCN":"在失去之后继续生活而不被压垮","example":"Children may cope with grief better when routines are kept.","exampleCN":"若日常节律得以保持，孩子可能更好地承受悲伤。","why":"Grief is a blow that cannot be avoided, only stood through.","whyCN":"悲伤是一击无法躲开，只能撑过去。"}],"etymology":{"intro":{"en":"The phrase joins a verb that once meant to strike or to trade blows with a preposition of accompaniment. Coping is meeting a difficulty head on and continuing to stand.","cn":"这个短语把曾经表示「打击、交手」的动词与表示「与、同」的介词结合起来。所谓应对，就是正面遇上困难，并且继续站住。"},"items":[{"era":"GREEK KOLAPHOS","en":"Kolaphos meant a blow or a cuff, especially one given with the fist.","cn":"这个词意为「一击、一巴掌」，尤指用拳头打。"},{"era":"LATIN COLAPHUS","en":"Latin borrowed the word as colaphus, still naming a blow.","cn":"拉丁语借入这个词，仍然表示「一击」。"},{"era":"OLD FRENCH COUP","en":"French shortened it to coup, a stroke or a blow, and built the verb couper, to strike.","cn":"法语把它缩短为「一击、一记」，并造出「打击」的动词。"},{"era":"ENGLISH COPE, 14TH CENTURY","en":"English took the verb for meeting an opponent in combat, and only later for meeting any difficulty.","cn":"英语在十四世纪引入这个动词，指在战斗中迎击对手，后来才指迎接任何困难。"},{"era":"PHRASE WITH WITH","en":"The frame with the preposition of accompaniment fixed in the nineteenth century for managing burdens, loads and losses. The exact first citation is uncertain.","cn":"与伴随介词搭配的框架在十九世纪固定下来，用于应对负担、负荷与丧失。最早书证年代不确定。"}]},"similar":{"note":{"en":"The first group shares the blow word or looks close to it; the second group holds other verbs for dealing with a difficulty.","cn":"第一组共享「打击」之词或形近；第二组是其他表示「处理困难」的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cope","ipa":"/kəʊp/","tag":"bare verb, no object","definition":"Used alone, it means to manage or to get by; the preposition is what brings the specific difficulty into the sentence.","definitionCN":"单独使用时意为「应付、过得去」；正是介词把具体的困难带进句子。"},{"word":"coping","ipa":"/ˈkəʊpɪŋ/","tag":"the noun of manner","definition":"It names the way a person manages, as in a coping strategy; the phrase names the encounter itself.","definitionCN":"名词指一个人应对的方式，如应对策略；短语指遭遇本身。"},{"word":"coup","ipa":"/kuːp/","tag":"same source, different meaning","definition":"It still means a stroke or a sudden seizure of power; it shares the blow word but not the sense of endurance.","definitionCN":"仍指「一击」或「突然夺取政权」；共享「打击」之词，却不含「撑住」之意。"},{"word":"copy","ipa":"/ˈkɒpi/","tag":"look-alike, unrelated","definition":"It comes from a Latin word for abundance, not from the blow word; the resemblance is only in spelling.","definitionCN":"它出自拉丁语表示「充裕」的词，与「打击」之词无关，相似只在拼写。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deal with","ipa":"/diːl wɪð/","tag":"take action on","definition":"The common phrase for taking action on a problem; it says nothing about whether one has enough resources.","definitionCN":"处理问题的常用短语，不涉及是否有足够资源。"},{"word":"handle","ipa":"/ˈhændl/","tag":"manage skillfully","definition":"It stresses skill in managing a situation, often with a lighter tone than the phrase.","definitionCN":"强调处理局面的技巧，语气常比本短语轻松。"},{"word":"endure","ipa":"/ɪnˈdjʊə/","tag":"suffer through","definition":"It stresses lasting through pain without any implication of managing the cause.","definitionCN":"强调在痛苦中撑过去，不含「处理成因」之意。"},{"word":"grapple with","ipa":"/ˈɡræpl wɪð/","tag":"wrestle closely","definition":"It suggests close, difficult struggle with a problem, and is more vivid than the phrase.","definitionCN":"暗示与问题近身缠斗，比本短语更形象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the umbrella in the wind, the rewritten rota, the dam after snow and the shared care.","cn":"正常联想使用风中的伞、改写的排班表、雪后的坝与分担的照护四个场景。"},"normal":[{"en":"An umbrella bent backward by wind, held on and turned sideways.","cn":"伞被风吹得反折，人没有松手，只是侧过身。"},{"en":"A rota rewritten three times in one night.","cn":"一张排班表，一夜之间改了三次。"},{"en":"An old dam holding back meltwater after a heavy snow.","cn":"大雪之后，旧坝拦住融水。"},{"en":"Two sisters sharing the care of an ill parent.","cn":"两姐妹分担照护生病的母亲。"},{"en":"A child whose bedtime stays the same through a family upheaval.","cn":"家里天翻地覆，孩子的睡觉时间却没变。"}],"abstract":[{"en":"Coping is not solving: it is continuing while the problem continues.","cn":"应对不是解决：问题还在，人还在往前走。"},{"en":"The word began as trading blows, and it still carries the stance of a fighter who has not fallen.","cn":"这个词最初指交手，至今仍带着「没有倒下」的姿态。"},{"en":"Resources decide what coping looks like: the same difficulty needs a different answer in a rich room and a poor one.","cn":"资源决定应对的模样：同一个困难，在富裕的屋里与拮据的屋里需要不同答案。"}]},"examples":[{"en":"Small firms must cope with delays that larger rivals can absorb.","cn":"小公司必须应对大对手能吸收掉的延误。"},{"en":"Coastal towns may cope with a rise in sea level only with new defences.","cn":"沿海城镇只有建起新防线，才可能应对海平面上升。"},{"en":"A bridge designed for horses must cope with modern truck traffic.","cn":"为马车设计的桥，必须承受现代卡车的通行。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「寇普 威兹」：把「交手」记成顶着风撑伞不肯松手——风还在，人还站着，这就是应对","word":"cope with"},"root":"核心动词出自希腊语表示「一击、一拳」的词，经拉丁语与古法语进入英语，本义是「打击、交手」，后引申为「迎上困难并撑住」。介词为本族常用词，意为「与、同」。短语整体强调用现有资源继续对付，而不保证解决。","sensesIntro":{"en":"Nine senses meet a load and keep going: pressure, workload, crisis, change, illness, a small budget, a physical load, competing demands, and grief.","cn":"九个义项都是遇上一个负荷并继续前行：压力、工作量、危机、变化、疾病、小预算、物理负荷、相互冲突的诉求与悲伤。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person holding an umbrella that the wind has bent backward, turning sideways rather than letting go.","cn":"核心意象：一个人撑着被风吹反的伞，侧过身继续走，而不是松手。"},"chain":["MEET THE BLOW","HOLD ONE'S GROUND","USE WHAT ONE HAS","ABSORB THE LOAD","KEEP GOING","LIVE THROUGH IT"],"branches":[{"senses":"01 · 09","en":"THE INNER LOAD: exam strain and grief are carried without visible machinery.","cn":"内在负荷：考试压力与悲伤在没有可见器械的情况下被承住。"},{"senses":"02 · 03","en":"THE SUDDEN SURGE: an office absorbs extra applications, a hospital absorbs casualties.","cn":"骤增：办事处吸收额外申请，医院吸收大量伤员。"},{"senses":"04 · 08","en":"THE ADJUSTED STANCE: new software, opposite demands, a chair turning sideways.","cn":"调整姿态：新软件、相反诉求，主持人侧身应对。"},{"senses":"05 · 06","en":"THE LONG HAUL: shared care and a tight budget are managed day after day.","cn":"长期支撑：分担照护与紧张预算，一天一天地维持。"},{"senses":"07","en":"THE PHYSICAL LOAD: a dam or a bridge must hold under weight.","cn":"物理负荷：坝或桥必须在重量下撑住。"}]},"affixes":{"intro":{"en":"The family is small and verbal; it grew from a word for a blow, and the endings name the manner and the person rather than a Latin technical vocabulary.","cn":"这个词族人少且以动词为主；它从表示「一击」的词长成，词尾命名方式与人，而不是拉丁技术词汇。"},"latinIntro":{"en":"Greek and Latin both supplied the blow word, French reshaped it, and English added its own endings.","cn":"希腊语与拉丁语都提供了「打击」之词，法语加以改写，英语再加上自己的词尾。"},"items":[{"word":"kolaphos","structure":"Greek noun","meaning":"a blow, a cuff","meaningCN":"一击；一巴掌","example":"The oldest word in the family.","exampleCN":"词族里最古老的一词。"},{"word":"colaphus","structure":"Latin noun","meaning":"a blow","meaningCN":"一击","example":"The Latin borrowing of the same word.","exampleCN":"同一词的拉丁语借形。"},{"word":"coup","structure":"Old French noun","meaning":"a stroke, a blow","meaningCN":"一击；一记","example":"The shortened French form.","exampleCN":"法语中的缩短形式。"},{"word":"couper","structure":"Old French verb","meaning":"to strike","meaningCN":"打击","example":"The verb English borrowed.","exampleCN":"英语借入的动词。"},{"word":"cope","structure":"English verb","meaning":"to meet and hold one's ground","meaningCN":"迎上并站住","example":"The modern English verb.","exampleCN":"现代英语动词。"},{"word":"-ing","structure":"verb ending","meaning":"ongoing action or manner","meaningCN":"进行中的动作或方式","example":"It forms the word for a way of managing.","exampleCN":"它构成表示「应对方式」的词。"},{"word":"-ed","structure":"verb ending","meaning":"past or completed","meaningCN":"过去或已完成","example":"It forms the past tense of the verb.","exampleCN":"它构成动词的过去式。"},{"word":"with","structure":"preposition","meaning":"together with, against","meaningCN":"与；同；对着","example":"It brings the difficulty into the sentence.","exampleCN":"它把困难带进句子。"}],"latinEntries":[{"word":"colaphus","structure":"Latin noun","meaning":"a blow","meaningCN":"一击"},{"word":"colpus","structure":"Late Latin noun","meaning":"a stroke, a blow","meaningCN":"一击；一记"},{"word":"colaphizare","structure":"Late Latin verb","meaning":"to strike with the fist","meaningCN":"用拳击打"}],"derivatives":[{"word":"coping","pos":"n./adj.","zh":"由动词加动名词词尾构成，义为「应对方式」"},{"word":"cope","pos":"v.","zh":"核心动词，义为「应付」"},{"word":"coper","pos":"n.","zh":"由动词加施事词尾构成，义为「能应付的人」，较少用"},{"word":"coped","pos":"v.","zh":"核心动词的过去式与过去分词"}]}},{"word":"depend on","ipa_uk":"/dɪˈpend ɒn/","ipa_us":"/dɪˈpend ɑːn/","definition_zh":"依赖；依靠；取决于；信赖；指望","definition_en":"to rely on something for support or survival, to be decided by a condition, or to trust a person","core_image":"一只吊篮用一根绳子挂在梁上，篮里的重量一增，绳子就绷紧，梁也跟着微微下沉","scene":"果园主人蹲在干裂的土上，抬头看天，又翻看手机里的降雨预报。The size of the crop may depend on rain in the next three weeks.","sceneCN":"这里指收成多少由某个条件决定（第 2 个义项：结果取决于某一因素）；句意为收成的大小可能取决于未来三周的降雨。图中可辨识物件：干裂的土、果树、降雨预报、水桶。","pos":[{"tag":"v. phr.","zh":"依赖；依靠（不及物动词短语加介词，后接所依靠的人或物）"},{"tag":"v. phr.","zh":"取决于；视……而定（后接条件、变量或情况）"}],"collocations":[{"phrase":"depend on water","zh":"依赖水源"},{"phrase":"depend on the weather","zh":"取决于天气"},{"phrase":"depend on the outcome","zh":"视结果而定"},{"phrase":"depend on exports","zh":"依赖出口"},{"phrase":"depend on a habitat","zh":"依赖某种栖息地"},{"phrase":"depend on volunteers","zh":"依靠志愿者"},{"phrase":"depend on temperature","zh":"随温度变化"}],"forms":[{"label":"三单","form":"depends on"},{"label":"过去式","form":"depended on"},{"label":"过去分词","form":"depended on"},{"label":"现在分词","form":"depending on"},{"label":"情态后原形","form":"depend on"}],"derivatives":[{"word":"dependence","pos":"n.","zh":"由动词加表示状态的名词尾构成，义为「依赖；依靠」"},{"word":"dependent","pos":"adj./n.","zh":"由动词加形容词尾构成，义为「依赖的；受扶养者」"},{"word":"dependable","pos":"adj.","zh":"由动词加「可……的」词尾构成，义为「可靠的」"},{"word":"independent","pos":"adj.","zh":"由否定前缀加形容词构成，义为「独立的」"},{"word":"dependency","pos":"n.","zh":"由形容词加名词尾构成，义为「依附关系；属地」"}],"senses":[{"no":"01","title":"Rely on for survival","titleCN":"依靠……生存","definition":"to need something in order to live or to keep operating","definitionCN":"为了生存或继续运转而需要某物","example":"The village must depend on the spring for drinking water.","exampleCN":"这个村庄必须依靠那眼泉水取饮用水。","why":"The core verb meant to hang from something; what hangs from a support cannot stand without it.","whyCN":"核心动词本义是「从某物上悬垂」；挂在支撑物上的东西，离开它便立不住。"},{"no":"02","title":"Be decided by a condition","titleCN":"取决于某个条件","definition":"to have one's outcome fixed by a stated factor","definitionCN":"结果由某一明确因素决定","example":"The harvest can depend on two weeks of dry weather in June.","exampleCN":"收成可能取决于六月里连续两周的干燥天气。","why":"What hangs from a support has its place fixed by that support, so a harvest hangs from rain.","whyCN":"挂在支撑上的东西，位置由支撑决定，因此收成挂在雨上。"},{"no":"03","title":"Trust a person","titleCN":"信赖某人","definition":"to place one's confidence in someone's reliability","definitionCN":"把信心放在某人的可靠之上","example":"Readers should depend on the handbook only after checking its sources.","exampleCN":"读者只有在核对手册的来源之后，才应信赖它。","why":"Trust is hanging one's confidence on another person's reliability.","whyCN":"信赖，是把信心挂在另一个人的可靠上。"},{"no":"04","title":"Rely economically","titleCN":"经济上依赖","definition":"to have one's income or livelihood tied to one source","definitionCN":"收入或生计系于单一来源","example":"The island may depend on a single crop for most of its income.","exampleCN":"这座岛可能依赖单一作物获取大部分收入。","why":"A single crop is a single rope holding an island's income.","whyCN":"单一作物就是吊住整岛收入的一根绳子。"},{"no":"05","title":"Rely on a habitat","titleCN":"依赖某种栖息地","definition":"to survive only in a particular environment","definitionCN":"只能在特定环境中存活","example":"The beetle can depend on one kind of rotting log.","exampleCN":"这种甲虫可能只依赖一种腐木生存。","why":"A beetle hangs from one kind of log, and nowhere else holds it up.","whyCN":"甲虫挂在一种腐木上，别处托不住它。"},{"no":"06","title":"Vary with a variable","titleCN":"随变量变化","definition":"to change in value as another measured quantity changes","definitionCN":"数值随另一测量量的变化而变化","example":"The measured rate should depend on temperature and pressure.","exampleCN":"测得的速率应随温度与压力而变化。","why":"A measured rate hangs from the conditions that set it.","whyCN":"测得的速率挂在决定它的那些条件上。"},{"no":"07","title":"Be conditional in planning","titleCN":"视情况而定","definition":"to remain undecided until a future condition is known","definitionCN":"在未来的条件明确之前不作定论","example":"The launch may depend on the wind at the pad.","exampleCN":"发射可能要看发射台上的风况而定。","why":"A launch hangs from the wind at the pad, a condition not yet known.","whyCN":"发射挂在发射台的风况上，而那条件尚未可知。"},{"no":"08","title":"Rely on a substance","titleCN":"依赖某种物质","definition":"to be unable to function without a drug or a habit","definitionCN":"离开某种药物或习惯便无法正常运转","example":"Patients should not depend on sleeping pills for more than a month.","exampleCN":"患者不应连续一个多月依赖安眠药。","why":"A sleeper hangs from a pill when the body can no longer hold the night alone.","whyCN":"当身体无法独自撑过夜晚，睡眠就挂在药片上。"},{"no":"09","title":"Count on someone to act","titleCN":"指望某人去做","definition":"to expect a person to perform a task one needs done","definitionCN":"期待某人去完成自己需要完成的事","example":"The committee must depend on volunteers to staff the doors.","exampleCN":"委员会必须依靠志愿者来守门。","why":"A committee hangs from volunteers when no one is paid to stand at the door.","whyCN":"没有人领薪守门时，委员会就挂在志愿者身上。"}],"etymology":{"intro":{"en":"The phrase centres on a Latin verb meaning to hang down from something. Every sense keeps the picture of a weight suspended: what hangs needs the thing it hangs from, and its position is fixed by that support.","cn":"这个短语的核心是拉丁语中表示「从某物下垂」的动词。每个义项都保留「重物悬垂」的画面：挂着的东西需要所挂之处，它的位置也由那个支撑决定。"},"items":[{"era":"LATIN PENDERE","en":"Pendere meant to hang, to weigh, and it stands behind pendant, suspend and pendulum.","cn":"这个词意为「悬挂、称重」，吊坠、悬停与摆锤诸词都由它而来。"},{"era":"LATIN DEPENDERE","en":"De- 'down from' plus pendere produced dependere, to hang from something, to be attached to it.","cn":"表示「自下」的前缀加「悬挂」，构成「挂在某物上、附着于它」的动词。"},{"era":"FRENCH DEPENDRE","en":"Old French carried the verb with the sense of being subject to another's will.","cn":"古法语把这个动词带入「受他人意志支配」的意思。"},{"era":"ENGLISH DEPEND, 15TH CENTURY","en":"English took it first for being sustained by something, then for being decided by a condition.","cn":"英语最初用它表示「由某物支撑」，随后表示「由某条件决定」。"},{"era":"PHRASE WITH ON","en":"The frame with on fixed in the following centuries for support, condition and trust alike. The exact first citation is uncertain.","cn":"与介词搭配的框架在此后几个世纪固定下来，兼指支撑、条件与信任。最早书证年代不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin hanging verb; the second group holds other verbs of relying or being decided.","cn":"第一组共享拉丁「悬挂」动词；第二组是其他表示「依靠」或「由……决定」的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dependent","ipa":"/dɪˈpendənt/","tag":"the adjective","definition":"It describes a person or thing that relies on another; the phrase states the reliance as an action.","definitionCN":"它形容依赖他人的人或物；短语则把这种依赖说成一个动作。"},{"word":"dependence","ipa":"/dɪˈpendəns/","tag":"the noun","definition":"The noun names the state of relying; it cannot take the specific condition as its object.","definitionCN":"名词指「依赖的状态」，不能像短语那样带出具体的条件。"},{"word":"independent","ipa":"/ˌɪndɪˈpendənt/","tag":"negated form","definition":"It says that nothing hangs from another support, the exact reverse of the phrase.","definitionCN":"表示不挂在别的支撑上，正是本短语的反面。"},{"word":"pending","ipa":"/ˈpendɪŋ/","tag":"same Latin root","definition":"From the same hanging verb, it means awaiting a decision; it shares the image but not the reliance.","definitionCN":"同出「悬挂」动词，意为「待决的」；共享意象，却不含「依靠」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rely on","ipa":"/rɪˈlaɪ ɒn/","tag":"trust in support","definition":"It stresses confidence in the support, and is common for people and services rather than for equations.","definitionCN":"强调对支撑的信心，多用于人与服务，少用于方程式。"},{"word":"count on","ipa":"/kaʊnt ɒn/","tag":"expect confidently","definition":"It adds the note of expecting a person to act; the phrase can mean this but does not stress expectation.","definitionCN":"多一层「期待某人行动」的意思；本短语可含此义，但不强调期待。"},{"word":"hinge on","ipa":"/hɪndʒ ɒn/","tag":"turn on one point","definition":"A vivid phrase for an outcome that turns on a single factor, as a door turns on a hinge.","definitionCN":"形象地表示结果系于单一因素，如门绕铰链转动。"},{"word":"be contingent on","ipa":"/bi kənˈtɪndʒənt ɒn/","tag":"formal condition","definition":"A formal phrase for a result that follows only if a condition holds; it is limited to the conditional sense.","definitionCN":"正式表示「只有在某条件成立时结果才成立」，只覆盖条件义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the hanging basket, the dry field, the sleeping pill and the volunteer at the door.","cn":"正常联想使用吊篮、干裂的田、安眠药与守门的志愿者四个场景。"},"normal":[{"en":"A basket hung from a beam: add weight and the rope tightens and the beam dips.","cn":"篮子挂在梁上：加重一点，绳就绷紧，梁也下沉。"},{"en":"A cracked field, a rain forecast, and a farmer doing arithmetic in his head.","cn":"干裂的田、一份降雨预报，农夫在心里算账。"},{"en":"One beetle, one kind of rotting log, nowhere else to go.","cn":"一种甲虫，一种腐木，别处无处可去。"},{"en":"A pill that must be taken or the night does not end.","cn":"一片必须吃的药，不吃夜就到不了头。"},{"en":"A volunteer standing at the door because no one is paid to.","cn":"志愿者守在门口，因为没有人是领薪的。"}],"abstract":[{"en":"To depend is to have one's position fixed by something outside oneself.","cn":"依赖，就是自己的位置由身外之物决定。"},{"en":"Every support is also a limit: what holds you up decides how far you can move.","cn":"每个支撑同时是限制：托住你的东西，也决定你能走多远。"},{"en":"The same hanging image covers water, weather, trust and truth, because all of them hold something up.","cn":"同一个「悬挂」意象覆盖水、天气、信任与真值，因为它们都托着某物。"}]},"examples":[{"en":"Coastal cities may depend on desalination if the rivers keep shrinking.","cn":"若河流继续萎缩，沿海城市可能依赖海水淡化。"},{"en":"The final cost should depend on how much material is reused.","cn":"最终成本应取决于有多少材料被再利用。"},{"en":"A referee must depend on the linesman's view of the touchline.","cn":"裁判必须依靠边裁对边线的判断。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「迪彭德 昂」：把「悬挂」记成吊篮挂在梁上——绳在梁上，篮才不落地，这就是依赖","word":"depend on"},"root":"核心动词出自拉丁语，由表示「自下」的前缀加表示「悬挂、称重」的动词构成，本义是「挂在某物上」，引申为「依靠、由……决定、信赖」。介词为本族常用词。整条短语保留「悬挂者离不开支撑」的意象。","sensesIntro":{"en":"Nine senses hang from something: water, a condition, a person's reliability, a single export, a habitat, a measured variable, a future wind, a drug, and a volunteer.","cn":"九个义项各自挂在一处：水、条件、某人的可靠、单一出口、栖息地、测量变量、未来的风、药物与志愿者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a basket hung from a beam, its rope tightening as weight is added, the beam bending under the pull.","cn":"核心意象：篮子挂在梁上，加重时绳子绷紧，梁也被拉得微弯。"},"chain":["HANG FROM","NEED THE SUPPORT","BE HELD IN PLACE","FOLLOW THE SUPPORT","TRUST THE HOLDER","COUNT ON IT"],"branches":[{"senses":"01 · 04","en":"THE LIVING SUPPORT: a spring and a single crop keep a community alive.","cn":"活命的支撑：泉水与单一作物，维系着一个社区的生存。"},{"senses":"05","en":"THE HABITAT: one kind of rotting log is the only thing that holds a beetle up.","cn":"栖息地：一种腐木，是唯一托住这种甲虫的东西。"},{"senses":"02 · 06 · 07","en":"THE MOVING VALUE: a harvest, a rate or a launch shifts with a factor one cannot fix.","cn":"变动的值：收成、速率或发射，随一个无法固定的因素起落。"},{"senses":"03 · 09","en":"THE TRUSTED PERSON: a handbook's sources and a volunteer at the door are relied on to hold.","cn":"被信任的人：手册的来源与门口的志愿者，被指望守住。"},{"senses":"08","en":"THE HELD HABIT: a pill that must be taken before sleep arrives.","cn":"被抓住的习惯：不吃药就睡不着的夜晚。"}]},"affixes":{"intro":{"en":"The family hangs from a Latin weighing verb; the prefix points downward, and the endings name the state, the person and the negation.","cn":"这个词族挂在拉丁语「称重、悬挂」动词上；前缀指向下方，词尾命名状态、人与否定形式。"},"latinIntro":{"en":"Latin pendere and dependere passed through French into English, which added its own endings and its own negative prefix.","cn":"拉丁语的「悬挂」与「依附」动词经法语进入英语，英语加上自己的词尾与否定前缀。"},"items":[{"word":"de-","structure":"prefix","meaning":"down from","meaningCN":"自下；向下","example":"It marks the weight as hanging down from a support.","exampleCN":"它标出重物从支撑处垂下。"},{"word":"pendere","structure":"Latin verb","meaning":"to hang, to weigh","meaningCN":"悬挂；称重","example":"The hanging verb at the base.","exampleCN":"底层的「悬挂」动词。"},{"word":"dependere","structure":"Latin verb","meaning":"to hang from, be attached","meaningCN":"挂在……上；附着","example":"The direct source of the English verb.","exampleCN":"英语动词的直接来源。"},{"word":"depend-","structure":"English stem","meaning":"to rely","meaningCN":"依靠","example":"The stem used in the modern phrase.","exampleCN":"现代短语所用的词干。"},{"word":"-ence","structure":"noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It forms the noun of reliance.","exampleCN":"它构成表示「依赖」的名词。"},{"word":"-ent","structure":"adjective ending","meaning":"having the quality","meaningCN":"具有该性质的","example":"It forms the adjective for one who relies.","exampleCN":"它构成表示「依赖者」的形容词。"},{"word":"-able","structure":"adjective ending","meaning":"able to be","meaningCN":"可被……的","example":"It forms the adjective for what can be relied on.","exampleCN":"它构成「可靠的」形容词。"},{"word":"in-","structure":"negative prefix","meaning":"not","meaningCN":"不；非","example":"It reverses the adjective into independence.","exampleCN":"它把形容词翻成「独立」。"}],"latinEntries":[{"word":"pendere","structure":"Latin verb","meaning":"to hang, weigh","meaningCN":"悬挂；称重"},{"word":"dependere","structure":"Latin verb","meaning":"to hang from, be attached","meaningCN":"挂在……上；依附"},{"word":"dependentia","structure":"Late Latin noun","meaning":"a hanging from, dependence","meaningCN":"依附；依赖"}],"derivatives":[{"word":"dependence","pos":"n.","zh":"由动词加状态名词尾构成，义为「依赖」"},{"word":"dependent","pos":"adj./n.","zh":"由动词加形容词尾构成，义为「依赖的」"},{"word":"dependable","pos":"adj.","zh":"由动词加「可……的」词尾构成，义为「可靠的」"},{"word":"independent","pos":"adj.","zh":"由否定前缀加形容词构成，义为「独立的」"}]}},{"word":"distinguish between","ipa_uk":"/dɪˈstɪŋɡwɪʃ bɪˈtwiːn/","ipa_us":"/dɪˈstɪŋɡwɪʃ bɪˈtwiːn/","definition_zh":"区分；辨别；分辨；把……与……区别开来；分清","definition_en":"to recognise the difference between two or more things that may be similar, and to treat them as separate","core_image":"两只几乎一样的杯子摆在桌上，检验员举起放大镜，靠杯底一处极细的刻痕把两只分到不同的托盘里","scene":"桌上摆着两只几乎一样的玻璃瓶，标签被水泡糊了，研究员举起放大镜比对瓶口的刻痕。A trained eye must distinguish between the two samples before any test begins.","sceneCN":"这里指凭借细微差别把两个相似样本分开（第 1 个义项：辨认出两物之间的差别）；句意为在开始任何测试之前，受过训练的眼睛必须把这两个样本区分开来。图中可辨识物件：两只玻璃瓶、模糊的标签、放大镜、两只托盘。","pos":[{"tag":"v. phr.","zh":"区分；辨别（及物动词短语加介词，后接被区分的两方）"},{"tag":"v. phr.","zh":"分清（后接抽象类别，如事实与意见、主次、阶段）"}],"collocations":[{"phrase":"distinguish between right and wrong","zh":"分辨是非"},{"phrase":"distinguish between fact and opinion","zh":"区分事实与意见"},{"phrase":"distinguish between the two species","zh":"区分这两个物种"},{"phrase":"distinguish between cause and effect","zh":"区分因与果"},{"phrase":"distinguish between the stages","zh":"区分各阶段"},{"phrase":"distinguish between needs and wants","zh":"分清需要与想要"}],"forms":[{"label":"三单","form":"distinguishes between"},{"label":"过去式","form":"distinguished between"},{"label":"过去分词","form":"distinguished between"},{"label":"现在分词","form":"distinguishing between"},{"label":"情态后原形","form":"distinguish between"}],"derivatives":[{"word":"distinction","pos":"n.","zh":"由动词加表示行为的名词尾构成，义为「区别；优异」"},{"word":"distinct","pos":"adj.","zh":"由同一词干加形容词尾构成，义为「截然不同的；清晰的」"},{"word":"distinctive","pos":"adj.","zh":"由词干加形容词尾构成，义为「有特色的」"},{"word":"distinguishable","pos":"adj.","zh":"由动词加「可……的」词尾构成，义为「可区分的」"},{"word":"distinguished","pos":"adj.","zh":"由过去分词转作形容词，义为「卓越的」"}],"senses":[{"no":"01","title":"Tell two similar things apart","titleCN":"把两个相似之物分开","definition":"to recognise which of two similar things is which","definitionCN":"辨认出两个相似之物各自是哪一个","example":"Students must distinguish between correlation and causation.","exampleCN":"学生必须区分相关关系与因果关系。","why":"The core verb meant to prick apart, to mark a separation with a point; two things are told apart when a line is drawn between them.","whyCN":"核心动词本义是「刺开、以尖点标出分界」；两物被分开，正因为在它们之间画下了一条线。"},{"no":"02","title":"Separate true from false","titleCN":"辨别真伪","definition":"to judge which account or claim is true and which is not","definitionCN":"判断哪种说法为真、哪种不为真","example":"Readers should distinguish between a claim and its evidence.","exampleCN":"读者应区分一个主张与支持它的证据。","why":"A mark drawn between a claim and its evidence keeps the two from merging.","whyCN":"在说法与证据之间画一道记号，两者就不会混成一体。"},{"no":"03","title":"Sort into categories","titleCN":"把事物分入类别","definition":"to assign similar-looking things to different classes","definitionCN":"把外观相似的东西归入不同的类别","example":"The key must distinguish between two species that look almost alike.","exampleCN":"检索表必须能把两个外观几乎相同的物种区分开。","why":"A key is a set of pricking points that sends similar forms down different lines.","whyCN":"检索表是一组尖点，把相似形态送到不同的线上。"},{"no":"04","title":"Separate fact from opinion","titleCN":"区分事实与意见","definition":"to keep observed facts apart from judgements about them","definitionCN":"把观察到的事实与对它的判断分开","example":"A careful report should distinguish between what was seen and what was inferred.","exampleCN":"谨慎的报告应把所见与所推断区分开来。","why":"A line between what was seen and what was guessed is the first duty of a report.","whyCN":"在所见与所猜之间画线，是报告的第一项义务。"},{"no":"05","title":"Tell symptoms apart","titleCN":"区分症状","definition":"to identify which of two similar conditions is present","definitionCN":"判断呈现的是两种相似状况中的哪一种","example":"Clinicians may distinguish between a viral and a bacterial infection only with a test.","exampleCN":"临床医生只有借助检验，才可能区分病毒性与细菌性感染。","why":"Two infections look alike until a test pricks the difference out.","whyCN":"两种感染外观相似，直到检验把差别刺出来。"},{"no":"06","title":"Hear a fine difference","titleCN":"分辨细微差别","definition":"to perceive a small difference in sound or appearance","definitionCN":"察觉声音或外观上的细微差别","example":"Trained ears can distinguish between the two dialects within a sentence.","exampleCN":"受过训练的耳朵能在一句话之内分辨这两种方言。","why":"A trained ear marks a difference too small for an untrained one.","whyCN":"受过训练的耳朵，标出未受训练者听不出的差别。"},{"no":"07","title":"Draw a legal line","titleCN":"区分法律界线","definition":"to mark where one legal category ends and another begins","definitionCN":"标出一个法律类别终止、另一类别开始之处","example":"The statute must distinguish between negligence and deliberate harm.","exampleCN":"该法规必须把过失与故意伤害区分开。","why":"A statute is a line drawn between negligence and intent.","whyCN":"法规是在过失与故意之间画下的一道线。"},{"no":"08","title":"Rank by importance","titleCN":"分清主次","definition":"to decide which demands matter more than others","definitionCN":"判断哪些需求比另一些更重要","example":"A manager should distinguish between urgent tasks and merely loud ones.","exampleCN":"管理者应分清紧急任务与只是叫得响的任务。","why":"Ranking demands is drawing a line between what must be done and what merely shouts.","whyCN":"给需求排次序，就是在「必须做」与「只是叫得响」之间画线。"},{"no":"09","title":"Divide periods in history","titleCN":"区分历史阶段","definition":"to mark a boundary between phases of a continuing process","definitionCN":"在一个连续过程中标出前后阶段的界限","example":"Historians may distinguish between the early and late phases of the migration.","exampleCN":"历史学者可以把这次迁徙分为早期与晚期阶段。","why":"A period boundary is a mark on a process that never stopped moving.","whyCN":"时期分界，是在从未停止的过程上作下的记号。"}],"etymology":{"intro":{"en":"The phrase uses a Latin verb that meant to prick apart. The point of a stylus makes a visible mark, and a mark is what turns one mass into two recognised things.","cn":"这个短语用的是拉丁语中表示「刺开」的动词。尖笔点下会留下可见的记号，而记号正是把一团东西分成两样可辨认之物的关键。"},"items":[{"era":"LATIN STINGUERE","en":"Stinguere meant to prick or to quench, and it is related to the English word sting.","cn":"这个词意为「刺、戳」，也与英语中表示「蜇刺」的词同源。"},{"era":"LATIN DISTINGUERE","en":"Dis- 'apart' plus stinguere produced distinguere, to separate by marking, to set apart, to tell apart.","cn":"表示「分开」的前缀加「刺」，构成「以记号分开、使分离、辨别」的动词。"},{"era":"LATIN DISTINCTUS","en":"The participle described things that have been marked off from one another, and it gave English distinct.","cn":"分词形容「已被彼此标开」之物，并给出英语中表示「截然不同」的形容词。"},{"era":"ENGLISH DISTINGUISH, 16TH CENTURY","en":"English took the verb through French, first for perceiving a difference, then for treating things separately.","cn":"英语经法语引入这个动词，先指「察觉差别」，后指「分别对待」。"},{"era":"PHRASE WITH BETWEEN AND WITH FROM","en":"English fixed two frames: between for the pair being separated, from for the thing left behind. The exact first citations are uncertain.","cn":"英语固定了两个框架：一个用于被分开的两方，一个用于被撇开的那一方。两者最早书证年代均不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin pricking root and includes the partner frame with a different preposition; the second group holds other verbs of telling things apart.","cn":"第一组共享拉丁「刺开」词根，其中还包含换用另一介词的伙伴框架；第二组是其他「辨别」动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"distinguish from","ipa":"/dɪˈstɪŋɡwɪʃ frəm/","tag":"partner frame","definition":"With from, only one party is named and the other is left implied; with between, both parties are named.","definitionCN":"换用另一介词时只点出一方，另一方隐含；用表示「之间」的介词时两方都要点出。"},{"word":"distinct","ipa":"/dɪˈstɪŋkt/","tag":"the adjective","definition":"It describes things already marked apart; the phrase is the act of marking them.","definitionCN":"形容词形容已经被分开的东西；短语则是「分开」这一动作。"},{"word":"distinction","ipa":"/dɪˈstɪŋkʃn/","tag":"the noun","definition":"It names the difference itself, including the sense of high honour; it does not take the two parties as objects.","definitionCN":"名词指差别本身，也指「卓越」；不能像短语那样带出两方。"},{"word":"distinctive","ipa":"/dɪˈstɪŋktɪv/","tag":"same root, different ending","definition":"It means characteristic of one thing rather than separating two; a distinctive mark identifies, it does not divide.","definitionCN":"意为「某物特有的」，而非「分开两物」；特有标记用于识别，不用于划分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"differentiate between","ipa":"/ˌdɪfəˈrenʃieɪt bɪˈtwiːn/","tag":"technical synonym","definition":"A formal synonym common in science and medicine; it stresses analysis of differences.","definitionCN":"科学和医学中常用的正式同义说法，强调对差别作分析。"},{"word":"tell apart","ipa":"/tel əˈpɑːt/","tag":"plain everyday phrase","definition":"The everyday way to say the same thing; it is more colloquial and less formal.","definitionCN":"日常说法，意思相同，但更口语、更不正式。"},{"word":"discriminate between","ipa":"/dɪˈskrɪmɪneɪt bɪˈtwiːn/","tag":"perceive differences","definition":"In neutral use it means to perceive fine differences; in social use it refers to unfair treatment.","definitionCN":"中性用法指察觉细微差别；社会语境中则指不公平对待。"},{"word":"separate","ipa":"/ˈsepəreɪt/","tag":"put apart","definition":"It stresses physically putting things apart, not only noticing a difference.","definitionCN":"强调把东西实际分开，而不只是察觉差别。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two bottles, the taxonomy key, the symptom chart and the period boundary.","cn":"正常联想使用两只玻璃瓶、检索表、症状表与阶段分界四个场景。"},"normal":[{"en":"Two bottles with soaked labels, and one hairline nick on the rim.","cn":"两只标签泡糊的瓶子，瓶口只有一道发丝般的刻痕。"},{"en":"A key that asks one question and sends two species down different lines.","cn":"一张检索表只问一个问题，就把两个物种分到不同的线上。"},{"en":"A report with two columns: what was seen, what was guessed.","cn":"报告分两栏：看见的，与猜的。"},{"en":"Two dialects, one sentence, one vowel that gives them away.","cn":"两种方言，一句话，一个元音就露了底。"},{"en":"A historian drawing a line at the year the ships stopped coming.","cn":"历史学者在船不再来的那一年画下一道线。"}],"abstract":[{"en":"A distinction is a line drawn where none was visible before.","cn":"区分，是在原本看不见的地方画下一道线。"},{"en":"To distinguish well is to know which differences matter for the question at hand.","cn":"善于区分，就是知道哪些差别对眼前的问题才算数。"},{"en":"Naming two things separately is the first act of every science.","cn":"把两样东西分别命名，是每门科学的第一步。"}]},"examples":[{"en":"A good editor must distinguish between a weak argument and a poor translation.","cn":"好编辑必须区分论证薄弱与译文拙劣。"},{"en":"The survey should distinguish between households that own land and those that rent.","cn":"这项调查应把拥有土地的家庭与租地的家庭区分开来。"},{"en":"Buyers may distinguish between a genuine antique and a careful copy only by the joinery.","cn":"买家可能只有凭接榫才能分辨真古董与精细的仿件。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「迪斯丁桂什 比特维恩」：把「刺开」记成用尖笔在两件相似之物中间划一道线——线一划，就分清了","word":"distinguish between"},"root":"核心动词出自拉丁语，由表示「分开」的前缀加表示「刺、戳」的动词构成，本义是「以尖点标出分界、使分离」，引申为「辨别、区分」。该短语用介词引出被分开的两方；若只点出一方，则改用另一个介词。","sensesIntro":{"en":"Nine senses draw a line: between similar objects, truth and claim, categories, fact and opinion, symptoms, sounds, legal categories, priorities and historical phases.","cn":"九个义项都画一道线：相似之物、真与说法、类别、事实与意见、症状、声音、法律类别、主次与历史阶段之间。"},"semanticMap":{"core":{"en":"CORE IMAGE: two near-identical bottles on a table, and a lens finding one hairline nick that sends them to different trays.","cn":"核心意象：桌上两只几乎一样的瓶子，放大镜找到一处发丝般的刻痕，于是它们被放进不同的托盘。"},"chain":["PRICK A MARK","DRAW A LINE","SEE THE DIFFERENCE","NAME BOTH SIDES","SORT THEM","KEEP THEM APART"],"branches":[{"senses":"01 · 03 · 06","en":"THE SENSED DIFFERENCE: objects, species and sounds are separated by a mark one can perceive.","cn":"可感的差别：物体、物种与声音，靠一个可察觉的记号分开。"},{"senses":"02 · 04","en":"THE HONEST PAGE: a claim is kept apart from its evidence, a guess from an observation.","cn":"诚实的页面：说法与证据分开，猜测与观察分开。"},{"senses":"05 · 07","en":"THE DIAGNOSTIC LINE: a test separates two infections, a statute separates negligence from intent.","cn":"诊断线：检验分开两种感染，法规分开过失与故意。"},{"senses":"08","en":"THE WEIGHTED LIST: urgent and merely loud demands are ranked, not merged.","cn":"分权的清单：紧急的与只是响亮的，被排出次序而不是混为一谈。"},{"senses":"09","en":"THE PERIOD BOUNDARY: early and late phases are marked on one continuous process.","cn":"时期分界：在同一条连续过程上标出早期与晚期。"}]},"affixes":{"intro":{"en":"The family is built on a Latin pricking verb; the prefix separates, and the endings name the act, the result and the quality of being marked off.","cn":"这个词族建立在拉丁语「刺」动词上；前缀表示分开，词尾命名动作、结果与「被标开」的性质。"},"latinIntro":{"en":"Latin distinguere and distinctus passed through French into English, which added its own endings and two prepositional frames.","cn":"拉丁语的「分开」动词与分词经法语进入英语，英语加上自己的词尾与两个介词框架。"},"items":[{"word":"dis-","structure":"prefix","meaning":"apart, in different directions","meaningCN":"分开；朝不同方向","example":"It marks the two things as pulled apart.","exampleCN":"它标出两样东西被拉开。"},{"word":"stinguere","structure":"Latin verb","meaning":"to prick, to mark","meaningCN":"刺；作记号","example":"The pricking verb at the base.","exampleCN":"底层的「刺」动词。"},{"word":"distinguere","structure":"Latin verb","meaning":"to mark apart, to separate","meaningCN":"标开；使分离","example":"The direct source of the English verb.","exampleCN":"英语动词的直接来源。"},{"word":"distinctus","structure":"Latin participle","meaning":"marked off, separate","meaningCN":"被标开的；分离的","example":"The participle behind the adjective.","exampleCN":"形容词背后的分词。"},{"word":"-ish","structure":"verb ending","meaning":"to make or to become","meaningCN":"使……；成为","example":"It forms the English verb of separating.","exampleCN":"它构成英语中表示「分开」的动词。"},{"word":"-ion","structure":"noun ending","meaning":"action or result","meaningCN":"动作；结果","example":"It forms the noun of the difference.","exampleCN":"它构成表示「差别」的名词。"},{"word":"-ive","structure":"adjective ending","meaning":"tending to","meaningCN":"有……性质的","example":"It forms the adjective of a characteristic mark.","exampleCN":"它构成表示「特有标记」的形容词。"},{"word":"-able","structure":"adjective ending","meaning":"able to be","meaningCN":"可被……的","example":"It forms the adjective for what can be told apart.","exampleCN":"它构成「可被区分」的形容词。"}],"latinEntries":[{"word":"stinguere","structure":"Latin verb","meaning":"to prick, mark","meaningCN":"刺；作记号"},{"word":"distinguere","structure":"Latin verb","meaning":"to mark apart, separate","meaningCN":"标开；使分离"},{"word":"distinctus","structure":"Latin participle","meaning":"marked off, separate","meaningCN":"被标开的；分离的"}],"derivatives":[{"word":"distinction","pos":"n.","zh":"由动词加行为名词尾构成，义为「区别」"},{"word":"distinct","pos":"adj.","zh":"由词干加形容词尾构成，义为「截然不同的」"},{"word":"distinctive","pos":"adj.","zh":"由词干加形容词尾构成，义为「有特色的」"},{"word":"distinguishable","pos":"adj.","zh":"由动词加「可……的」词尾构成，义为「可区分的」"}]}},{"word":"give rise to","ipa_uk":"/ɡɪv raɪz tə/","ipa_us":"/ɡɪv raɪz tə/","definition_zh":"引起；引发；导致；使……产生；催生","definition_en":"to cause something to begin or to appear, often something unintended, indirect or far-reaching","core_image":"一颗小石子落进静水，第一圈波纹很小，第二圈更大，后面的波纹一路推到池边","scene":"编辑在稿件页边画满问号，因为一句措辞含糊的话可能引出许多不必要的争论。One careless sentence may give rise to a long dispute over meaning.","sceneCN":"这里指引发、使某事开始（第 1 个义项：使争论或问题由此产生）；句意为一句不小心的措辞可能引发一场关于含义的长期争论。图中可辨识物件：稿件、页边问号、红笔、校样。","pos":[{"tag":"v. phr.","zh":"引起；引发（及物动词短语，宾语多为问题、争论、现象）"},{"tag":"v. phr.","zh":"催生；使产生（宾语可为新事物、新领域）"}],"collocations":[{"phrase":"give rise to a dispute","zh":"引发争论"},{"phrase":"give rise to doubt","zh":"引起怀疑"},{"phrase":"give rise to a new field","zh":"催生新领域"},{"phrase":"give rise to concern","zh":"引起担忧"},{"phrase":"give rise to misunderstanding","zh":"造成误解"},{"phrase":"give rise to a reaction","zh":"引发反应"},{"phrase":"give rise to a species","zh":"产生新物种"}],"forms":[{"label":"三单","form":"gives rise to"},{"label":"过去式","form":"gave rise to"},{"label":"过去分词","form":"given rise to"},{"label":"现在分词","form":"giving rise to"},{"label":"情态后原形","form":"give rise to"}],"derivatives":[{"word":"rise","pos":"n./v.","zh":"短语中的核心名词兼动词，义为「上升；升起；兴起」"},{"word":"rising","pos":"adj./n.","zh":"由动词加分词词尾构成，义为「上升的；上升」"},{"word":"risen","pos":"v.","zh":"核心动词的过去分词形式"},{"word":"giver","pos":"n.","zh":"由给予动词加施事词尾构成，义为「给予者」，与本短语关系较远"}],"senses":[{"no":"01","title":"Start a dispute","titleCN":"引发争论","definition":"to cause an argument or a debate to begin","definitionCN":"使争论或辩论开始","example":"The ambiguous clause may give rise to years of argument.","exampleCN":"这条含糊的条款可能引发多年的争论。","why":"Rise is the moment something lifts off the ground; a dispute given rise is one that has left silence and started to move.","whyCN":"「升起」是某物离开地面的那一刻；被「升起」的争论，就是离开沉默开始动起来的那一场。"},{"no":"02","title":"Cause an illness","titleCN":"引发疾病","definition":"to bring about a health problem or an outbreak","definitionCN":"造成健康问题或疾病爆发","example":"Standing water can give rise to a mosquito problem.","exampleCN":"积水可能引发蚊虫问题。","why":"Standing water lets a problem rise and spread beyond its own edge.","whyCN":"积水让问题升起，并越过自己的边缘扩散。"},{"no":"03","title":"Produce a new field","titleCN":"催生新领域","definition":"to cause a new branch of study or practice to appear","definitionCN":"使新的研究或实践分支出现","example":"Cheap sequencing can give rise to a new branch of ecology.","exampleCN":"廉价的测序技术可以催生生态学的一个新分支。","why":"A method lets a new branch of study rise where none stood before.","whyCN":"一种方法让新的研究分支在原本空无处升起。"},{"no":"04","title":"Arouse doubt","titleCN":"引起怀疑","definition":"to cause uncertainty about a claim or a record","definitionCN":"使人们对某个说法或记录产生不确定","example":"The missing page may give rise to doubt about the whole ledger.","exampleCN":"缺失的那一页可能使人们对整本账簿产生怀疑。","why":"A missing page lets uncertainty rise about everything after it.","whyCN":"缺了一页，怀疑就在其后的一切上升起。"},{"no":"05","title":"Lead to litigation","titleCN":"引发诉讼","definition":"to cause legal action to be brought","definitionCN":"使法律诉讼被提起","example":"A vague contract can give rise to costly disputes.","exampleCN":"一份含糊的合同可能引发代价高昂的纠纷。","why":"A vague clause lets a dispute rise into the courts.","whyCN":"含糊条款让纠纷升进法庭。"},{"no":"06","title":"Cause misunderstanding","titleCN":"造成误解","definition":"to produce a false impression in someone's mind","definitionCN":"在他人心中造成错误的印象","example":"A literal translation may give rise to a false impression.","exampleCN":"逐字直译可能造成错误的印象。","why":"A literal rendering lets a wrong picture rise in the reader's mind.","whyCN":"逐字直译让错误画面在读者心里升起。"},{"no":"07","title":"Create an industry","titleCN":"催生产业","definition":"to cause a cluster of businesses to form","definitionCN":"使一群相关企业形成","example":"The new port can give rise to a cluster of repair shops.","exampleCN":"新港口可以催生一群修船作坊。","why":"A port lets a cluster of workshops rise beside it.","whyCN":"港口让一群作坊在它旁边升起。"},{"no":"08","title":"Set off a chain reaction","titleCN":"引发连锁反应","definition":"to start a sequence of effects that feed on one another","definitionCN":"启动一连串彼此推动的后果","example":"One dry summer may give rise to a wave of beetle damage.","exampleCN":"一个干旱的夏天可能引发一波甲虫危害。","why":"One dry summer lets a wave of damage rise and feed on itself.","whyCN":"一个旱夏让一波损害升起并自我喂养。"},{"no":"09","title":"Stir an emotion","titleCN":"引发情感","definition":"to cause a feeling to arise in someone","definitionCN":"使某种感受在某人心中升起","example":"The photograph can give rise to a strong sense of loss.","exampleCN":"那张照片可以引发强烈的失落感。","why":"A photograph lets a feeling rise that had settled out of sight.","whyCN":"一张照片让沉到看不见处的感受重新升起。"}],"etymology":{"intro":{"en":"The phrase joins the native verb of giving to the native noun of rising. The cause is pictured as a hand that lets something go up, and what goes up then spreads on its own.","cn":"这个短语把本族表示「给予」的动词与本族表示「升起」的名词结合。原因被画成一只放手让某物升起的手，而升起之物随后自行扩散。"},"items":[{"era":"OLD ENGLISH GIEFAN","en":"Giefan meant to give, to grant, and it is one of the oldest verbs in the language.","cn":"这个词意为「给予、授予」，是语言中最古老的动词之一。"},{"era":"OLD ENGLISH RISAN","en":"Risan meant to rise, to get up, to move upward, and it stands behind the modern noun and verb.","cn":"这个词意为「升起、起身、向上移动」，现代的名词与动词都由它而来。"},{"era":"ENGLISH PHRASE, 17TH CENTURY","en":"The combination appears in the seventeenth century, first for physical beginnings and soon for disputes and doubts.","cn":"这个组合在十七世纪出现，先指物理上的开始，很快用于争论与怀疑。"},{"era":"SENSE OF INDIRECT CAUSE","en":"Unlike a direct maker, the phrase often names a small trigger whose effects grow on their own; this is why it suits unintended problems.","cn":"与直接的制造者不同，这个短语常指一个小小触发点，其后果自行扩大；这正是它适合「非本意问题」的原因。"},{"era":"FIRST RECORD","en":"The exact first citation of the phrase is uncertain, and the deeper origin of the rising verb is a reconstructed form rather than a recorded one.","cn":"该短语最早的书证年代不确定；表示「升起」的动词更早的来源属重构形式，并非有记录的原形。"}]},"similar":{"note":{"en":"The first group shares the giving or rising words in other combinations; the second group holds other verbs of causing, including the one most often confused with this phrase.","cn":"第一组是同出「给予」或「升起」之词的其他组合；第二组是其他表示「造成」的动词，其中包含最易与本短语混淆的一个。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"give","ipa":"/ɡɪv/","tag":"the bare verb","definition":"The bare verb takes a concrete object, as give a book; the phrase takes an event or a condition that begins.","definitionCN":"单独使用时带具体宾语，如给一本书；短语的宾语则是开始的事件或状况。"},{"word":"rise","ipa":"/raɪz/","tag":"the bare noun or verb","definition":"Alone it names the upward movement itself, not the cause that started it.","definitionCN":"单独使用时指「上升」这一运动本身，而不指启动它的原因。"},{"word":"give way to","ipa":"/ɡɪv weɪ tə/","tag":"different noun","definition":"It means to yield or to be replaced by something, not to cause something to begin.","definitionCN":"意为「让位、被取代」，而不是「使某物开始」。"},{"word":"give up","ipa":"/ɡɪv ʌp/","tag":"different particle","definition":"It means to stop trying or to surrender, with no causal sense at all.","definitionCN":"意为「放弃、投降」，完全不含因果义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bring about","ipa":"/brɪŋ əˈbaʊt/","tag":"direct and often intended","definition":"It stresses a cause that carries a result into fact, and it suits deliberate reforms; the phrase here leans toward indirect or unintended effects.","definitionCN":"强调把结果搬进事实，适合有意的改革；本短语则偏向间接或非本意的后果。"},{"word":"lead to","ipa":"/liːd tə/","tag":"chain of steps","definition":"It follows a path toward a result and stresses the sequence rather than the first spark.","definitionCN":"沿一条路径通向结果，强调过程顺序而非最初的火花。"},{"word":"trigger","ipa":"/ˈtrɪɡə/","tag":"sudden release","definition":"A vivid verb for a small action that sets off a large reaction, close to the eighth sense.","definitionCN":"形象地表示小动作引发大反应，接近第八个义项。"},{"word":"result in","ipa":"/rɪˈzʌlt ɪn/","tag":"outcome focus","definition":"It takes the outcome as its object and looks backward from the result, not forward from the cause.","definitionCN":"以结果为宾语，从结果往回看，而不是从原因往前看。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the pebble and the pond, the standing water, the new port and the old photograph.","cn":"正常联想使用石子与池塘、积水、新港口与旧照片四个场景。"},"normal":[{"en":"A pebble dropped into still water: one small ring, then wider ones reaching the edge.","cn":"石子落进静水：先一圈小波纹，随后更大的波纹一路推到池边。"},{"en":"A puddle behind a wall that becomes a mosquito nursery.","cn":"墙后的一摊积水，成了蚊子的育婴房。"},{"en":"A new port, and a row of repair shops opening beside it.","cn":"新港口开张，旁边跟着开了一排修船铺。"},{"en":"A page missing from a ledger, and every later entry doubted.","cn":"账簿少了一页，后面的每一条都变得可疑。"},{"en":"A photograph that brings back a loss one had stopped feeling daily.","cn":"一张照片，把早已不再天天想起的失去又带了回来。"}],"abstract":[{"en":"A rise is a beginning that keeps going after the hand is gone.","cn":"升起，是手松开之后仍然继续的开始。"},{"en":"Small causes with long wakes are the hardest kind to trace back.","cn":"小原因拖出长尾迹，最难回溯。"},{"en":"The phrase never says the cause was intended, which is why it fits accidents and discoveries alike.","cn":"这个短语从不交代原因是否有意，因此事故与发现都适用。"}]},"examples":[{"en":"A single ambiguous word may give rise to two opposite readings.","cn":"一个含义模糊的词，可能引出两种相反的理解。"},{"en":"Rapid irrigation can give rise to salt buildup in the soil.","cn":"快速灌溉可能引起土壤盐分累积。"},{"en":"The discovery may give rise to a whole new class of materials.","cn":"这一发现可能催生一整类新材料。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「基夫 赖兹 图」：把「让某物升起」记成石子落水，第一圈很小，后面的波纹自己推到岸边——这就是引发","word":"give rise to"},"root":"前半为本族动词，意为「给予、授予」；后半为本族名词，意为「升起、兴起」。短语整体把原因画成一只放手让某物升起的手，强调后果自行扩散，不交代是否有意为之。","sensesIntro":{"en":"Nine senses let something rise: a dispute, a disease, a field, a doubt, a lawsuit, a misunderstanding, an industry, a chain of damage, and a feeling.","cn":"九个义项让某物升起：争论、疾病、学科、怀疑、诉讼、误解、产业、连锁损害与情感。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pebble dropped into still water, a small first ring, then wider rings travelling to the edge of the pool.","cn":"核心意象：石子落进静水，第一圈很小，随后更大的波纹一路推到池边。"},"chain":["GIVE THE PUSH","SOMETHING RISES","IT SPREADS","OTHERS REACT","EFFECTS GROW","A NEW STATE STANDS"],"branches":[{"senses":"01 · 05","en":"THE PUBLIC CLASH: a clause starts an argument, a vague contract starts a lawsuit.","cn":"公开的冲突：一条条款引起争论，一份含糊合同引起诉讼。"},{"senses":"02 · 08","en":"THE GROWING WAKE: standing water breeds mosquitoes, a dry summer feeds a beetle wave.","cn":"扩大的尾迹：积水养蚊，旱夏养甲虫。"},{"senses":"03 · 07","en":"THE NEW THING: a method opens a field, a port opens a cluster of shops.","cn":"新生之物：一种方法开出一门学科，一个港口开出一群作坊。"},{"senses":"04 · 06","en":"THE DOUBTFUL MIND: a missing page and a literal translation both plant a wrong picture.","cn":"起疑的心：缺页与直译，都在心里种下错误的画面。"},{"senses":"09","en":"THE STIRRED FEELING: a photograph raises a loss that had gone quiet.","cn":"被搅动的情感：一张照片让沉寂的失去重新升起。"}]},"affixes":{"intro":{"en":"Both halves are native English, so the family is short and concrete: a giving verb, a rising verb, and their forms.","cn":"两部分都是本族英语，因此词族短而具体：一个「给予」动词、一个「升起」动词及其形式。"},"latinIntro":{"en":"No Latin source is involved in either half, so the Latin list is left empty and the native forms are given instead.","cn":"两部分都不涉及拉丁语来源，因此拉丁词表留空，改列本族形式。"},"items":[{"word":"give","structure":"Old English verb","meaning":"to grant, to hand over","meaningCN":"给予；交给","example":"The first half of the phrase.","exampleCN":"短语的前半。"},{"word":"rise","structure":"Old English verb and noun","meaning":"to move upward","meaningCN":"向上升起","example":"The second half of the phrase.","exampleCN":"短语的后半。"},{"word":"giefan","structure":"Old English form","meaning":"to give","meaningCN":"给予","example":"The oldest recorded form of the giving verb.","exampleCN":"给予动词最古老的记录形式。"},{"word":"risan","structure":"Old English form","meaning":"to rise","meaningCN":"升起","example":"The oldest recorded form of the rising verb.","exampleCN":"升起动词最古老的记录形式。"},{"word":"-s","structure":"verb ending","meaning":"third person singular","meaningCN":"第三人称单数","example":"It marks a singular subject in the present.","exampleCN":"它标出现在时的单数主语。"},{"word":"-ing","structure":"verb ending","meaning":"ongoing action","meaningCN":"进行中的动作","example":"It forms the participle of the phrase.","exampleCN":"它构成短语的现在分词。"},{"word":"given","structure":"irregular form","meaning":"past participle","meaningCN":"过去分词","example":"The giving verb keeps an old strong form.","exampleCN":"给予动词保留了古老的强变化形式。"},{"word":"to","structure":"preposition","meaning":"toward, into","meaningCN":"朝向；进入","example":"It points the rise at what is produced.","exampleCN":"它把「升起」指向所产生之物。"}],"latinEntries":[],"derivatives":[{"word":"rise","pos":"n./v.","zh":"短语中的核心名词兼动词，义为「升起」"},{"word":"rising","pos":"adj./n.","zh":"由分词转作形容词，义为「上升的」"},{"word":"risen","pos":"v.","zh":"核心动词的过去分词"},{"word":"giver","pos":"n.","zh":"由给予动词加施事词尾构成，义为「给予者」"}]}},{"word":"have an impact on","ipa_uk":"/hæv ən ˈɪmpækt ɒn/","ipa_us":"/hæv ən ˈɪmpækt ɑːn/","definition_zh":"对……有影响；对……产生作用；冲击……；影响……的程度","definition_en":"to produce an effect on something, whether a strong one or a limited one, and whether intended or not","core_image":"一枚铁球从架上荡下，撞上一块薄板，板面凹进去一小块，凹痕的边缘向外散开","scene":"评估会上，一张曲线图被投到墙上，显示某项补贴实施后几个行业的变化。The subsidy may have an impact on small farms more than on large ones.","sceneCN":"这里指对某类对象产生作用（第 1 个义项：对结果或群体产生影响）；句意为这项补贴对小农场的影响可能大于对大农场的影响。图中可辨识物件：投影曲线、补贴文件、农场分布图、记号笔。","pos":[{"tag":"v. phr.","zh":"对……有影响（及物动词短语，后接受影响的对象）"},{"tag":"v. phr.","zh":"对……产生作用；冲击……（可用于物理碰撞或抽象作用）"}],"collocations":[{"phrase":"have an impact on growth","zh":"对增长有影响"},{"phrase":"have an impact on health","zh":"对健康有影响"},{"phrase":"have an impact on employment","zh":"对就业有影响"},{"phrase":"have an impact on the environment","zh":"对环境有影响"},{"phrase":"have an impact on decision making","zh":"对决策有影响"},{"phrase":"have an impact on the outcome","zh":"对结果有影响"}],"forms":[{"label":"三单","form":"has an impact on"},{"label":"过去式","form":"had an impact on"},{"label":"过去分词","form":"had an impact on"},{"label":"现在分词","form":"having an impact on"},{"label":"情态后原形","form":"have an impact on"}],"derivatives":[{"word":"impact","pos":"n./v.","zh":"短语中的核心名词兼动词，义为「冲击；影响」"},{"word":"impacted","pos":"adj.","zh":"由名词加过去分词词尾构成，义为「受影响的；压紧的」"},{"word":"impactful","pos":"adj.","zh":"由名词加形容词尾构成，义为「有冲击力的」，多用于评论语体"},{"word":"impaction","pos":"n.","zh":"由动词加名词尾构成，义为「嵌塞；压紧」，多用于医学"}],"senses":[{"no":"01","title":"Influence an outcome","titleCN":"对结果产生影响","definition":"to change the course or the size of a result","definitionCN":"改变结果的方向或大小","example":"A small change in the interest rate can have an impact on housing starts.","exampleCN":"利率的小幅变动，可能对新屋开工产生影响。","why":"The noun came from a word for driving something in; an effect that drives into a situation leaves a mark there.","whyCN":"核心名词出自表示「把某物打进去」的词；打进局面的作用会在那里留下痕迹。"},{"no":"02","title":"Change how people work","titleCN":"影响工作方式","definition":"to alter the way people carry out their work","definitionCN":"改变人们开展工作的方式","example":"Automation may have an impact on the number of clerks in the office.","exampleCN":"自动化可能影响办公室职员的人数。","why":"A machine driven into an office leaves a dent in the number of hands needed.","whyCN":"机器撞进办公室，在所需人手数目上留下凹痕。"},{"no":"03","title":"Affect living things","titleCN":"影响生物","definition":"to alter the timing, numbers or health of organisms","definitionCN":"改变生物的时序、数量或健康状况","example":"Warmer springs should have an impact on the timing of bird migration.","exampleCN":"更暖的春天会对鸟类迁徙的时间产生影响。","why":"A warmer spring strikes the timing of migration and leaves a dent in it.","whyCN":"更暖的春天撞在迁徙时序上，并在那里留下凹痕。"},{"no":"04","title":"Shape personal beliefs","titleCN":"影响个人观念","definition":"to alter what a person thinks or chooses","definitionCN":"改变一个人的想法或选择","example":"A single teacher can have an impact on a student's choice of study.","exampleCN":"一位老师就可能影响学生对专业的选择。","why":"A teacher's words strike a young mind and leave a dent that lasts.","whyCN":"老师的话撞在年轻的心上，留下持久的凹痕。"},{"no":"05","title":"Sway public opinion","titleCN":"影响公众舆论","definition":"to shift how an audience understands an event","definitionCN":"改变受众对某一事件的理解","example":"The broadcast may have an impact on how the audience reads the vote.","exampleCN":"这次播报可能影响受众如何解读那次表决。","why":"A broadcast strikes an audience's reading of a vote and bends it.","whyCN":"一次播报撞上受众对表决的解读，并使其弯折。"},{"no":"06","title":"Distort research results","titleCN":"影响研究结论","definition":"to introduce a change into measurements or estimates","definitionCN":"使测量或估计发生偏差","example":"A small error in the scale can have an impact on the final estimate.","exampleCN":"标尺上的一点误差，就可能影响最终的估计。","why":"An error in the scale strikes the final number and leaves its mark there.","whyCN":"标尺的误差撞在最终数字上，并在那里留下痕迹。"},{"no":"07","title":"Strike a structure physically","titleCN":"对结构产生撞击","definition":"literally to hit a body with force","definitionCN":"字面地以力量撞击一个物体","example":"A falling branch can have an impact on the roof during a storm.","exampleCN":"暴风中落下的树枝可能撞击屋顶。","why":"This is the oldest layer: the noun first named a collision before it named an influence.","whyCN":"这是最古老的一层：名词先指「碰撞」，后来才指「影响」。"},{"no":"08","title":"Damage something","titleCN":"造成损害","definition":"to cause harm or loss to a system or a place","definitionCN":"对某个系统或地方造成伤害或损失","example":"The spill may have an impact on the shellfish beds.","exampleCN":"这次泄漏可能对贝类养殖区造成损害。","why":"A spill strikes a shellfish bed where living things cannot move away.","whyCN":"泄漏撞在贝类养殖区，那里的生物无处避开。"},{"no":"09","title":"Be limited or large in degree","titleCN":"影响程度有限或显著","definition":"to affect something only slightly or very greatly, with the degree made explicit","definitionCN":"只轻微影响或极大影响，并明确点出程度","example":"The new rule should have an impact on only a few small firms.","exampleCN":"新规则应只影响少数小公司。","why":"A dent can be shallow or deep; the phrase can say how deep the dent is.","whyCN":"凹痕可深可浅；这个短语可以说出凹痕有多深。"}],"etymology":{"intro":{"en":"The phrase joins the native verb of holding with a noun borrowed from Latin, where it named something driven in by force. The modern sense of influence grew out of that physical collision in the twentieth century.","cn":"这个短语把本族表示「持有」的动词，与借自拉丁语、本指「以力量打入之物」的名词结合。现代「影响」义是在二十世纪从那次物理碰撞里长出来的。"},"items":[{"era":"LATIN PANGERE","en":"Pangere meant to fix, to drive in, to fasten, and it stands behind compact and pact as well.","cn":"这个词意为「固定、打入、系紧」，紧密的与契约诸词也由它而来。"},{"era":"LATIN IMPINGERE","en":"In- 'into' plus pangere produced impingere, to drive something into, to strike against.","cn":"表示「进入」的前缀加「打入」，构成「把某物撞进去、撞击」的动词。"},{"era":"LATIN IMPACTUS","en":"The participle named a thing struck against another, and English took it as the noun impact in the seventeenth century.","cn":"分词指「被撞上之物」，英语在十七世纪把它取作名词「碰撞」。"},{"era":"ENGLISH IMPACT, 17TH CENTURY","en":"The noun first meant a collision or a striking together, and it kept that physical sense for centuries.","cn":"这个名词最初指「碰撞、相撞」，这一物理义延续了几个世纪。"},{"era":"SENSE OF INFLUENCE, 20TH CENTURY","en":"The figurative sense of a strong effect became dominant in the twentieth century and is often criticised as vague in academic writing. The exact first citation is uncertain.","cn":"表示「强烈作用」的比喻义在二十世纪占据主导，并常被批评为学术写作中含义模糊。最早书证年代不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin driving-in word and its derivatives; the second group holds other verbs and phrases of influence, including the plainer twin of this phrase.","cn":"第一组共享拉丁「打入」之词及其派生词；第二组是其他表示「影响」的动词与短语，其中包含本短语更朴素的对应说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"impact","ipa":"/ˈɪmpækt/","tag":"the noun alone","definition":"The noun can stand alone as a subject or object, as in the impact was small; the phrase adds the affected party.","definitionCN":"名词可单独作主语或宾语，如「影响很小」；短语则补出受影响的一方。"},{"word":"impacted","ipa":"/ɪmˈpæktɪd/","tag":"the adjective","definition":"It describes something already affected or tightly wedged; it is not a substitute for the phrase.","definitionCN":"形容已被影响或紧紧嵌住的东西，不能替代本短语。"},{"word":"impactful","ipa":"/ɪmˈpæktfl/","tag":"the derived adjective","definition":"A recent coinage for having a strong effect; many style guides prefer a plain alternative.","definitionCN":"晚近造出的形容词，表示「有强烈作用」；许多体例指南更倾向朴素的替代说法。"},{"word":"impaction","ipa":"/ɪmˈpækʃn/","tag":"the technical noun","definition":"It is used in medicine and geology for material wedged in place, not for social influence.","definitionCN":"医学与地质学中指尖塞、压紧之物，不用于社会影响。"}]},{"heading":"NEAR MEANING","entries":[{"word":"have an effect on","ipa":"/hæv ən ɪˈfekt ɒn/","tag":"plainer twin","definition":"The standard neutral phrase for influence; it avoids the vagueness that critics find in the impact wording.","definitionCN":"表示「影响」的中性标准短语，避开了批评者认为「冲击」说法含混的问题。"},{"word":"influence","ipa":"/ˈɪnfluəns/","tag":"general verb","definition":"A general verb for shaping decisions or beliefs; it is less physical and less emphatic.","definitionCN":"泛指影响决策或信念的动词，物理意味与强调意味都较弱。"},{"word":"shape","ipa":"/ʃeɪp/","tag":"form the outcome","definition":"It stresses giving form to a result rather than merely changing it.","definitionCN":"强调给结果以形状，而不只是改变它。"},{"word":"bear on","ipa":"/beə ɒn/","tag":"be relevant to","definition":"A formal phrase for being relevant to a question; it does not necessarily imply a strong effect.","definitionCN":"正式表示「与某问题相关」，不一定含「作用强烈」之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the swinging iron ball, the projected curve, the weather shift and the falling branch.","cn":"正常联想使用摆动的铁球、投影曲线、气候变动与落下的树枝四个场景。"},"normal":[{"en":"An iron ball swings down and dents a thin plate, the rim of the dent spreading outward.","cn":"铁球荡下，把薄板撞出一个凹痕，凹痕边缘向外散开。"},{"en":"A curve thrown on the wall at an evaluation meeting.","cn":"评估会上，一张曲线被投到墙上。"},{"en":"A warmer spring, and birds arriving a week early.","cn":"春天更暖，鸟早来了一周。"},{"en":"One teacher who changes what a student wants to study.","cn":"一位老师，改变了学生想学的专业。"},{"en":"A branch falling on a roof during a storm.","cn":"暴风中一根树枝落在屋顶上。"}],"abstract":[{"en":"Impact is a dent left by something else, never a property of the thing alone.","cn":"影响是别的东西留下的凹痕，从不是某物自身的属性。"},{"en":"The word first meant collision, and every figurative use still carries a trace of force.","cn":"这个词先指碰撞，每个比喻用法都还带着一点力。"},{"en":"An effect named as impact invites the question: how large, on whom, for how long?","cn":"用「冲击」来命名的作用，会招来三个问题：多大、对谁、多久。"}]},"examples":[{"en":"The new tariff may have an impact on the price of imported steel.","cn":"新关税可能影响进口钢材的价格。"},{"en":"A long drought can have an impact on the following year's seed crop.","cn":"长期干旱可能影响下一年的种子收成。"},{"en":"The report should state how large an impact the policy can have on rural incomes.","cn":"报告应说明该政策能对农村收入产生多大影响。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「哈夫 恩 因帕克特 昂」：把「打入」记成铁球撞薄板，板上留下凹痕——凹痕就是影响","word":"have an impact on"},"root":"前半为本族动词，意为「持有、具有」；后半名词出自拉丁语，由表示「进入」的前缀加表示「打入、固定」的动词构成，本义是「撞击、碰撞」，现代「影响」义为晚近引申。短语后接介词引出受影响的一方。","sensesIntro":{"en":"Nine senses follow one dent: an outcome, a workplace, a species, a belief, an audience, an estimate, a roof, a shellfish bed, and a stated degree.","cn":"九个义项都跟着同一处凹痕：结果、工作场所、物种、信念、受众、估计、屋顶、贝类养殖区与明确的程度。"},"semanticMap":{"core":{"en":"CORE IMAGE: an iron ball swinging down onto a thin plate, a dent forming, its rim spreading outward.","cn":"核心意象：铁球荡下撞上薄板，板上出现凹痕，凹痕的边缘向外散开。"},"chain":["STRIKE","LEAVE A DENT","THE DENT SPREADS","OTHERS FEEL IT","THE COURSE CHANGES","THE SIZE IS NAMED"],"branches":[{"senses":"01 · 02 · 09","en":"THE MEASURED EFFECT: a rate change, an office of clerks, a rule touching few firms, all with a size to state.","cn":"可测的作用：利率变动、职员人数、只触及少数公司的规则，都有大小可说。"},{"senses":"03 · 08","en":"THE LIVING AND THE FRAGILE: migrating birds and shellfish beds take the blow.","cn":"生物与脆弱之处：迁徙的鸟与贝类养殖区承受这一击。"},{"senses":"04 · 05","en":"THE MIND MOVED: a teacher shapes a choice, a broadcast shapes a reading.","cn":"被推动的心：老师塑造选择，播报塑造解读。"},{"senses":"06","en":"THE DISTORTED NUMBER: an error in the scale bends the final estimate.","cn":"被扭偏的数字：标尺误差使最终估计走形。"},{"senses":"07","en":"THE PHYSICAL BLOW: a branch strikes a roof in a storm.","cn":"物理的一击：暴风中树枝撞上屋顶。"}]},"affixes":{"intro":{"en":"The family joins a native holding verb to a Latin noun of driving in; the endings build the adjective of being affected and the newer adjective of having force.","cn":"这个词族把本族「持有」动词与拉丁语「打入」名词结合；词尾造出「受影响」形容词与较新的「有冲击力」形容词。"},"latinIntro":{"en":"Latin pangere and impingere supplied the noun impactus, which English borrowed directly in the seventeenth century.","cn":"拉丁语的「打入」与「撞入」动词提供了名词，英语在十七世纪直接借入。"},"items":[{"word":"in-","structure":"prefix","meaning":"into","meaningCN":"进入","example":"It marks the force as driven into something.","exampleCN":"它标出力被打进某物。"},{"word":"pangere","structure":"Latin verb","meaning":"to fix, to drive in","meaningCN":"固定；打入","example":"The driving verb behind the noun.","exampleCN":"名词背后的「打入」动词。"},{"word":"impingere","structure":"Latin verb","meaning":"to strike against, drive into","meaningCN":"撞击；撞入","example":"The verb that produced the noun.","exampleCN":"产生该名词的动词。"},{"word":"impactus","structure":"Latin participle","meaning":"struck against","meaningCN":"被撞上的","example":"The participle English borrowed as a noun.","exampleCN":"英语借作名词的分词。"},{"word":"impact","structure":"English noun and verb","meaning":"a collision, an effect","meaningCN":"碰撞；影响","example":"The borrowed word at the centre of the phrase.","exampleCN":"短语中心的借入词。"},{"word":"-ed","structure":"adjective ending","meaning":"having undergone","meaningCN":"已经受……的","example":"It forms the adjective of what has been affected.","exampleCN":"它构成「已受影响」的形容词。"},{"word":"-ful","structure":"adjective ending","meaning":"full of, having","meaningCN":"充满；具有","example":"It forms the newer adjective of strong effect.","exampleCN":"它构成表示「作用强烈」的较新形容词。"},{"word":"-ion","structure":"noun ending","meaning":"action or state","meaningCN":"动作；状态","example":"It forms the technical noun of wedging.","exampleCN":"它构成表示「嵌塞」的技术名词。"}],"latinEntries":[{"word":"pangere","structure":"Latin verb","meaning":"to fix, drive in","meaningCN":"固定；打入"},{"word":"impingere","structure":"Latin verb","meaning":"to strike against","meaningCN":"撞击"},{"word":"impactus","structure":"Latin participle","meaning":"struck against","meaningCN":"被撞上的"}],"derivatives":[{"word":"impact","pos":"n./v.","zh":"核心名词兼动词，义为「冲击；影响」"},{"word":"impacted","pos":"adj.","zh":"由名词加过去分词词尾构成，义为「受影响的」"},{"word":"impactful","pos":"adj.","zh":"由名词加形容词尾构成，义为「有冲击力的」"},{"word":"impaction","pos":"n.","zh":"由动词加名词尾构成，义为「嵌塞」"}]}},{"word":"have access to","ipa_uk":"/hæv ˈækses tə/","ipa_us":"/hæv ˈækses tə/","definition_zh":"有权使用；可以接触；能够获得；可以进入；有……的通道","definition_en":"to be able or entitled to reach, use or obtain something, whether a place, a service, information or a person","core_image":"一道闸门半开，门禁灯由红转绿，持卡人推门而入，里面的一排书架与资料柜都向他敞开","scene":"阅览室门口，管理员核对了证件，把一张临时卡递给来访的学生，告诉他哪些书架可以自己去取。Only enrolled students may have access to the closed stacks.","sceneCN":"这里指被允许进入并使用特定资源（第 1 个义项：有权使用某处资源或设施）；句意为只有注册在籍的学生才可以使用闭架书库。图中可辨识物件：门禁读卡器、临时卡、闭架书库、管理员证。","pos":[{"tag":"v. phr.","zh":"有权使用；能够获得（及物动词短语，后接资源、服务或信息）"},{"tag":"v. phr.","zh":"可以进入；可以接近（后接场所、人群或机构）"}],"collocations":[{"phrase":"have access to clean water","zh":"能获得清洁用水"},{"phrase":"have access to information","zh":"能获取信息"},{"phrase":"have access to health care","zh":"能获得医疗服务"},{"phrase":"have access to education","zh":"有受教育的机会"},{"phrase":"have access to the archive","zh":"可以使用档案"},{"phrase":"have access to decision makers","zh":"能接触到决策者"},{"phrase":"have access to the market","zh":"有市场准入"}],"forms":[{"label":"三单","form":"has access to"},{"label":"过去式","form":"had access to"},{"label":"过去分词","form":"had access to"},{"label":"现在分词","form":"having access to"},{"label":"情态后原形","form":"have access to"}],"derivatives":[{"word":"access","pos":"n./v.","zh":"短语中的核心名词兼动词，义为「通道；使用权；进入」"},{"word":"accessible","pos":"adj.","zh":"由名词加「可……的」词尾构成，义为「可接近的；易理解的」"},{"word":"accessibility","pos":"n.","zh":"由形容词加名词尾构成，义为「可及性；可达性」"},{"word":"accession","pos":"n.","zh":"由动词加名词尾构成，义为「就任；加入；入藏」"},{"word":"accessed","pos":"adj.","zh":"由动词加过去分词词尾构成，义为「被访问过的」"}],"senses":[{"no":"01","title":"Entitled to use a resource","titleCN":"有权使用某项资源","definition":"to have the right or the means to use a facility or a supply","definitionCN":"拥有使用某项设施或供应的权利或条件","example":"Every resident should have access to clean water.","exampleCN":"每位居民都应能获得清洁用水。","why":"The core verb meant to go near, and a right of use is a door left open for one to approach.","whyCN":"核心动词本义是「走近」，而使用权就是一扇为你留着、让你靠近的门。"},{"no":"02","title":"Able to reach information","titleCN":"能够获取信息","definition":"to be able to consult records, data or documents","definitionCN":"能够查阅记录、数据或文件","example":"Researchers may have access to the archive only with written permission.","exampleCN":"研究人员只有获得书面许可，才可以查阅该档案。","why":"A record room is entered by permission, and the way in is the permission.","whyCN":"记录室凭许可进入，而那条进去的路就是许可。"},{"no":"03","title":"Able to obtain care","titleCN":"能够获得医疗服务","definition":"to be able to reach and receive medical treatment","definitionCN":"能够到达并接受医疗","example":"Rural families should have access to a clinic within an hour's drive.","exampleCN":"农村家庭应能在一小时车程内获得诊所服务。","why":"A clinic within an hour is a door that can actually be reached.","whyCN":"一小时车程内的诊所，是一扇真正够得着的门。"},{"no":"04","title":"Able to receive education","titleCN":"有受教育的机会","definition":"to be able to attend and use schools or courses","definitionCN":"能够进入并使用学校或课程","example":"Girls in the district can have access to the same schools as boys.","exampleCN":"该地区的女孩可以和男孩进入同样的学校。","why":"A school place is a door held open for a child.","whyCN":"一个学位，是为孩子留着的一扇门。"},{"no":"05","title":"Able to reach a place","titleCN":"可以到达某地","definition":"to have a route by which a place can be reached","definitionCN":"拥有通往某处的路径","example":"The upper valley may have access to the sea through one narrow pass.","exampleCN":"上游河谷可能通过一个狭窄山口通向大海。","why":"This is the physical layer: access as a way in, before it became a right.","whyCN":"这是物理层面：先有「进去的路」，后来才有「进去的权利」。"},{"no":"06","title":"Hold the right to enter","titleCN":"拥有进入权限","definition":"to be permitted to enter a restricted place","definitionCN":"被允许进入受限制的场所","example":"Only two technicians should have access to the sealed room.","exampleCN":"只有两名技师应被允许进入那间密封室。","why":"Two keyholders are two keys to the same locked door.","whyCN":"两个持钥人，就是同一扇锁门上的两把钥匙。"},{"no":"07","title":"Able to use samples or records","titleCN":"可以使用样本或档案","definition":"to be allowed to handle material kept for research","definitionCN":"被允许接触为研究保存的材料","example":"Visiting scholars can have access to the fossil collection.","exampleCN":"访问学者可以使用这批化石藏品。","why":"A fossil collection opens to visiting scholars by written permission.","whyCN":"化石藏品凭书面许可向访问学者敞开。"},{"no":"08","title":"Able to enter a market","titleCN":"有市场准入","definition":"to be allowed to sell or compete in a market","definitionCN":"被允许在某一市场销售或竞争","example":"Small exporters may have access to the regional market under the new terms.","exampleCN":"小型出口商在新条款下可能获得区域市场准入。","why":"A market door opens to exporters when the terms admit them.","whyCN":"条款准许时，市场之门向出口商打开。"},{"no":"09","title":"Able to reach decision makers","titleCN":"能接触到决策者","definition":"to be able to meet or speak with people who decide","definitionCN":"能够见到或向做决定的人表达","example":"Local groups should have access to the officials who set the budget.","exampleCN":"本地团体应能接触到制定预算的官员。","why":"A local group that can sit with budget makers has reached the inner door.","whyCN":"能与编预算者同坐的本地团体，已经走到内门。"}],"etymology":{"intro":{"en":"The phrase joins the native verb of holding to a Latin noun built from to plus going. Access is first a way of going near, and the phrase turns that way into a capacity, a permission or a right.","cn":"这个短语把本族表示「持有」的动词，与拉丁语中由「向」加「行走」构成的名词结合。通道首先是「走近的路」，短语则把这条路变成能力、许可或权利。"},"items":[{"era":"LATIN CEDERE","en":"Cedere meant to go, to move, to yield, and it stands behind proceed, concede and exceed.","cn":"这个词意为「走、移动、让出」，行进、让步与超过诸词都由它而来。"},{"era":"LATIN ACCEDERE","en":"Ad- 'to' plus cedere produced accedere, to go near, to approach, to come to.","cn":"表示「朝向」的前缀加「走」，构成「走近、接近、来到」的动词。"},{"era":"LATIN ACCESSUS","en":"The noun named a coming near, a way of approach, and later a fit or an attack of illness.","cn":"相应的名词指「走近、接近之路」，后来也指疾病的发作。"},{"era":"ENGLISH ACCESS, 14TH CENTURY","en":"English took the noun for a way in or an approach, and the right of entry came later.","cn":"英语在十四世纪引入这个名词，指「入口、接近」，表示「进入的权利」的用法后来才出现。"},{"era":"PHRASE OF RIGHT AND MEANS","en":"With the native verb of holding, the phrase came to cover both permission and practical ability. The exact first citation is uncertain.","cn":"与本族「持有」动词结合后，这个短语兼指许可与实际能力。最早书证年代不确定。"}]},"similar":{"note":{"en":"The first group shares the Latin going word; the second group holds other ways of saying that something can be reached or used.","cn":"第一组共享拉丁「行走」之词；第二组是其他表示「可以到达或使用」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"access","ipa":"/ˈækses/","tag":"the noun alone","definition":"It names the way in or the right itself, as in a service with wide access; the phrase puts a holder in front of it.","definitionCN":"名词指「入口」或「权利」本身，如覆盖面广的服务；短语则在它前面加上持有者。"},{"word":"accessible","ipa":"/əkˈsesəbl/","tag":"the adjective","definition":"It describes a place or a text that can be reached or understood; it is a property, not a possession.","definitionCN":"形容某地或某文本可达、可懂；它是性质，不是谁持有之物。"},{"word":"accession","ipa":"/əkˈseʃn/","tag":"same root, different noun","definition":"It means coming to office or adding to a collection, not the ability to use something.","definitionCN":"意为「就任」或「入藏」，而不是「使用的能力」。"},{"word":"exceed","ipa":"/ɪkˈsiːd/","tag":"same Latin going verb, different prefix","definition":"From beyond plus going: it means to go past a limit, sharing the root but not the sense of entry.","definitionCN":"由「越过」加「走」构成，意为「超出限度」，共享词根，却不含「进入」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"be able to use","ipa":"/bi ˈeɪbl tə juːz/","tag":"plain ability","definition":"The plain phrase for having the capacity to use something; it says nothing about permission.","definitionCN":"朴素表示「有能力使用」，不涉及许可。"},{"word":"be entitled to","ipa":"/bi ɪnˈtaɪtld tə/","tag":"legal right","definition":"It stresses a right that can be claimed, often in law or policy, without the physical sense of entry.","definitionCN":"强调可主张的权利，常用于法律或政策，不含物理上的进入。"},{"word":"reach","ipa":"/riːtʃ/","tag":"get to","definition":"A general verb for getting to a place or a person; it lacks the sense of a granted right.","definitionCN":"泛指到达某地或找到某人，不含「被授予的权利」。"},{"word":"gain entry to","ipa":"/ɡeɪn ˈentri tə/","tag":"get inside","definition":"It focuses on the act of getting in through a door or a barrier, closer to the physical senses.","definitionCN":"强调穿过门或障碍进去的动作，较接近物理义项。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the gate reader, the closed stacks, the rural clinic and the narrow pass.","cn":"正常联想使用门禁读卡器、闭架书库、乡村诊所与狭窄山口四个场景。"},"normal":[{"en":"A gate half open, a light turning from red to green, a reader passing a card.","cn":"闸门半开，指示灯由红转绿，读卡人递过一张卡。"},{"en":"A student handed a temporary card and told which shelves are open to her.","cn":"学生拿到一张临时卡，被告知哪些书架向她开放。"},{"en":"A village an hour from the nearest clinic, and a road that makes the hour possible.","cn":"村庄离最近诊所一小时车程，而这条路让这一小时成为可能。"},{"en":"One narrow pass between the upper valley and the sea.","cn":"上游河谷与大海之间，只有一道狭窄山口。"},{"en":"A local group sitting in the same room as the officials who set the budget.","cn":"本地团体与编预算的官员，坐在同一间屋里。"}],"abstract":[{"en":"Access is a door plus a key: the door alone is only a route.","cn":"可及性是门加钥匙：只有门，那只是路。"},{"en":"The same word covers a right and a road, because both decide who may come near.","cn":"同一个词既指权利也指道路，因为两者都决定谁能靠近。"},{"en":"What is open to everyone stops being a privilege and becomes an infrastructure.","cn":"对所有人开放之后，特权就变成了基础设施。"}]},"examples":[{"en":"Every patient should have access to a copy of the record held about them.","cn":"每位患者都应有权拿到关于自己的记录副本。"},{"en":"Small firms may have access to the fund only through a local bank.","cn":"小公司可能只能通过本地银行获得这笔基金。"},{"en":"The public can have access to the gardens on two days each month.","cn":"公众每月有两天可以进入这些花园。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「哈夫 阿克塞斯 图」：把「走近」记成闸门红灯转绿、刷卡进门——门开了，路就通了","word":"have access to"},"root":"前半为本族动词，意为「持有」；后半名词出自拉丁语，由表示「朝向」的前缀加表示「行走」的动词构成，本义是「走近、接近之路」，后引申为「进入的权利」。短语兼指许可与实际能力。","sensesIntro":{"en":"Nine senses move from a right to a road: water, information, care, schooling, a pass to the sea, a sealed room, a fossil collection, a market and a minister's door.","cn":"九个义项从权利走到道路：水、信息、医疗、教育、通海的山口、密封室、化石藏品、市场与官员的门。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gate half open, the reader turning green, a card passed, and the shelves beyond opening to the holder.","cn":"核心意象：闸门半开，读卡器转绿，卡片递过，里面的书架向持卡人敞开。"},"chain":["COME NEAR","FIND A WAY IN","PASS THE GATE","BE ALLOWED","USE WHAT IS THERE","OBTAIN THE SHARE"],"branches":[{"senses":"01 · 03 · 04","en":"THE BASIC NEED: water, care and schooling are rights before they are routes.","cn":"基本所需：水、医疗与教育，先被当作权利，然后才被当作道路。"},{"senses":"02 · 07","en":"THE RECORD ROOM: an archive and a fossil collection open only to those with permission.","cn":"记录室：档案馆与化石藏品，只对获准者开放。"},{"senses":"05 · 06","en":"THE PHYSICAL GATE: a pass to the sea, a sealed room with two keyholders.","cn":"物理的门：通海的山口，只有两名持钥者的密封室。"},{"senses":"08","en":"THE MARKET DOOR: an exporter admitted to a regional market under new terms.","cn":"市场之门：出口商在新条款下被准入区域市场。"},{"senses":"09","en":"THE OFFICIAL DOOR: a local group able to sit with those who set the budget.","cn":"官员之门：本地团体能与编预算者同坐一室。"}]},"affixes":{"intro":{"en":"The family is built on a Latin going verb with a prefix of approach; the endings name the way in, the quality of being reachable and the act of entering office.","cn":"这个词族建立在拉丁语「行走」动词上，前缀表示「朝向」；词尾命名入口、可达的性质与就任的动作。"},"latinIntro":{"en":"Latin accedere and accessus passed through French into English, which added its own adjective and noun endings.","cn":"拉丁语的「走近」动词与名词经法语进入英语，英语加上自己的形容词与名词词尾。"},"items":[{"word":"ad-","structure":"prefix","meaning":"to, toward","meaningCN":"朝向；向","example":"It marks the movement as coming near.","exampleCN":"它标出「走近」这一移动。"},{"word":"cedere","structure":"Latin verb","meaning":"to go, to move","meaningCN":"行走；移动","example":"The going verb at the base.","exampleCN":"底层的「行走」动词。"},{"word":"accedere","structure":"Latin verb","meaning":"to go near, approach","meaningCN":"走近；接近","example":"The direct source of the English noun.","exampleCN":"英语名词的直接来源。"},{"word":"accessus","structure":"Latin noun","meaning":"a coming near, a way of approach","meaningCN":"走近；接近之路","example":"The noun English borrowed.","exampleCN":"英语借入的名词。"},{"word":"-ible","structure":"adjective ending","meaning":"able to be","meaningCN":"可被……的","example":"It forms the adjective for what can be reached.","exampleCN":"它构成「可达」的形容词。"},{"word":"-ity","structure":"noun ending","meaning":"state or quality","meaningCN":"状态；性质","example":"It forms the noun of reachability.","exampleCN":"它构成表示「可达性」的名词。"},{"word":"-ion","structure":"noun ending","meaning":"action or result","meaningCN":"动作；结果","example":"It forms the noun of coming to office.","exampleCN":"它构成表示「就任」的名词。"},{"word":"to","structure":"preposition","meaning":"toward","meaningCN":"朝向；对于","example":"It points the access at what is reached.","exampleCN":"它把「可及」指向所达之物。"}],"latinEntries":[{"word":"cedere","structure":"Latin verb","meaning":"to go, move","meaningCN":"行走；移动"},{"word":"accedere","structure":"Latin verb","meaning":"to go near, approach","meaningCN":"走近；接近"},{"word":"accessus","structure":"Latin noun","meaning":"a coming near","meaningCN":"走近；接近"}],"derivatives":[{"word":"access","pos":"n./v.","zh":"核心名词兼动词，义为「通道；使用权」"},{"word":"accessible","pos":"adj.","zh":"由名词加「可……的」词尾构成，义为「可接近的」"},{"word":"accessibility","pos":"n.","zh":"由形容词加名词尾构成，义为「可及性」"},{"word":"accession","pos":"n.","zh":"由动词加名词尾构成，义为「就任；入藏」"}]}}]);
